export enum ToolType {
  STRATEGY = 'Strategy',
  EDUCATIONAL = 'Educational Post',
  SALES = 'Sales Post',
  AD_COPY = 'Ad Copy',
  CONSULTATION = 'Consultation'
}

export interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface GenerationRequest {
  tool: ToolType;
  topic: string;
  audience?: string;
  tone?: string;
  additionalContext?: string;
}

export interface GeminiConfig {
  apiKey: string;
}

import { GoogleGenAI, Chat } from "@google/genai";
import { ToolType, GenerationRequest } from "../types";

const SYSTEM_INSTRUCTION = `
You are the Chief Marketing Officer (CMO) and Lead Content Strategist for "Shwe Thai" (shwethai.com).

**Brand Profile:**
- **Core Service:** Connecting Myanmar patients with world-class hospitals in Thailand (Medical Tourism).
- **USP:** Safety, Transparency, Peace of Mind (စိတ်အေးချမ်းသာမှု), and Ease of Access.
- **Target Audience:** Myanmar citizens seeking better healthcare. They value trust above price.

**Your Role:**
1.  **Strategic Planning:** Analyze pain points, suggest channels (FB, Telegram, TikTok), outline customer journeys.
2.  **Content Creation:** 
    - Educational: Explain medical info simply and professionally.
    - Sales: Sell packages (Check-ups, IVF, Cancer treatment) using PAS or AIDA frameworks.
    - Tone: Warm, Professional, Reassuring, Respectful (use 'ခင်ဗျာ/ရှင်').
3.  **Ad Copywriting:** Focus on "Results" and "Safety".
4.  **Consultation:** Act as a senior consultant.

**Formatting Rules:**
- Use Markdown (Bold headers, bullet points).
- **CRITICAL:** Use Myanmar Unicode for all public-facing content.
- Include emojis (🏥 🩺 ✈️).
- Always end with a CTA to shwethai.com or Messenger.
`;

class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat | null = null;

  constructor() {
    // API Key is injected by the environment
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-flash-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const model = this.getModel();

    let prompt = "";

    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a marketing strategy for: "${request.topic}". 
        Target Audience: ${request.audience || "General Public"}.
        Context: ${request.additionalContext || "None"}.

        Analyze pain points, suggest channels, and outline a full Customer Journey.`;
        break;

      case ToolType.EDUCATIONAL:
        prompt = `Write an EDUCATIONAL Facebook post about: "${request.topic}".
        Target Audience: ${request.audience || "Patients seeking info"}.
        Tone: Empathetic, Clear, Professional.
        Context: ${request.additionalContext || "None"}.

        Explain the condition/procedure simply. Use empathy.`;
        break;

      case ToolType.SALES:
        prompt = `Write a SALES Facebook post for: "${request.topic}".
        Framework: Use PAS (Problem-Agitation-Solution) or AIDA.
        Target Audience: ${request.audience || "Potential customers"}.
        Context: ${request.additionalContext || "None"}.

        Focus on safety, transparency, and ease of access.`;
        break;

      case ToolType.AD_COPY:
        prompt = `Write Facebook Ad Copy for: "${request.topic}".
        Include:
        1. Primary Text (2 variations)
        2. Headlines (3 options)
        3. Visual/Creative Suggestions.

        Focus on "Trust" and "Results".`;
        break;

      case ToolType.CONSULTATION:
        // This should theoretically go through chat, but if called as single gen:
        prompt = `Consultation request: ${request.topic}. ${request.additionalContext}`;
        break;
    }

    try {
      const response = await this.ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
        },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Gemini Generation Error:", error);
      throw error;
    }
  }

  async startChat(): Promise<Chat> {
    this.chatSession = this.ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
    });
    return this.chatSession;
  }

  async sendMessage(message: string): Promise<string> {
    if (!this.chatSession) {
      await this.startChat();
    }
    if (!this.chatSession) {
        throw new Error("Failed to initialize chat");
    }
    const response = await this.chatSession.sendMessage({ message });
    return response.text || "";
  }
}

export const geminiService = new GeminiService();

