          </div>
        )}
        {chatMessages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-2xl px-5 py-3 shadow-sm ${
              msg.role === 'user' 
                ? 'bg-thai-600 text-white rounded-br-none' 
                : 'bg-gray-100 text-gray-800 rounded-bl-none border border-gray-200'
            }`}>
              <FormattedText text={msg.text} />
              <p className={`text-[10px] mt-1 ${msg.role === 'user' ? 'text-thai-200' : 'text-gray-400'}`}>
                {msg.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
              </p>
            </div>
          </div>
        ))}
        {isGenerating && (
          <div className="flex justify-start">
             <div className="bg-gray-50 rounded-2xl px-4 py-3 border border-gray-100 flex space-x-2 items-center">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></div>
             </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-4 border-t bg-gray-50">
        <div className="flex space-x-2">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleChatSend()}
            placeholder="Type your message..."
            disabled={isGenerating}
            className="flex-1 px-4 py-3 bg-gray-800 text-white placeholder-gray-400 border border-gray-700 rounded-xl focus:ring-2 focus:ring-thai-500 focus:border-thai-500 outline-none"
          />
          <button 
            onClick={handleChatSend}
            disabled={!chatInput.trim() || isGenerating}
            className={`px-6 rounded-xl font-bold text-white transition-colors ${
              !chatInput.trim() || isGenerating
                ? 'bg-gray-300 cursor-not-allowed'
                : 'bg-thai-600 hover:bg-thai-700'
            }`}
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <Layout activeTool={activeTool} onToolChange={setActiveTool}>
      {activeTool === ToolType.CONSULTATION ? renderChat() : renderGenerator()}
    </Layout>
  );
};

