       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY:
        return {
          title: "Strategic Planner",
          desc: "Create comprehensive marketing strategies for new campaigns or services.",
          placeholder: "e.g., Launching a new comprehensive heart check-up package",
          topicLabel: "Campaign Topic"
        };
      case ToolType.EDUCATIONAL:
        return {
          title: "Educational Content Generator",
          desc: "Build trust with informative posts about medical conditions.",
          placeholder: "e.g., The importance of early cervical cancer screening",
          topicLabel: "Medical Topic"
        };
      case ToolType.SALES:
        return {
          title: "Sales Copy Generator",
          desc: "Convert interest into bookings with persuasive, safe copy.",
          placeholder: "e.g., Promotion for 30% off liver screening in Bangkok",
          topicLabel: "Promotion / Service"
        };
      case ToolType.AD_COPY:
        return {
          title: "Ad Creative Suite",
          desc: "Generate high-converting Facebook ad copy and headlines.",
          placeholder: "e.g., Second opinion services for orthopedics",
          topicLabel: "Ad Subject"
        };
      case ToolType.IMAGE_GENERATION:
        return {
          title: "AI Image Generator",
          desc: "Create relevant visual assets for your marketing posts.",
          placeholder: "e.g., A modern, clean hospital lobby with friendly staff greeting a patient",
          topicLabel: "Image Description"
        };
      default:
        return { title: "", desc: "", placeholder: "", topicLabel: "Topic" };
    }
  };

  const headerInfo = renderToolHeader();

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">
      {/* Input Section */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 h-fit sticky top-6">
        <div className="mb-6">
          <h2 className="text-2xl font-bold text-gray-900 mb-1">{headerInfo.title}</h2>
          <p className="text-gray-500 text-sm">{headerInfo.desc}</p>
        </div>

        <div className="space-y-5">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">
              {headerInfo.topicLabel} <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              placeholder={headerInfo.placeholder}
              className="w-full px-4 py-2 bg-gray-800 text-white placeholder-gray-400 border border-gray-700 rounded-lg focus:ring-2 focus:ring-thai-500 focus:border-thai-500 outline-none transition-all"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">
              {activeTool === ToolType.IMAGE_GENERATION ? "Style / Mood (Optional)" : "Target Audience (Optional)"}
            </label>
            <input
              type="text"
              value={audience}
              onChange={(e) => setAudience(e.target.value)}
              placeholder={activeTool === ToolType.IMAGE_GENERATION ? "e.g., Photorealistic, Warm, Professional" : "e.g., Women over 40, Patients with diabetes history"}
              className="w-full px-4 py-2 bg-gray-800 text-white placeholder-gray-400 border border-gray-700 rounded-lg focus:ring-2 focus:ring-thai-500 focus:border-thai-500 outline-none transition-all"
            />
          </div>

          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">
              Additional Context / Key Details (Optional)
            </label>
            <textarea
              value={context}
              onChange={(e) => setContext(e.target.value)}
              rows={4}
              placeholder={activeTool === ToolType.IMAGE_GENERATION ? "e.g., Ensure the lighting is bright and the colors match Shwe Thai branding (Gold/Blue)" : "e.g., Price is 5000 THB, includes free airport pickup. Emphasize the modern technology used."}
              className="w-full px-4 py-2 bg-gray-800 text-white placeholder-gray-400 border border-gray-700 rounded-lg focus:ring-2 focus:ring-thai-500 focus:border-thai-500 outline-none transition-all resize-none"
            />
          </div>

          <button
            onClick={handleGenerate}
            disabled={!topic || isGenerating}
            className={`w-full py-3 px-4 rounded-lg text-white font-semibold shadow-md flex items-center justify-center space-x-2 transition-all transform hover:-translate-y-0.5
              ${!topic || isGenerating 
                ? 'bg-gray-400 cursor-not-allowed' 
                : 'bg-gradient-to-r from-thai-600 to-thai-500 hover:from-thai-700 hover:to-thai-600'
              }`}
          >
            {isGenerating ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <span>{activeTool === ToolType.IMAGE_GENERATION ? "Generating Image..." : "Analyzing & Generating..."}</span>
              </>
            ) : (
              <>
                <span>{activeTool === ToolType.IMAGE_GENERATION ? "Generate Image" : "Generate Content"}</span>
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Output Section */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8 min-h-[500px] flex flex-col">
        <div className="flex items-center justify-between mb-6 pb-4 border-b border-gray-100">
           <h3 className="text-lg font-bold text-gray-800">Generated Output</h3>
           {generatedContent && (
             <button 
               onClick={() => navigator.clipboard.writeText(generatedContent)}
               className="text-sm text-thai-600 hover:text-thai-800 font-medium flex items-center space-x-1"
             >
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
               <span>Copy Text</span>
             </button>
           )}
           {generatedImage && (
             <a 
               href={generatedImage} 
               download="shwethai-generated-image.png"
               className="text-sm text-thai-600 hover:text-thai-800 font-medium flex items-center space-x-1"
             >
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
               <span>Download</span>
             </a>
           )}
        </div>

        <div className="flex-1">
          {generatedImage ? (
            <div className="flex items-center justify-center h-full">
              <img 
                src={generatedImage} 
                alt="Generated Marketing Visual" 
                className="max-w-full max-h-[500px] rounded-lg shadow-lg border border-gray-100 object-contain"
              />
            </div>
          ) : generatedContent ? (
            <div className="prose prose-sm max-w-none prose-p:my-2 prose-headings:text-thai-900">
              <FormattedText text={generatedContent} />
            </div>
          ) : (
             <div className="h-full flex flex-col items-center justify-center text-gray-400 space-y-4">
               <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center">
                 {activeTool === ToolType.IMAGE_GENERATION ? (
                   <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                 ) : (
                   <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                 )}
               </div>
               <p className="text-center max-w-xs">Enter your topic and details on the left to generate professional Shwe Thai marketing content.</p>
             </div>
          )}
        </div>
      </div>
    </div>
  );

  const renderChat = () => (
    <div className="flex flex-col h-[calc(100vh-6rem)] bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="p-4 border-b bg-gray-50 flex items-center justify-between">
         <div className="flex items-center space-x-3">
           <div className="w-10 h-10 rounded-full bg-gradient-to-br from-shwe-gold to-yellow-600 flex items-center justify-center shadow-sm">
             <span className="text-white font-bold text-lg">C</span>
           </div>
           <div>
             <h3 className="font-bold text-gray-900">Shwe Thai CMO Consultant</h3>
             <p className="text-xs text-gray-500">Ask for advice, strategy critiques, or brainstorming.</p>
           </div>
         </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-white">
        {chatMessages.length === 0 && (
          <div className="text-center text-gray-400 mt-20">
            <p className="mb-2">👋 Mingalarpar! I am your AI Marketing Consultant.</p>
            <p className="text-sm">Ask me how to improve our conversion rates or how to handle a specific patient objection.</p>
          </div>
        )}
        {chatMessages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-2xl px-5 py-3 shadow-sm ${
              msg.role === 'user' 
                ? 'bg-thai-600 text-white rounded-br-none' 
                : 'bg-gray-100 text-gray-800 rounded-bl-none border border-gray-200'
            }`}>
              <FormattedText text={msg.text} />
              <p className={`text-[10px] mt-1 ${msg.role === 'user' ? 'text-thai-200' : 'text-gray-400'}`}>
                {msg.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
              </p>
            </div>
          </div>
        ))}
        {isGenerating && (
          <div className="flex justify-start">
             <div className="bg-gray-50 rounded-2xl px-4 py-3 border border-gray-100 flex space-x-2 items-center">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></div>
             </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-4 border-t bg-gray-50">
        <div className="flex space-x-2">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleChatSend()}
            placeholder="Type your message..."
            disabled={isGenerating}
            className="flex-1 px-4 py-3 bg-gray-800 text-white placeholder-gray-400 border border-gray-700 rounded-xl focus:ring-2 focus:ring-thai-500 focus:border-thai-500 outline-none"
          />
          <button 
            onClick={handleChatSend}
            disabled={!chatInput.trim() || isGenerating}
            className={`px-6 rounded-xl font-bold text-white transition-colors ${
              !chatInput.trim() || isGenerating
                ? 'bg-gray-300 cursor-not-allowed'
                : 'bg-thai-600 hover:bg-thai-700'
            }`}
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    if (activeTool === ToolType.CONSULTATION) return renderChat();
    if (activeTool === ToolType.GALLERY) return <Gallery images={storedImages} onDelete={handleDeleteImage} onReuse={handleReusePrompt} />;
    return renderGenerator();
  };

  return (
    <Layout activeTool={activeTool} onToolChange={setActiveTool}>
      {renderContent()}
    </Layout>
  );
};

export default App;

export enum ToolType {
  STRATEGY = 'Strategy',
  EDUCATIONAL = 'Educational Post',
  SALES = 'Sales Post',
  AD_COPY = 'Ad Copy',
  CONSULTATION = 'Consultation',
  IMAGE_GENERATION = 'Image Generator',
  GALLERY = 'Gallery'
}

export enum ImageAspectRatio {
  SQUARE = '1:1',
  PORTRAIT_3_4 = '3:4',
  LANDSCAPE_4_3 = '4:3',
  PORTRAIT_9_16 = '9:16',
  LANDSCAPE_16_9 = '16:9'
}

export interface Message {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export interface GenerationRequest {
  tool: ToolType;
  topic: string;
  audience?: string;
  tone?: string;
  additionalContext?: string;
}

export interface GeminiConfig {
  apiKey: string;
}

export interface StoredImage {
  id: string;
  data: string;
  prompt: string;
  timestamp: number;
}

import { GoogleGenAI, Chat } from "@google/genai";
import { ToolType, GenerationRequest } from "../types";

const SYSTEM_INSTRUCTION_TEXT = `
You are the Chief Marketing Officer (CMO) and Lead Content Strategist for "Shwe Thai" (shwethai.com).

**Brand Profile:**
- **Core Service:** Connecting Myanmar patients with world-class hospitals in Thailand (Medical Tourism).
- **USP:** Safety, Transparency, Peace of Mind (စိတ်အေးချမ်းသာမှု), and Ease of Access.
- **Target Audience:** Myanmar citizens seeking better healthcare. They value trust above price.

**Operational Model (How shwethai.com works):**
1. **Marketplace:** The website lists official packages from partner hospitals.
2. **User Journey:** Patients log in, fill in their medical details/forms, and purchase packages directly on the site.
3. **Integration:** Shwe Thai is directly connected to the hospitals. Patient forms filled on the site are automatically forwarded to the hospital.
4. **Appointment:** Shwe Thai handles the appointment booking based on the purchase, and the patient simply travels on the scheduled date.

**Your Role:**
1.  **Strategic Planning:** Analyze pain points, suggest channels (FB, Telegram, TikTok), outline customer journeys emphasizing the ease of the digital platform.
2.  **Content Creation:** 
    - Educational: Explain medical info simply and professionally.
    - Sales: Sell packages (Check-ups, IVF, Cancer treatment) using PAS or AIDA frameworks. **Highlight that they can buy directly on the website and forms are auto-forwarded.**
    - Tone: Warm, Professional, Reassuring, Respectful (use 'ခင်ဗျာ/ရှင်').
3.  **Ad Copywriting:** Focus on "Results", "Safety", and "Convenience".
4.  **Consultation:** Act as a senior consultant.

**Formatting Rules:**
- Use Markdown (Bold headers, bullet points).
- **CRITICAL:** Use Myanmar Unicode for all public-facing content.
- Include emojis (🏥 🩺 ✈️).
- Always end with a CTA to shwethai.com or Messenger.
`;

class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat | null = null;

  constructor() {
    // API Key is injected by the environment
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const model = this.getModel();

    let prompt = "";

    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a marketing strategy for: "${request.topic}". 
        Target Audience: ${request.audience || "General Public"}.
        Context: ${request.additionalContext || "None"}.

        Analyze pain points, suggest channels, and outline a full Customer Journey.`;
        break;

      case ToolType.EDUCATIONAL:
        prompt = `Write an EDUCATIONAL Facebook post about: "${request.topic}".
        Target Audience: ${request.audience || "Patients seeking info"}.
        Tone: Empathetic, Clear, Professional.
        Context: ${request.additionalContext || "None"}.

        Explain the condition/procedure simply. Use empathy.`;
        break;

      case ToolType.SALES:
        prompt = `Write a SALES Facebook post for: "${request.topic}".
        Framework: Use PAS (Problem-Agitation-Solution) or AIDA.
        Target Audience: ${request.audience || "Potential customers"}.
        Context: ${request.additionalContext || "None"}.

        Focus on safety, transparency, and ease of access.`;
        break;

      case ToolType.AD_COPY:
        prompt = `Write Facebook Ad Copy for: "${request.topic}".
        Include:
        1. Primary Text (2 variations)
        2. Headlines (3 options)
        3. Visual/Creative Suggestions.

        Focus on "Trust" and "Results".`;
        break;

      case ToolType.CONSULTATION:
        prompt = `Consultation request: ${request.topic}. ${request.additionalContext}`;
        break;

      case ToolType.IMAGE_GENERATION:
         // This case should ideally be handled by generateImage, but if called here:
         return "Please use the image generation specific function.";
    }

    try {
      const response = await this.ai.models.generateContent({
        model,
        contents: [
          {
            role: 'user',
            parts: [{ text: prompt }]
          }
        ],
        config: {
          systemInstruction: {
            role: 'system',
            parts: [{ text: SYSTEM_INSTRUCTION_TEXT }]
          },
        },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Gemini Generation Error:", error);
      throw error;
    }
  }

  async generateImage(prompt: string, aspectRatio: string = '1:1'): Promise<string> {
    const model = 'gemini-2.5-flash-image';
    try {
      const response = await this.ai.models.generateContent({
        model,
        contents: {
          parts: [{ text: prompt }],
        },
        config: {
          // @ts-ignore - The SDK types might not yet reflect the full imageConfig structure for all environments
          imageConfig: {
            aspectRatio: aspectRatio
          }
        }
      });

      // The output response may contain both image and text parts; iterate through all parts.
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const base64EncodeString = part.inlineData.data;
            return `data:${part.inlineData.mimeType};base64,${base64EncodeString}`;
          }
        }
      }
      throw new Error("No image data found in response");
    } catch (error) {
      console.error("Gemini Image Generation Error:", error);
      throw error;
    }
  }

  async startChat(): Promise<Chat> {
    this.chatSession = this.ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: {
            role: 'system',
            parts: [{ text: SYSTEM_INSTRUCTION_TEXT }]
          },
      },
    });
    return this.chatSession;
  }

  async sendMessage(message: string): Promise<string> {
    if (!this.chatSession) {
      await this.startChat();
    }
    if (!this.chatSession) {
        throw new Error("Failed to initialize chat");
    }
    const response = await this.chatSession.sendMessage({ message });
    return response.text || "";
  }
}

export const geminiService = new GeminiService();

import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, GenerationRequest, Message, StoredImage, ImageAspectRatio } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { Gallery } from './components/Gallery';

const STORAGE_KEY = 'SHWETHAI_GALLERY';
const PREFS_KEY = 'SHWETHAI_IMAGE_PREFS';

const App = () => {
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);

  // Generator State
  const [topic, setTopic] = useState('');
  const [audience, setAudience] = useState('');
  const [context, setContext] = useState('');

  // Image Generator Preferences
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');

  const [generatedContent, setGeneratedContent] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]);

  // Chat State
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Load images and preferences from local storage
  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) {
        setStoredImages(JSON.parse(savedImages));
      }

      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  // Save preferences when they change
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality }));
  }, [aspectRatio, imageQuality]);

  // Reset content when tool changes (except when switching to Image Gen from Reuse)
  useEffect(() => {
    // We don't want to clear topic if we just switched to Image Gen for reuse
    if (activeTool !== ToolType.IMAGE_GENERATION) {
       setGeneratedContent(null);
       setGeneratedImage(null);
       setTopic('');
       setAudience('');
       setContext('');
    } else {
        // Just clear outputs
        setGeneratedContent(null);
        setGeneratedImage(null);
    }
  }, [activeTool]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const saveImageToGallery = (base64: string, prompt: string) => {
    const newImage: StoredImage = {
      id: Date.now().toString(),
      data: base64,
      prompt: prompt,
      timestamp: Date.now()
    };

    const updated = [newImage, ...storedImages];
    setStoredImages(updated);

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    } catch (e) {
      console.error("Storage full or error saving image", e);
      alert("Gallery storage is full. The image was generated but could not be saved to your local history.");
    }
  };

  const handleDeleteImage = (id: string) => {
    const updated = storedImages.filter(img => img.id !== id);
    setStoredImages(updated);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  };

  const handleReusePrompt = (prompt: string) => {
    setTopic(prompt);
    setActiveTool(ToolType.IMAGE_GENERATION);
  };

  const handleGenerate = async () => {
    if (!topic) return;

    setIsGenerating(true);
    setGeneratedContent(null);
    setGeneratedImage(null);

    try {
      if (activeTool === ToolType.IMAGE_GENERATION) {
        // Construct prompt for image
        let imagePrompt = topic;

        // Enhance prompt with Style/Mood and Context
        if (audience) imagePrompt += `. Style and Mood: ${audience}`;
        if (context) imagePrompt += `. Context/Details: ${context}`;

        // Apply "Quality" modifier via prompt engineering
        if (imageQuality === 'High') {
          imagePrompt += `, 8k resolution, highly detailed, photorealistic, masterpiece, professional photography`;
        }

        const imageBase64 = await geminiService.generateImage(imagePrompt, aspectRatio);
        setGeneratedImage(imageBase64);
        saveImageToGallery(imageBase64, imagePrompt);

      } else {
        // Handle text generation
        const request: GenerationRequest = {
          tool: activeTool,
          topic,
          audience,
          additionalContext: context
        };

        const result = await geminiService.generateContent(request);
        setGeneratedContent(result);
      }
    } catch (error) {
      console.error(error);
      setGeneratedContent("An error occurred while generating content. Please check your API Key and try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg: Message = {
      role: 'user',
      text: chatInput,
      timestamp: new Date()
    };

    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsGenerating(true);

    try {
      const responseText = await geminiService.sendMessage(userMsg.text);
      const botMsg: Message = {
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, botMsg]);
    } catch (error) {
       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY:
        return {
          title: "Strategic Planner",
          desc: "Create comprehensive marketing strategies for new campaigns or services.",
          placeholder: "e.g., Launching a new comprehensive heart check-up package",
          topicLabel: "Campaign Topic"
        };
      case ToolType.EDUCATIONAL:
        return {
          title: "Educational Content Generator",
          desc: "Build trust with informative posts about medical conditions.",
          placeholder: "e.g., The importance of early cervical cancer screening",
          topicLabel: "Medical Topic"
        };
      case ToolType.SALES:
        return {
          title: "Sales Copy Generator",
          desc: "Convert interest into bookings with persuasive, safe copy.",
          placeholder: "e.g., Promotion for 30% off liver screening in Bangkok",
          topicLabel: "Promotion / Service"
        };
      case ToolType.AD_COPY:
        return {
          title: "Ad Creative Suite",
          desc: "Generate high-converting Facebook ad copy and headlines.",
          placeholder: "e.g., Second opinion services for orthopedics",
          topicLabel: "Ad Subject"
        };
      case ToolType.IMAGE_GENERATION:
        return {
