import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, GenerationRequest, Message, StoredImage, ImageAspectRatio } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { Gallery } from './components/Gallery';

const STORAGE_KEY = 'SHWETHAI_GALLERY';
const PREFS_KEY = 'SHWETHAI_IMAGE_PREFS';

const App = () => {
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);

  // Generator State
  const [topic, setTopic] = useState('');
  const [audience, setAudience] = useState('');
  const [context, setContext] = useState('');

  // Image Generator Preferences
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');

  const [generatedContent, setGeneratedContent] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [generatedVideo, setGeneratedVideo] = useState<string | null>(null);

  const [isGenerating, setIsGenerating] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]);

  // Video Specific State
  const [hasVideoApiKey, setHasVideoApiKey] = useState(false);
  const [checkingKey, setCheckingKey] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Load images and preferences from local storage
  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) {
        setStoredImages(JSON.parse(savedImages));
      }

      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  // Check API Key for Video Tool
  useEffect(() => {
    const checkKey = async () => {
      if (activeTool === ToolType.VIDEO_GENERATION && window.aistudio) {
        setCheckingKey(true);
        try {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setHasVideoApiKey(hasKey);
        } catch (e) {
          console.error("Error checking API key", e);
        } finally {
          setCheckingKey(false);
        }
      }
    };
    checkKey();
  }, [activeTool]);

  // Save preferences when they change
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality }));
  }, [aspectRatio, imageQuality]);

  // Reset content when tool changes (except when switching to Image Gen from Reuse)
  useEffect(() => {
    // We don't want to clear topic if we just switched to Image Gen for reuse
    if (activeTool !== ToolType.IMAGE_GENERATION) {
       setGeneratedContent(null);
       setGeneratedImage(null);
       setGeneratedVideo(null);
       setTopic('');
       setAudience('');
       setContext('');
    } else {
        // Just clear outputs
        setGeneratedContent(null);
        setGeneratedImage(null);
        setGeneratedVideo(null);
    }
  }, [activeTool]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const saveImageToGallery = (base64: string, prompt: string) => {
    const newImage: StoredImage = {
      id: Date.now().toString(),
      data: base64,
      prompt: prompt,
      timestamp: Date.now()
    };

    const updated = [newImage, ...storedImages];
    setStoredImages(updated);

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    } catch (e) {
      console.error("Storage full or error saving image", e);
      alert("Gallery storage is full. The image was generated but could not be saved to your local history.");
    }
  };

  const handleDeleteImage = (id: string) => {
    const updated = storedImages.filter(img => img.id !== id);
    setStoredImages(updated);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  };

  const handleReusePrompt = (prompt: string) => {
    setTopic(prompt);
    setActiveTool(ToolType.IMAGE_GENERATION);
  };

  const handleSelectApiKey = async () => {
    if (window.aistudio) {
      try {
        await window.aistudio.openSelectKey();
        // Assume success to proceed, though race conditions may apply (mitigated by service ensuring logic)
        setHasVideoApiKey(true);
      } catch (e) {
        console.error("Error selecting key", e);
      }
    }
  };

  const handleGenerate = async () => {
    if (!topic) return;

    setIsGenerating(true);
    setLoadingProgress(0);
    setGeneratedContent(null);
    setGeneratedImage(null);
    setGeneratedVideo(null);

    // Simulate progress for better UX
    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => {
        if (prev >= 90) return prev;
        // Random increment 
        return prev + Math.floor(Math.random() * 5) + 1;
      });
    }, 800); // Slower progress for video/image

    try {
      if (activeTool === ToolType.IMAGE_GENERATION) {
        // Construct prompt for image
        let imagePrompt = topic;
        if (audience) imagePrompt += `. Style and Mood: ${audience}`;
        if (context) imagePrompt += `. Context/Details: ${context}`;
        if (imageQuality === 'High') {
          imagePrompt += `, 8k resolution, highly detailed, photorealistic, masterpiece, professional photography`;
        }

        const imageBase64 = await geminiService.generateImage(imagePrompt, aspectRatio);
        setGeneratedImage(imageBase64);
        saveImageToGallery(imageBase64, imagePrompt);

      } else if (activeTool === ToolType.VIDEO_GENERATION) {
         let videoPrompt = topic;
         if (audience) videoPrompt += `. Mood: ${audience}`;
         if (context) videoPrompt += `. details: ${context}`;

         const videoUrl = await geminiService.generateVideo(videoPrompt);
         setGeneratedVideo(videoUrl);

      } else {
        // Handle text generation
        const request: GenerationRequest = {
          tool: activeTool,
          topic,
          audience,
          additionalContext: context
        };

        const result = await geminiService.generateContent(request);
        setGeneratedContent(result);
      }
    } catch (error: any) {
      console.error(error);
      if (error.message === 'API_KEY_INVALID') {
        setHasVideoApiKey(false);
        setGeneratedContent("Your session expired or the API key was invalid. Please select your API Key again.");
      } else {
        setGeneratedContent("An error occurred while generating content. Please try again.");
      }
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg: Message = {
      role: 'user',
      text: chatInput,
      timestamp: new Date()
    };

    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsGenerating(true);

    try {
      const responseText = await geminiService.sendMessage(userMsg.text);
      const botMsg: Message = {
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, botMsg]);
    } catch (error) {
       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

