import React, { useState } from 'react';
import { ScheduledPost, ToolType } from '../types';

interface ContentCalendarProps {
  posts: ScheduledPost[];
  onDeletePost: (id: string) => void;
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

export const ContentCalendar: React.FC<ContentCalendarProps> = ({ posts, onDeletePost }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedPost, setSelectedPost] = useState<ScheduledPost | null>(null);

  const getDaysInMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const handlePrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1));
  };

  const handleExportCSV = () => {
    const headers = ['Date', 'Platform', 'Type', 'Status', 'Topic', 'Content'];
    const rows = posts.map(post => [
      post.date,
      post.platform,
      post.type,
      post.status,
      `"${post.title.replace(/"/g, '""')}"`, // Escape quotes
      `"${post.content.replace(/"/g, '""').replace(/\n/g, ' ')}"` // Escape quotes and newlines
    ]);

    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `shwe_thai_content_schedule_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const daysInMonth = getDaysInMonth(currentDate);
  const firstDay = getFirstDayOfMonth(currentDate);
  const today = new Date();

  // Create grid cells
  const blanks = Array(firstDay).fill(null);
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const totalSlots = [...blanks, ...days];

  // Helper to find posts for a day
  const getPostsForDay = (day: number) => {
    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    return posts.filter(p => p.date === dateStr);
  };

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Published': return 'bg-green-100 text-green-700 border-green-200';
      case 'Scheduled': return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-gray-100 text-gray-600 border-gray-200';
    }
  };

  const getPlatformIcon = (platform: string) => {
     switch(platform) {
       case 'Facebook': return <span className="text-blue-600 font-bold text-[10px]">FB</span>;
       case 'Telegram': return <span className="text-sky-500 font-bold text-[10px]">TG</span>;
       case 'Viber': return <span className="text-purple-600 font-bold text-[10px]">VB</span>;
       case 'TikTok': return <span className="text-black font-bold text-[10px]">TT</span>;
       default: return <span className="text-gray-500 font-bold text-[10px]">OT</span>;
     }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-gray-100">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Content Calendar</h2>
          <p className="text-sm text-gray-500 mt-1">Plan and manage your marketing distribution</p>
        </div>
        <div className="flex items-center space-x-3">
           <button 
            onClick={handleExportCSV}
            className="flex items-center space-x-2 px-4 py-2 bg-white border border-gray-200 text-gray-700 rounded-xl hover:bg-gray-50 transition-colors shadow-sm font-medium text-sm"
           >
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
             <span>Export CSV</span>
           </button>
           <div className="flex items-center bg-white rounded-xl shadow-sm border border-gray-200">
             <button onClick={handlePrevMonth} className="p-2 hover:bg-gray-50 text-gray-600 rounded-l-xl">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             </button>
             <span className="px-4 py-2 font-bold text-gray-800 min-w-[140px] text-center">
               {MONTHS[currentDate.getMonth()]} {currentDate.getFullYear()}
             </span>
             <button onClick={handleNextMonth} className="p-2 hover:bg-gray-50 text-gray-600 rounded-r-xl">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
             </button>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200 flex-1 overflow-hidden flex flex-col">
        {/* Days Header */}
        <div className="grid grid-cols-7 border-b border-gray-200 bg-gray-50">
          {DAYS.map(day => (
            <div key={day} className="py-3 text-center text-xs font-bold text-gray-500 uppercase tracking-wider">
              {day}
            </div>
          ))}
        </div>

        {/* Calendar Grid */}
        <div className="grid grid-cols-7 flex-1 auto-rows-fr">
          {totalSlots.map((day, index) => {
            if (!day) return <div key={index} className="bg-gray-50/30 border-b border-r border-gray-100 min-h-[100px]" />;

            const isToday = day === today.getDate() && currentDate.getMonth() === today.getMonth() && currentDate.getFullYear() === today.getFullYear();
            const dayPosts = getPostsForDay(day);

            return (
              <div key={index} className={`border-b border-r border-gray-100 p-2 min-h-[100px] flex flex-col group hover:bg-gray-50/50 transition-colors relative ${isToday ? 'bg-blue-50/30' : ''}`}>
                <div className="flex justify-between items-start mb-1">
                  <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${isToday ? 'bg-thai-600 text-white' : 'text-gray-700'}`}>
                    {day}
                  </span>
                </div>

                <div className="space-y-1 overflow-y-auto max-h-[100px] custom-scrollbar">
                  {dayPosts.map(post => (
                    <button
                      key={post.id}
                      onClick={() => setSelectedPost(post)}
                      className={`w-full text-left px-2 py-1.5 rounded-md text-[10px] border shadow-sm flex items-center gap-1.5 hover:opacity-80 transition-opacity ${getStatusColor(post.status)}`}
                    >
                      {getPlatformIcon(post.platform)}
                      <span className="truncate font-medium flex-1">{post.title}</span>
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Post Detail Modal */}
      {selectedPost && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setSelectedPost(null)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                 <h3 className="text-xl font-bold text-gray-900">{selectedPost.title}</h3>
                 <button onClick={() => setSelectedPost(null)} className="text-gray-400 hover:text-gray-600">
                   <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>
              <div className="p-6 space-y-4">
                 <div className="flex space-x-4">
                    <div>
                       <span className="text-xs font-bold text-gray-500 uppercase">Date</span>
                       <p className="text-sm font-medium">{new Date(selectedPost.date).toLocaleDateString(undefined, {weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'})}</p>
                    </div>
                    <div>
                       <span className="text-xs font-bold text-gray-500 uppercase">Platform</span>
                       <div className="flex items-center gap-1 mt-0.5">
                          {getPlatformIcon(selectedPost.platform)}
                          <span className="text-sm font-medium">{selectedPost.platform}</span>
                       </div>
                    </div>
                    <div>
                       <span className="text-xs font-bold text-gray-500 uppercase">Status</span>
                       <span className={`block mt-0.5 px-2 py-0.5 rounded text-xs font-medium border ${getStatusColor(selectedPost.status)}`}>
                         {selectedPost.status}
                       </span>
                    </div>
                 </div>
                 <div className="bg-gray-50 rounded-xl p-4 max-h-[200px] overflow-y-auto text-sm text-gray-700 leading-relaxed border border-gray-100">
                    {selectedPost.content}
                 </div>
              </div>
              <div className="p-4 bg-gray-50 flex justify-end space-x-3">
                 <button 
                   onClick={() => {
                     onDeletePost(selectedPost.id);
                     setSelectedPost(null);
                   }}
                   className="px-4 py-2 text-sm font-bold text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                 >
                   Delete
                 </button>
                 <button 
                   onClick={() => setSelectedPost(null)}
                   className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors"
                 >
                   Close
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, GenerationRequest, Message, StoredImage, ImageAspectRatio, ScheduledPost } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { Gallery } from './components/Gallery';
import { OnboardingTour } from './components/OnboardingTour';
import { ContentCalendar } from './components/ContentCalendar';

const STORAGE_KEY = 'SHWETHAI_GALLERY';
const PREFS_KEY = 'SHWETHAI_IMAGE_PREFS';
const TOUR_KEY = 'SHWETHAI_TOUR_COMPLETED';
const CALENDAR_KEY = 'SHWETHAI_CALENDAR';

const App = () => {
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);

  // Generator State
  const [topic, setTopic] = useState('');
  const [audience, setAudience] = useState('');
  const [context, setContext] = useState('');

  // Image Generator Preferences
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');

  const [generatedContent, setGeneratedContent] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [generatedVideo, setGeneratedVideo] = useState<string | null>(null);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false); // New state for enhancement
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]);
  const [previewImage, setPreviewImage] = useState<string | null>(null); // State for image preview

  // Calendar State
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false); // Modal trigger
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');

  // Video Specific State
  const [hasVideoApiKey, setHasVideoApiKey] = useState(false);
  const [checkingKey, setCheckingKey] = useState(false);

  // Tour State
  const [showTour, setShowTour] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Load data from local storage
  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) {
        setStoredImages(JSON.parse(savedImages));
      }

      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }

      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) {
        setScheduledPosts(JSON.parse(savedPosts));
      }

      // Check for tour completion
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) {
        // Small delay to ensure render is complete before showing tour
        setTimeout(() => setShowTour(true), 1000);
      }

    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  // Check API Key for Video Tool
  useEffect(() => {
    const checkKey = async () => {
      if (activeTool === ToolType.VIDEO_GENERATION && window.aistudio) {
        setCheckingKey(true);
        try {
          const hasKey = await window.aistudio.hasSelectedApiKey();
          setHasVideoApiKey(hasKey);
        } catch (e) {
          console.error("Error checking API key", e);
        } finally {
          setCheckingKey(false);
        }
      }
    };
    checkKey();
  }, [activeTool]);

  // Save preferences when they change
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality }));
  }, [aspectRatio, imageQuality]);

  // Save calendar when changed
  useEffect(() => {
    localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts));
  }, [scheduledPosts]);

  // Reset content when tool changes (except when switching to Image Gen from Reuse)
  useEffect(() => {
    // We don't want to clear topic if we just switched to Image Gen for reuse
    if (activeTool !== ToolType.IMAGE_GENERATION) {
       setGeneratedContent(null);
       setGeneratedImage(null);
       setGeneratedVideo(null);
       setTopic('');
       setAudience('');
       setContext('');
    } else {
        // Just clear outputs
        setGeneratedContent(null);
        setGeneratedImage(null);
        setGeneratedVideo(null);
    }
  }, [activeTool]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const saveImageToGallery = (base64: string, prompt: string) => {
    const newImage: StoredImage = {
      id: Date.now().toString(),
      data: base64,
      prompt: prompt,
      timestamp: Date.now()
    };

    const updated = [newImage, ...storedImages];
    setStoredImages(updated);

    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    } catch (e) {
      console.error("Storage full or error saving image", e);
      alert("Gallery storage is full. The image was generated but could not be saved to your local history.");
    }
  };

  const handleDeleteImage = (id: string) => {
    const updated = storedImages.filter(img => img.id !== id);
    setStoredImages(updated);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  };

  const handleDeletePost = (id: string) => {
    const updated = scheduledPosts.filter(p => p.id !== id);
    setScheduledPosts(updated);
  };

  const handleReusePrompt = (prompt: string) => {
    setTopic(prompt);
    setActiveTool(ToolType.IMAGE_GENERATION);
  };

  const handleSelectApiKey = async () => {
    if (window.aistudio) {
      try {
        await window.aistudio.openSelectKey();
        // Assume success to proceed, though race conditions may apply (mitigated by service ensuring logic)
        setHasVideoApiKey(true);
      } catch (e) {
        console.error("Error selecting key", e);
      }
    }
  };

  const handleEnhanceContent = async () => {
    if (!generatedContent || isEnhancing) return;

    setIsEnhancing(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      setGeneratedContent(enhanced);
    } catch (e) {
      console.error("Failed to enhance", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleSchedulePost = () => {
    if (!generatedContent || !scheduleDate) return;

    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date: scheduleDate,
      title: topic || 'Generated Content',
      content: generatedContent,
      platform: schedulePlatform,
      status: 'Scheduled',
      type: activeTool
    };

    setScheduledPosts(prev => [...prev, newPost]);
    setIsScheduling(false);
    setScheduleDate('');
    alert("Post added to your calendar!");
  };

  const handleTourClose = () => {
    setShowTour(false);
    localStorage.setItem(TOUR_KEY, 'true');
  };

  const handleGenerate = async () => {
    if (!topic) return;

    setIsGenerating(true);
    setLoadingProgress(0);
    setGeneratedContent(null);
    setGeneratedImage(null);
    setGeneratedVideo(null);

    // Simulate progress for better UX
    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => {
        if (prev >= 90) return prev;
        // Random increment 
        return prev + Math.floor(Math.random() * 5) + 1;
      });
    }, 800); // Slower progress for video/image

    try {
      if (activeTool === ToolType.IMAGE_GENERATION) {
        // Construct prompt for image
        let imagePrompt = topic;
        if (audience) imagePrompt += `. Style and Mood: ${audience}`;
        if (context) imagePrompt += `. Context/Details: ${context}`;
        if (imageQuality === 'High') {
          imagePrompt += `, 8k resolution, highly detailed, photorealistic, masterpiece, professional photography`;
        }

        const imageBase64 = await geminiService.generateImage(imagePrompt, aspectRatio);
        setGeneratedImage(imageBase64);
        saveImageToGallery(imageBase64, imagePrompt);

      } else if (activeTool === ToolType.VIDEO_GENERATION) {
         let videoPrompt = topic;
         if (audience) videoPrompt += `. Mood: ${audience}`;
         if (context) videoPrompt += `. details: ${context}`;

         const videoUrl = await geminiService.generateVideo(videoPrompt);
         setGeneratedVideo(videoUrl);

      } else {
        // Handle text generation
        const request: GenerationRequest = {
          tool: activeTool,
          topic,
          audience,
          additionalContext: context
        };

        const result = await geminiService.generateContent(request);
        setGeneratedContent(result);
      }
    } catch (error: any) {
      console.error(error);
      if (error.message === 'API_KEY_INVALID') {
        setHasVideoApiKey(false);
        setGeneratedContent("Your session expired or the API key was invalid. Please select your API Key again.");
      } else {
        setGeneratedContent("An error occurred while generating content. Please try again.");
      }
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg: Message = {
      role: 'user',
      text: chatInput,
      timestamp: new Date()
    };

    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsGenerating(true);

    try {
      const responseText = await geminiService.sendMessage(userMsg.text);
      const botMsg: Message = {
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, botMsg]);
    } catch (error) {
       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY:
        return {
          title: "Strategic Planner",
          desc: "Create comprehensive marketing strategies for new campaigns or services.",
          placeholder: "e.g., Launching a new comprehensive heart check-up package",
          topicLabel: "Campaign Topic"
        };
      case ToolType.EDUCATIONAL:
        return {
          title: "Educational Content Generator",
          desc: "Build trust with informative posts about medical conditions.",
          placeholder: "e.g., The importance of early cervical cancer screening",
          topicLabel: "Medical Topic"
        };
      case ToolType.SALES:
        return {
          title: "Sales Copy Generator",
          desc: "Convert interest into bookings with persuasive, safe copy.",
          placeholder: "e.g., Promotion for 30% off liver screening in Bangkok",
          topicLabel: "Promotion / Service"
        };
      case ToolType.AD_COPY:
        return {
          title: "Ad Creative Suite",
          desc: "Generate high-converting Facebook ad copy and headlines.",
          placeholder: "e.g., Second opinion services for orthopedics",
          topicLabel: "Ad Subject"
        };
      case ToolType.IMAGE_GENERATION:
        return {
          title: "AI Image Generator",
          desc: "Create relevant visual assets for your marketing posts.",
          placeholder: "e.g., A modern, clean hospital lobby with friendly staff greeting a patient",
          topicLabel: "Image Description"
        };
      case ToolType.VIDEO_GENERATION:
        return {
          title: "Veo Video Creator",
          desc: "Generate cinematic promotional videos for packages.",
          placeholder: "e.g., A happy family walking in a clean hospital corridor in Bangkok",
          topicLabel: "Video Concept"
        };
      default:
        return { title: "", desc: "", placeholder: "", topicLabel: "Topic" };
    }
  };

  const headerInfo = renderToolHeader();

  const renderLoadingState = () => (
    <div className="flex flex-col items-center justify-center h-full animate-fadeIn transition-opacity duration-300">
      <div className="relative w-24 h-24 mb-6">
        <div className="absolute inset-0 border-4 border-gray-100 rounded-full"></div>
        <div className="absolute inset-0 border-4 border-thai-500 rounded-full border-t-transparent animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center font-bold text-thai-600 text-lg">
          {loadingProgress}%
        </div>
      </div>
      <h3 className="text-xl font-bold text-gray-800 mb-2">
        {activeTool === ToolType.IMAGE_GENERATION ? 'Creating Visuals...' : 
         activeTool === ToolType.VIDEO_GENERATION ? 'Generating Video (this may take a minute)...' : 'Generating Strategy...'}
      </h3>
      <p className="text-gray-500 text-sm max-w-xs text-center">
        Our AI is analyzing your requirements and crafting professional content for Shwe Thai.
      </p>

      <div className="mt-8 flex space-x-2">
         <div className="w-2 h-2 bg-thai-200 rounded-full animate-bounce"></div>
         <div className="w-2 h-2 bg-thai-500 rounded-full animate-bounce delay-75"></div>
         <div className="w-2 h-2 bg-thai-700 rounded-full animate-bounce delay-150"></div>
      </div>
    </div>
  );

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
      {/* Input Section */}
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200/60 h-fit sticky top-6 overflow-hidden">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100">
          <h2 className="text-xl font-bold text-gray-900 mb-1">{headerInfo.title}</h2>
          <p className="text-gray-500 text-xs font-medium">{headerInfo.desc}</p>
        </div>

        <div className="p-6 space-y-6">
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
              {headerInfo.topicLabel} <span className="text-thai-red">*</span>
            </label>
            <input
              type="text"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              placeholder={headerInfo.placeholder}
              className="w-full px-4 py-3 bg-white text-gray-900 placeholder-gray-400 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all shadow-sm"
            />
          </div>

          {/* Image Settings - Only for Image Gen */}
          {activeTool === ToolType.IMAGE_GENERATION && (
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
                  Aspect Ratio
                </label>
                <div className="relative">
                  <select
                    value={aspectRatio}
                    onChange={(e) => setAspectRatio(e.target.value)}
                    className="w-full px-4 py-3 bg-white text-gray-900 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none appearance-none shadow-sm"
                  >
                    <option value={ImageAspectRatio.SQUARE}>Square (1:1)</option>
                    <option value={ImageAspectRatio.LANDSCAPE_4_3}>Landscape (4:3)</option>
                    <option value={ImageAspectRatio.LANDSCAPE_16_9}>Landscape (16:9)</option>
                    <option value={ImageAspectRatio.PORTRAIT_3_4}>Portrait (3:4)</option>
                    <option value={ImageAspectRatio.PORTRAIT_9_16}>Portrait (9:16)</option>
                  </select>
                  <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3 text-gray-500">
                    <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                  </div>
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
                  Quality
                </label>
                 <div className="relative">
                  <select
                    value={imageQuality}
                    onChange={(e) => setImageQuality(e.target.value)}
                    className="w-full px-4 py-3 bg-white text-gray-900 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none appearance-none shadow-sm"
                  >
                    <option value="Standard">Standard</option>
                    <option value="High">High Detail</option>
                  </select>
                  <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3 text-gray-500">
                    <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                  </div>
                </div>
              </div>
            </div>
          )}

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
              {activeTool === ToolType.IMAGE_GENERATION || activeTool === ToolType.VIDEO_GENERATION ? "Style / Mood (Optional)" : "Target Audience (Optional)"}
            </label>
            <input
              type="text"
              value={audience}
              onChange={(e) => setAudience(e.target.value)}
              placeholder={activeTool === ToolType.IMAGE_GENERATION || activeTool === ToolType.VIDEO_GENERATION ? "e.g., Warm, Professional, Cinematic" : "e.g., Women over 40, Patients with diabetes history"}
              className="w-full px-4 py-3 bg-white text-gray-900 placeholder-gray-400 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all shadow-sm"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
              Context / Details
            </label>
            <textarea
              value={context}
              onChange={(e) => setContext(e.target.value)}
              rows={4}
              placeholder={activeTool === ToolType.IMAGE_GENERATION || activeTool === ToolType.VIDEO_GENERATION ? "e.g., Bright lighting, specific hospital colors" : "e.g., Price is 5000 THB, includes free airport pickup."}
              className="w-full px-4 py-3 bg-white text-gray-900 placeholder-gray-400 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all resize-none shadow-sm"
            />
          </div>

          {activeTool === ToolType.VIDEO_GENERATION && !hasVideoApiKey ? (
             <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4">
                <p className="text-sm text-yellow-800 mb-3">
                   To create videos with Veo, you must select a billing-enabled project via Google AI Studio.
                   <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="underline ml-1 font-bold">Learn more</a>
                </p>
                <button
                  onClick={handleSelectApiKey}
                  className="w-full py-3 px-4 rounded-xl text-white font-bold shadow-md bg-yellow-600 hover:bg-yellow-700 transition-all flex items-center justify-center space-x-2"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
                  <span>Connect Billing Account</span>
                </button>
             </div>
          ) : (
             <button
              onClick={handleGenerate}
              disabled={!topic || isGenerating}
              className={`w-full py-4 px-4 rounded-xl text-white font-bold shadow-md flex items-center justify-center space-x-2 transition-all transform hover:-translate-y-0.5 relative overflow-hidden
                ${!topic || isGenerating 
                  ? 'bg-gray-300 cursor-not-allowed shadow-none' 
                  : 'bg-gradient-to-r from-thai-600 to-thai-500 hover:from-thai-700 hover:to-thai-600 shadow-thai-200'
                }`}
            >
               {isGenerating && (
                  <div 
                    className="absolute bottom-0 left-0 h-1.5 bg-white/40 transition-all duration-300 ease-linear"
                    style={{ width: `${loadingProgress}%` }}
                  />
               )}
              {isGenerating ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  <span>Processing {loadingProgress}%</span>
                </>
              ) : (
                <>
                  <span>{activeTool === ToolType.IMAGE_GENERATION ? "Generate Image" : activeTool === ToolType.VIDEO_GENERATION ? "Generate Video" : "Generate Content"}</span>
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                </>
              )}
