import React, { useState } from 'react';
import { SavedContentItem, StoredImage } from '../types';
import FormattedText from './MarkdownRenderer';

interface SavedContentRepoProps {
  items: SavedContentItem[];
  onDelete: (id: string) => void;
  onSchedule: (item: SavedContentItem) => void;
  onViewImage: (img: StoredImage) => void;
  onUpdate: (id: string, newContent: string) => void;
}

export const SavedContentRepo: React.FC<SavedContentRepoProps> = ({ items, onDelete, onSchedule, onViewImage, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');

  const startEdit = (item: SavedContentItem) => {
    setEditingId(item.id);
    setEditContent(item.content || '');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditContent('');
  };

  const saveEdit = (id: string) => {
    onUpdate(id, editContent);
    setEditingId(null);
    setEditContent('');
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-gray-400 min-h-[400px] bg-white rounded-2xl border border-gray-200 border-dashed hover:border-thai-200 transition-colors duration-300">
        <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mb-4 shadow-inner">
          <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
          </svg>
        </div>
        <p className="font-medium text-gray-500">သိမ်းဆည်းထားသော အရာများ မရှိသေးပါ (No saved items)</p>
        <p className="text-sm mt-1">Generate content and click "Save" to build your repository.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between pb-4 border-b border-gray-100">
        <div>
           <h2 className="text-2xl font-bold text-gray-900">Saved Content Repository</h2>
           <p className="text-sm text-gray-500 mt-1">Manage your drafts and assets</p>
        </div>
        <div className="flex items-center gap-2">
            <span className="bg-gray-100 text-gray-600 px-3 py-1 rounded-full text-xs font-bold animate-pulse-slow">
               {items.length} Items
            </span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {items.map((item) => (
          <div key={item.id} className="bg-white rounded-xl shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 ease-out border border-gray-200 overflow-hidden flex flex-col group">
            {/* Status Bar */}
            <div className={`px-4 py-2 border-b border-gray-50 flex justify-between items-center text-[10px] font-bold uppercase tracking-wider ${
                item.status === 'Scheduled' ? 'bg-green-50 text-green-700' : 'bg-gray-50 text-gray-500'
            }`}>
                <span>{item.type}</span>
                {item.status === 'Scheduled' ? (
                  <span className="flex items-center gap-1">
                    <span className="w-1.5 h-1.5 bg-green-500 rounded-full"></span>
                    {item.scheduledDate}
                  </span>
                ) : (
                  <span>Unscheduled</span>
                )}
            </div>

            {/* Content Body */}
            <div className="flex-1 p-5 flex flex-col space-y-4">
               {item.image && (
                 <div 
                   className="w-full aspect-video bg-gray-100 rounded-lg overflow-hidden cursor-zoom-in relative group/img shadow-inner"
                   onClick={() => onViewImage({ id: item.id, data: item.image!, prompt: item.prompt, timestamp: item.timestamp })}
                 >
                    <img src={item.image} alt="Asset" className="w-full h-full object-cover transition-transform duration-700 group-hover/img:scale-105" />
                    <div className="absolute inset-0 bg-black/20 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center">
                       <span className="text-white text-xs font-bold bg-black/50 px-3 py-1.5 rounded-full backdrop-blur-sm transform scale-90 group-hover/img:scale-100 transition-transform">View</span>
                    </div>
                 </div>
               )}

               {item.content && (
                 <div className="flex-1 max-h-[300px] custom-scrollbar">
                    {editingId === item.id ? (
                      <textarea
                        value={editContent}
                        onChange={(e) => setEditContent(e.target.value)}
                        className="w-full h-full min-h-[200px] p-3 border border-thai-200 rounded-lg focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none text-sm leading-relaxed resize-none"
                      />
                    ) : (
                      <div className="max-h-[200px] overflow-y-auto pr-2 custom-scrollbar">
                        <div className="prose prose-sm prose-slate line-clamp-6">
                            <FormattedText text={item.content} />
                        </div>
                      </div>
                    )}
                 </div>
               )}

               {!item.image && !item.content && (
                   <p className="text-gray-400 italic text-sm">No content data available.</p>
               )}
            </div>

            {/* Actions */}
            <div className="p-4 bg-gray-50 border-t border-gray-100 flex items-center justify-between">
                {editingId === item.id ? (
                  <div className="flex space-x-2 w-full justify-end">
                    <button 
                      onClick={cancelEdit}
                      className="px-3 py-1.5 text-xs font-bold text-gray-500 hover:text-gray-700 bg-white border border-gray-200 rounded-lg transition-colors hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={() => saveEdit(item.id)}
                      className="px-3 py-1.5 text-xs font-bold text-white bg-green-600 hover:bg-green-700 rounded-lg shadow-sm transition-all transform hover:scale-105 active:scale-95"
                    >
                      Save Changes
                    </button>
                  </div>
                ) : (
                  <>
                    <div className="flex space-x-2">
                       <button 
                        onClick={() => onDelete(item.id)}
                        className="text-red-500 hover:text-red-700 text-xs font-bold px-2 py-1 rounded hover:bg-red-50 transition-colors"
                      >
                        Delete
                      </button>
                      {item.content && (
                         <button 
                           onClick={() => startEdit(item)}
                           className="text-gray-500 hover:text-thai-600 text-xs font-bold px-2 py-1 rounded hover:bg-gray-100 transition-colors"
                         >
                           Edit
                         </button>
                      )}
                    </div>
                    <div className="flex space-x-2">
                       {item.content && (
                           <button 
                             onClick={() => navigator.clipboard.writeText(item.content || '')}
                             className="text-gray-500 hover:text-gray-700 text-xs font-bold px-2 py-1 rounded hover:bg-gray-100 transition-colors"
                           >
                             Copy
                           </button>
                       )}
                       <button 
                         onClick={() => onSchedule(item)}
                         className={`text-white text-xs font-bold px-4 py-2 rounded-lg shadow-md hover:shadow-lg transition-all transform hover:-translate-y-0.5 active:translate-y-0 active:scale-95 flex items-center gap-1.5 ${
                             item.status === 'Scheduled' ? 'bg-green-600 hover:bg-green-700' : 'bg-thai-600 hover:bg-thai-700'
                         }`}
                       >
                         {item.status === 'Scheduled' ? (
                             <>
                               <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                               Reschedule
                             </>
                         ) : (
                             <>
                               <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                               Calendar
                             </>
                         )}
                       </button>
                    </div>
                  </>
                )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

