import React, { useState } from 'react';
import { ScheduledPost, ToolType } from '../types';

interface ContentCalendarProps {
  posts: ScheduledPost[];
  onDeletePost: (id: string) => void;
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

export const ContentCalendar: React.FC<ContentCalendarProps> = ({ posts, onDeletePost }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedPost, setSelectedPost] = useState<ScheduledPost | null>(null);

  const getDaysInMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const handlePrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1));
  };

  const handleExportCSV = () => {
    const headers = ['Date', 'Platform', 'Type', 'Status', 'Topic', 'Content'];
    const rows = posts.map(post => [
      post.date,
      post.platform,
      post.type,
      post.status,
      `"${post.title.replace(/"/g, '""')}"`, // Escape quotes
      `"${post.content.replace(/"/g, '""').replace(/\n/g, ' ')}"` // Escape quotes and newlines
    ]);

    const csvContent = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `shwe_thai_content_schedule_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const daysInMonth = getDaysInMonth(currentDate);
  const firstDay = getFirstDayOfMonth(currentDate);
  const today = new Date();

  // Create grid cells
  const blanks = Array(firstDay).fill(null);
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const totalSlots = [...blanks, ...days];

  // Helper to find posts for a day
  const getPostsForDay = (day: number) => {
    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    return posts.filter(p => p.date === dateStr);
  };

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Published': return 'bg-green-100 text-green-700 border-green-200';
      case 'Scheduled': return 'bg-blue-100 text-blue-700 border-blue-200';
      default: return 'bg-gray-100 text-gray-600 border-gray-200';
    }
  };

  const getPlatformIcon = (platform: string) => {
     switch(platform) {
       case 'Facebook': return <span className="text-blue-600 font-bold text-[10px]">FB</span>;
       case 'Telegram': return <span className="text-sky-500 font-bold text-[10px]">TG</span>;
       case 'Viber': return <span className="text-purple-600 font-bold text-[10px]">VB</span>;
       case 'TikTok': return <span className="text-black font-bold text-[10px]">TT</span>;
       default: return <span className="text-gray-500 font-bold text-[10px]">OT</span>;
     }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-gray-100">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Content Calendar</h2>
          <p className="text-sm text-gray-500 mt-1">Plan and manage your marketing distribution</p>
        </div>
        <div className="flex items-center space-x-3">
           <button 
            onClick={handleExportCSV}
            className="flex items-center space-x-2 px-4 py-2 bg-white border border-gray-200 text-gray-700 rounded-xl hover:bg-gray-50 hover:shadow-md transition-all duration-300 transform hover:-translate-y-0.5 shadow-sm font-medium text-sm"
           >
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
             <span>Export CSV</span>
           </button>
           <div className="flex items-center bg-white rounded-xl shadow-sm border border-gray-200 hover:shadow-md transition-shadow">
             <button onClick={handlePrevMonth} className="p-2 hover:bg-gray-50 text-gray-600 rounded-l-xl transition-colors">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             </button>
             <span className="px-4 py-2 font-bold text-gray-800 min-w-[140px] text-center">
               {MONTHS[currentDate.getMonth()]} {currentDate.getFullYear()}
             </span>
             <button onClick={handleNextMonth} className="p-2 hover:bg-gray-50 text-gray-600 rounded-r-xl transition-colors">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
             </button>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200 flex-1 overflow-hidden flex flex-col">
        {/* Days Header */}
        <div className="grid grid-cols-7 border-b border-gray-200 bg-gray-50">
          {DAYS.map(day => (
            <div key={day} className="py-3 text-center text-xs font-bold text-gray-500 uppercase tracking-wider">
              {day}
            </div>
          ))}
        </div>

        {/* Calendar Grid */}
        <div className="grid grid-cols-7 flex-1 auto-rows-fr">
          {totalSlots.map((day, index) => {
            if (!day) return <div key={index} className="bg-gray-50/30 border-b border-r border-gray-100 min-h-[100px]" />;

            const isToday = day === today.getDate() && currentDate.getMonth() === today.getMonth() && currentDate.getFullYear() === today.getFullYear();
            const dayPosts = getPostsForDay(day);

            return (
              <div key={index} className={`border-b border-r border-gray-100 p-2 min-h-[100px] flex flex-col group hover:bg-gray-50/50 transition-colors relative ${isToday ? 'bg-blue-50/30' : ''}`}>
                <div className="flex justify-between items-start mb-1">
                  <span className={`text-sm font-semibold w-7 h-7 flex items-center justify-center rounded-full ${isToday ? 'bg-thai-600 text-white shadow-sm' : 'text-gray-700'}`}>
                    {day}
                  </span>
                </div>

                <div className="space-y-1 overflow-y-auto max-h-[100px] custom-scrollbar">
                  {dayPosts.map(post => (
                    <button
                      key={post.id}
                      onClick={() => setSelectedPost(post)}
                      className={`w-full text-left px-2 py-1.5 rounded-md text-[10px] border shadow-sm flex items-center gap-1.5 hover:opacity-90 hover:scale-[1.02] transition-all duration-200 ${getStatusColor(post.status)}`}
                    >
                      {getPlatformIcon(post.platform)}
                      <span className="truncate font-medium flex-1">{post.title}</span>
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Post Detail Modal */}
      {selectedPost && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setSelectedPost(null)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                 <h3 className="text-xl font-bold text-gray-900">{selectedPost.title}</h3>
                 <button onClick={() => setSelectedPost(null)} className="text-gray-400 hover:text-gray-600 hover:rotate-90 transition-transform duration-300">
                   <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>
              <div className="p-6 space-y-4">
                 <div className="flex space-x-4">
                    <div>
                       <span className="text-xs font-bold text-gray-500 uppercase">Date</span>
                       <p className="text-sm font-medium">{new Date(selectedPost.date).toLocaleDateString(undefined, {weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'})}</p>
                    </div>
                    <div>
                       <span className="text-xs font-bold text-gray-500 uppercase">Platform</span>
                       <div className="flex items-center gap-1 mt-0.5">
                          {getPlatformIcon(selectedPost.platform)}
                          <span className="text-sm font-medium">{selectedPost.platform}</span>
                       </div>
                    </div>
                    <div>
                       <span className="text-xs font-bold text-gray-500 uppercase">Status</span>
                       <span className={`block mt-0.5 px-2 py-0.5 rounded text-xs font-medium border ${getStatusColor(selectedPost.status)}`}>
                         {selectedPost.status}
                       </span>
                    </div>
                 </div>
                 <div className="bg-gray-50 rounded-xl p-4 max-h-[200px] overflow-y-auto text-sm text-gray-700 leading-relaxed border border-gray-100">
                    {selectedPost.content}
                 </div>
              </div>
              <div className="p-4 bg-gray-50 flex justify-end space-x-3">
                 <button 
                   onClick={() => {
                     if (window.confirm("Are you sure you want to delete this post? (ဖျက်မှာသေချာပါသလား)")) {
                        onDeletePost(selectedPost.id);
                        setSelectedPost(null);
                     }
                   }}
                   className="px-4 py-2 text-sm font-bold text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                 >
                   Delete
                 </button>
                 <button 
                   onClick={() => setSelectedPost(null)}
                   className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors"
                 >
                   Close
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI, Chat } from "@google/genai";
import { ToolType, GenerationRequest } from "../types";

// The error indicates 'aistudio' is already defined on Window with type 'AIStudio'.
// We need to augment that interface instead of redeclaring the window property with a conflicting type.
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const SYSTEM_INSTRUCTION_TEXT = `
You are the Chief Marketing Officer (CMO) and Lead Content Strategist for "Shwe Thai" (shwethai.com).

**Brand Profile:**
- **Core Service:** Connecting Myanmar patients with world-class hospitals in Thailand (Medical Tourism).
- **USP:** Safety, Transparency, Peace of Mind (စိတ်အေးချမ်းသာမှု), and Ease of Access.
- **Target Audience:** Myanmar citizens seeking better healthcare. They value trust above price.

**Operational Model (How shwethai.com works):**
1. **Marketplace:** The website lists official packages from partner hospitals.
2. **User Journey:** Patients log in, fill in their medical details/forms, and purchase packages directly on the site.
3. **Integration:** Shwe Thai is directly connected to the hospitals. Patient forms filled on the site are automatically forwarded to the hospital.
4. **Appointment:** Shwe Thai handles the appointment booking based on the purchase, and the patient simply travels on the scheduled date.

**Your Role:**
1.  **Strategic Planning:** Analyze pain points, suggest channels (FB, Telegram, TikTok), outline customer journeys emphasizing the ease of the digital platform.
2.  **Content Creation:** 
    - Educational: Explain medical info simply and professionally.
    - Sales: Sell packages (Check-ups, IVF, Cancer treatment) using PAS or AIDA frameworks. **Highlight that they can buy directly on the website and forms are auto-forwarded.**
    - Tone: Warm, Professional, Reassuring, Respectful (use 'ခင်ဗျာ/ရှင်').
3.  **Ad Copywriting:** Focus on "Results", "Safety", and "Convenience".
4.  **Consultation:** Act as a senior consultant.

**Formatting Rules:**
- Use Markdown (Bold headers, bullet points).
- **CRITICAL:** Use Myanmar Unicode for all public-facing content.
- **EMOJIS:** You MUST use a LOT of attractive and medical-themed emojis (🏥, 🩺, 👩‍⚕️, 💉, 💊, ✨, 💚, 🌸, ✈️, 🇹🇭, ✅, 💙, 🏨, 🔬) in every paragraph. Make the content visually popping, friendly, and very engaging.
- **Visual Appeal:** The content should look "Facebook-ready" with clear spacing and decorative emojis.
- Always end with a CTA to shwethai.com or Messenger.
`;

class GeminiService {
  private ai: GoogleGenAI;
  private chatSession: Chat | null = null;

  constructor() {
    // API Key is injected by the environment
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const model = this.getModel();

    let prompt = "";

    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a marketing strategy for: "${request.topic}". 
        Target Audience: ${request.audience || "General Public"}.
        Context: ${request.additionalContext || "None"}.

        Analyze pain points, suggest channels, and outline a full Customer Journey.`;
        break;

      case ToolType.EDUCATIONAL:
        prompt = `Write an EDUCATIONAL Facebook post about: "${request.topic}".
        Target Audience: ${request.audience || "Patients seeking info"}.
        Tone: Empathetic, Clear, Professional.
        Context: ${request.additionalContext || "None"}.

        Explain the condition/procedure simply. Use empathy.`;
        break;

      case ToolType.SALES:
        prompt = `Write a SALES Facebook post for: "${request.topic}".
        Framework: Use PAS (Problem-Agitation-Solution) or AIDA.
        Target Audience: ${request.audience || "Potential customers"}.
        Context: ${request.additionalContext || "None"}.

        Focus on safety, transparency, and ease of access.`;
        break;

      case ToolType.AD_COPY:
        prompt = `Write Facebook Ad Copy for: "${request.topic}".
        Include:
        1. Primary Text (2 variations)
        2. Headlines (3 options)
        3. Visual/Creative Suggestions.

        Focus on "Trust" and "Results".`;
        break;

      case ToolType.CONSULTATION:
        prompt = `Consultation request: ${request.topic}. ${request.additionalContext}`;
        break;

      case ToolType.IMAGE_GENERATION:
         return "Please use the specific generation function for media.";
    }

    try {
      const response = await this.ai.models.generateContent({
        model,
        contents: [
          {
            role: 'user',
            parts: [{ text: prompt }]
          }
        ],
        config: {
          systemInstruction: {
            role: 'system',
            parts: [{ text: SYSTEM_INSTRUCTION_TEXT }]
          },
        },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Gemini Generation Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const model = this.getModel();
    try {
      const prompt = `Review the following content and ENHANCE it. 
      1. Improve clarity, flow, and professionalism.
      2. Ensure it strictly follows Shwe Thai's tone (Warm, Reassuring, Professional).
      3. Improve formatting (bullet points, bold text).
      4. Ensure CTA is strong.
      5. Add MORE emojis to make it very attractive.

      Original Content:
      ${originalContent}`;

      const response = await this.ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: {
            role: 'system',
            parts: [{ text: SYSTEM_INSTRUCTION_TEXT }]
          },
        },
      });
      return response.text || originalContent;
    } catch (error) {
       console.error("Enhance Error:", error);
       throw error;
    }
  }

  async generateImage(prompt: string, aspectRatio: string = '1:1'): Promise<string> {
    const model = 'gemini-2.5-flash-image';
    try {
      const response = await this.ai.models.generateContent({
        model,
        contents: {
          parts: [{ text: prompt }],
        },
        config: {
          // @ts-ignore - The SDK types might not yet reflect the full imageConfig structure for all environments
          imageConfig: {
            aspectRatio: aspectRatio
          }
        }
      });

      // The output response may contain both image and text parts; iterate through all parts.
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const base64EncodeString = part.inlineData.data;
            return `data:${part.inlineData.mimeType};base64,${base64EncodeString}`;
          }
        }
      }
      throw new Error("No image data found in response");
    } catch (error) {
      console.error("Gemini Image Generation Error:", error);
      throw error;
    }
  }

  async startChat(): Promise<Chat> {
    this.chatSession = this.ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: {
            role: 'system',
            parts: [{ text: SYSTEM_INSTRUCTION_TEXT }]
          },
      },
    });
    return this.chatSession;
  }

  async sendMessage(message: string): Promise<string> {
    if (!this.chatSession) {
      await this.startChat();
    }
    if (!this.chatSession) {
        throw new Error("Failed to initialize chat");
    }
    const response = await this.chatSession.sendMessage({ message });
    return response.text || "";
  }
}

export const geminiService = new GeminiService();

