                          className="px-3 py-1.5 rounded-lg text-xs font-medium bg-gradient-to-r from-shwe-gold to-shwe-600 text-white hover:opacity-90 transition-all transform hover:scale-105 active:scale-95 flex items-center space-x-1 shadow-sm"
