                        <>
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                            <span>Scheduled</span>
                        </>
                    ) : (
                        <>
                            <svg className="w-4 h-4 text-gray-400 group-hover:text-thai-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                            <span>Schedule</span>
                        </>
                    )}
                  </button>
                  <button 
                    onClick={handleToggleSave}
                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all transform hover:scale-105 active:scale-95 flex items-center space-x-2 shadow-sm border ${
                      currentSavedItemId 
                        ? 'bg-green-50 text-green-700 border-green-200 hover:bg-red-50 hover:text-red-600 hover:border-red-200' 
                        : 'bg-white text-gray-600 border-gray-200 hover:text-thai-600 hover:border-thai-200'
                    }`}
                    title={currentSavedItemId ? "Click to Unsave" : "Save to Repository"}
                  >
                      {currentSavedItemId ? (
                        <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                        </svg>
                      ) : (
                        <svg className="w-4 h-4 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                      )}
                    <span>{currentSavedItemId ? 'Saved (သိမ်းပြီး)' : 'Save (သိမ်းမည်)'}</span>
                  </button>
                </>
              )}
              {generatedImage && (
                <a 
                  href={generatedImage} 
                  download="shwethai-generated-image.png"
                  className="px-3 py-1.5 rounded-lg text-xs font-medium bg-white border border-gray-200 text-gray-600 hover:text-thai-600 hover:border-thai-200 transition-all transform hover:scale-105 active:scale-95 flex items-center space-x-1"
                >
                  <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  <span>Download</span>
                </a>
              )}
            </div>
          </div>

          <div className="flex-1 p-8 bg-white relative overflow-y-auto custom-scrollbar">
            {isGenerating ? (
              renderLoadingState()
            ) : generatedImage ? (
              <div 
                className="flex items-center justify-center h-full bg-gray-50 rounded-xl border border-dashed border-gray-200 p-4 cursor-zoom-in group relative"
                onClick={() => handleOpenPreview({ id: 'gen', data: generatedImage, prompt: topic, timestamp: Date.now() })}
              >
                <img 
                  src={generatedImage} 
                  alt="Generated Marketing Visual" 
                  className="max-w-full max-h-[600px] rounded-lg shadow-lg object-contain transition-transform group-hover:scale-[1.02]"
