        <div className="bg-white rounded-xl shadow-sm border border-gray-200/60 p-4 h-52 flex flex-col">
            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3">Recent Generations ({activeTool})</h4>
            <div className="flex-1 overflow-x-auto overflow-y-hidden whitespace-nowrap custom-scrollbar flex space-x-4 items-center">
                {(recentHistory[activeTool] || []).length === 0 ? (
                    <p className="text-gray-400 text-sm italic w-full text-center">No recent history yet.</p>
                ) : (
                    (recentHistory[activeTool] || []).map((item) => (
                        <div key={item.id} className="inline-block w-64 h-full bg-gray-50 rounded-lg border border-gray-200 p-3 relative group flex flex-col hover:shadow-md transition-shadow bg-white">
                            <div className="flex justify-between items-start mb-2">
                                <p className="text-xs font-bold text-gray-800 truncate w-40" title={item.prompt}>{item.prompt}</p>
                                <span className="text-[9px] text-gray-400">{new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                            </div>
                            <div className="flex-1 overflow-hidden relative border border-gray-100 rounded-md bg-gray-50/50">
                                {item.image ? (
                                    <img src={item.image} alt="Thumbnail" className="w-full h-full object-cover rounded" />
                                ) : (
                                    <p className="text-[10px] text-gray-500 whitespace-pre-wrap line-clamp-4 p-2">{item.content}</p>
                                )}
                                {/* Overlay Actions */}
                                <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-2">
                                     <button 
                                       onClick={() => loadFromHistory(item)}
                                       className="p-1.5 bg-thai-600 text-white rounded hover:bg-thai-700 shadow-sm" 
                                       title="Load to Editor"
                                     >
                                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                     </button>
                                     {item.content && (
                                         <button 
                                           onClick={() => handleCopy(item.content || '', item.id)}
                                           className={`p-1.5 rounded shadow-sm transition-colors ${
                                               copiedId === item.id 
                                               ? 'bg-green-100 text-green-700' 
                                               : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                           }`}
                                           title="Copy Text"
                                         >
                                            {copiedId === item.id ? (
                                                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                                            ) : (
                                                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
                                            )}
                                         </button>
                                     )}
                                     <button 
                                       onClick={() => deleteFromHistory(activeTool, item.id)}
                                       className="p-1.5 bg-red-50 text-red-500 rounded hover:bg-red-100 hover:text-red-600 shadow-sm"
                                       title="Delete"
                                     >
                                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                     </button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
      </div>
    </div>
  );

  const renderChat = () => (
    <div className="flex flex-col h-[calc(100vh-6rem)] bg-white rounded-2xl shadow-sm border border-gray-200/60 overflow-hidden">
      <div className="px-6 py-4 border-b border-gray-100 bg-white flex items-center justify-between">
         <div className="flex items-center space-x-4">
           <div className="w-12 h-12 rounded-full bg-gradient-to-br from-shwe-gold to-yellow-600 flex items-center justify-center shadow-md ring-2 ring-white">
             <span className="text-white font-bold text-xl">C</span>
           </div>
           <div>
             <h3 className="font-bold text-gray-900 text-lg">CMO Consultant</h3>
             <p className="text-xs text-green-600 font-medium flex items-center">
               <span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-1.5"></span>
               Online & Ready
             </p>
           </div>
         </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gray-50/50">
        {chatMessages.length === 0 && (
            <div className="text-center mt-20 opacity-60">
            <p className="text-lg font-medium text-gray-800 mb-2">👋 Mingalarpar!</p>
            <p className="text-sm text-gray-500 max-w-sm mx-auto">I'm your AI Marketing Consultant. Ask me about strategy, objection handling, or campaign ideas.</p>
            </div>
        )}
        {chatMessages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-2xl px-6 py-4 shadow-sm ${
              msg.role === 'user' 
                ? 'bg-thai-600 text-white rounded-br-none' 
                : 'bg-white text-gray-800 rounded-bl-none border border-gray-100'
            }`}>
              <FormattedText text={msg.text} />
              <p className={`text-[10px] mt-2 font-medium ${msg.role === 'user' ? 'text-thai-200' : 'text-gray-400'}`}>
                {msg.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
              </p>
            </div>
          </div>
        ))}
        {isGenerating && (
          <div className="flex justify-start">
             <div className="bg-white rounded-2xl px-5 py-4 border border-gray-100 shadow-sm flex space-x-2 items-center">
                <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce delay-150"></div>
             </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-gray-100">
        <div className="flex space-x-3 max-w-4xl mx-auto">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleChatSend()}
            placeholder="Type your message..."
            disabled={isGenerating}
            className="flex-1 px-5 py-4 bg-gray-50 text-gray-900 placeholder-gray-400 border border-gray-200 rounded-2xl focus:bg-white focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all shadow-inner"
          />
          <button 
            onClick={handleChatSend}
            disabled={!chatInput.trim() || isGenerating}
            className={`px-8 rounded-2xl font-bold text-white transition-all duration-300 ease-out transform hover:scale-105 active:scale-95 shadow-md ${
              !chatInput.trim() || isGenerating
                ? 'bg-gray-300 cursor-not-allowed shadow-none'
                : 'bg-thai-600 hover:bg-thai-700 shadow-thai-200'
            }`}
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    if (activeTool === ToolType.CONSULTATION) return renderChat();
    // Use SavedContentRepo instead of Gallery
    if (activeTool === ToolType.SAVED_CONTENT) return <SavedContentRepo items={savedContent} onDelete={handleDeleteSavedItem} onSchedule={openScheduleModal} onViewImage={handleOpenPreview} onUpdate={handleUpdateSavedItem} />;
    if (activeTool === ToolType.CALENDAR) return <ContentCalendar posts={scheduledPosts} onDeletePost={handleDeletePost} />;
    return renderGenerator();
  };

  return (
    <Layout activeTool={activeTool} onToolChange={setActiveTool}>
      {renderContent()}

      {/* Onboarding Tour */}
      <OnboardingTour isOpen={showTour} onClose={handleTourClose} />

      {/* Full Screen Image Preview & Creative Studio Modal */}
      {previewImage && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setPreviewImage(null)}>
           <div className="relative max-w-6xl w-full h-[90vh] flex flex-col md:flex-row bg-gray-900 rounded-2xl overflow-hidden shadow-2xl" onClick={(e) => e.stopPropagation()}>

              {/* Image Canvas Area */}
              <div className="flex-1 flex items-center justify-center bg-black/50 p-6 relative overflow-hidden">
                 <img 
                   src={previewImage.data} 
                   alt="Preview" 
                   className={`max-h-full max-w-full object-contain shadow-2xl transition-all duration-500 ${previewFilter}`}
                 />
              </div>

              {/* Sidebar Controls */}
              <div className="w-full md:w-80 bg-white border-l border-gray-100 flex flex-col">
                 <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                    <h3 className="font-bold text-gray-900">Creative Studio</h3>
                    <button onClick={() => setPreviewImage(null)} className="text-gray-400 hover:text-gray-600">
                       <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                 </div>

                 <div className="p-5 flex-1 overflow-y-auto">
                    <div className="mb-6">
                       <label className="text-xs font-bold text-gray-400 uppercase tracking-wider block mb-3">Filters & Mood</label>
                       <div className="grid grid-cols-2 gap-2">
                          {IMAGE_FILTERS.map(f => (
                             <button
                               key={f.id}
                               onClick={() => setPreviewFilter(f.class)}
                               className={`px-3 py-2 rounded-lg text-sm font-medium transition-all text-left flex items-center space-x-2 ${
                                 previewFilter === f.class 
                                   ? 'bg-thai-50 text-thai-700 ring-1 ring-thai-200' 
                                   : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                               }`}
                             >
                               <div className={`w-4 h-4 rounded-full bg-gradient-to-br from-gray-300 to-gray-400 border border-gray-300 ${f.class}`}></div>
                               <span>{f.label}</span>
                             </button>
                          ))}
                       </div>
                    </div>

                    <div className="p-4 bg-yellow-50 rounded-xl border border-yellow-100">
                       <p className="text-xs text-yellow-800 leading-relaxed">
                          <strong>💡 Pro Tip:</strong> Use "Warm" for family packages and "Cool" for technology/lab highlights.
                       </p>
                    </div>
                 </div>

                 <div className="p-5 border-t border-gray-100 bg-gray-50">
                    <a 
                       href={previewImage.data} 
                       download={`shwethai-asset-${Date.now()}.png`}
                       className="w-full py-3 bg-gray-900 hover:bg-gray-800 text-white rounded-xl font-bold flex items-center justify-center space-x-2 transition-all transform hover:scale-105 active:scale-95"
                    >
                       <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                       <span>Download Asset</span>
                    </a>
                 </div>
              </div>

           </div>
        </div>
      )}

      {/* Scheduling Modal */}
      {isScheduling && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setIsScheduling(false)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden" onClick={e => e.stopPropagation()}>
             <div className="p-6 border-b border-gray-100">
               <h3 className="text-xl font-bold text-gray-900">Schedule Post</h3>
               <p className="text-sm text-gray-500">Add this content to your marketing calendar.</p>
             </div>
             <div className="p-6 space-y-4">
               <div>
                 <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">ဘယ်နေ့ ၊ ဘယ်အချိန် တင်မလဲ? (Date)</label>
                 <input 
                   type="date" 
                   value={scheduleDate}
                   onChange={(e) => setScheduleDate(e.target.value)}
                   className="w-full px-4 py-3 bg-gray-50 text-gray-900 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none"
                 />
               </div>
               <div>
                 <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">ဘယ် Platform အတွက်လဲ? (Platform)</label>
                 <select
                   value={schedulePlatform}
                   onChange={(e) => setSchedulePlatform(e.target.value as any)}
                   className="w-full px-4 py-3 bg-gray-50 text-gray-900 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none"
                 >
                   <option value="Facebook">Facebook</option>
                   <option value="Telegram">Telegram</option>
                   <option value="Viber">Viber</option>
                   <option value="TikTok">TikTok</option>
                   <option value="Other">Other</option>
                 </select>
               </div>
             </div>
             <div className="p-4 bg-gray-50 flex justify-end space-x-3">
               <button 
                 onClick={() => setIsScheduling(false)}
                 className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors"
               >
                 Cancel
               </button>
               <button 
                 onClick={handleSchedulePost}
                 disabled={!scheduleDate}
                 className={`px-4 py-2 text-sm font-bold text-white rounded-lg transition-all shadow-sm ${!scheduleDate ? 'bg-gray-300 cursor-not-allowed' : 'bg-thai-600 hover:bg-thai-700 hover:shadow-lg transform hover:-translate-y-0.5 active:translate-y-0 active:scale-95'}`}
               >
                 Calendar သို့ ပို့မည် (Confirm)
               </button>
             </div>
           </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { SavedContentItem, StoredImage } from '../types';
import FormattedText from './MarkdownRenderer';

interface SavedContentRepoProps {
  items: SavedContentItem[];
  onDelete: (id: string) => void;
  onSchedule: (item: SavedContentItem) => void;
  onViewImage: (img: StoredImage) => void;
  onUpdate: (id: string, newContent: string) => void;
}

export const SavedContentRepo: React.FC<SavedContentRepoProps> = ({ items, onDelete, onSchedule, onViewImage, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const startEdit = (item: SavedContentItem) => {
    setEditingId(item.id);
    setEditContent(item.content || '');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditContent('');
  };

  const saveEdit = (id: string) => {
    onUpdate(id, editContent);
    setEditingId(null);
    setEditContent('');
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-gray-400 min-h-[400px] bg-white rounded-2xl border border-gray-200 border-dashed hover:border-thai-200 transition-colors duration-300">
        <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mb-4 shadow-inner">
          <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
