import React, { useState } from 'react';
import { SavedContentItem, StoredImage } from '../types';
import FormattedText from './MarkdownRenderer';

interface SavedContentRepoProps {
  items: SavedContentItem[];
  onDelete: (ids: string[]) => void;
  onSchedule: (item: SavedContentItem) => void;
  onViewImage: (img: StoredImage) => void;
  onUpdate: (id: string, newContent: string) => void;
}

export const SavedContentRepo: React.FC<SavedContentRepoProps> = ({ items, onDelete, onSchedule, onViewImage, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  // Modal State
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [itemsToDelete, setItemsToDelete] = useState<string[]>([]);

  const startEdit = (item: SavedContentItem) => {
    setEditingId(item.id);
    setEditContent(item.content || '');
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditContent('');
  };

  const saveEdit = (id: string) => {
    onUpdate(id, editContent);
    setEditingId(null);
    setEditContent('');
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const toggleSelection = (id: string) => {
      const newSelected = new Set(selectedIds);
      if (newSelected.has(id)) {
          newSelected.delete(id);
      } else {
          newSelected.add(id);
      }
      setSelectedIds(newSelected);
  };

  const toggleSelectAll = () => {
      if (selectedIds.size === items.length) {
          setSelectedIds(new Set());
      } else {
          setSelectedIds(new Set(items.map(item => item.id)));
      }
  };

  // Trigger Modal
  const requestDelete = (ids: string[]) => {
      setItemsToDelete(ids);
      setIsDeleteModalOpen(true);
  };

  // Confirm Delete
  const confirmDelete = () => {
      onDelete(itemsToDelete);
      // Clear selection if deleted items were selected
      const newSelected = new Set(selectedIds);
      itemsToDelete.forEach(id => newSelected.delete(id));
      setSelectedIds(newSelected);

      setIsDeleteModalOpen(false);
      setItemsToDelete([]);
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-gray-400 min-h-[400px] bg-white rounded-2xl border border-gray-200 border-dashed hover:border-thai-200 transition-colors duration-300">
        <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mb-4 shadow-inner">
          <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" />
          </svg>
        </div>
        <p className="font-medium text-gray-500">သိမ်းဆည်းထားသော အရာများ မရှိသေးပါ (No saved items)</p>
        <p className="text-sm mt-1">Generate content and click "Save" to build your repository.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6 relative">
      {/* Header with Bulk Actions */}
      <div className="flex items-center justify-between pb-4 border-b border-gray-100 sticky top-0 bg-[#F9FAFB] z-10 py-2">
        <div>
           <h2 className="text-2xl font-bold text-gray-900">Saved Content Repository</h2>
           <p className="text-sm text-gray-500 mt-1">Manage your drafts and assets</p>
        </div>
        <div className="flex items-center gap-3">
            <button 
                onClick={toggleSelectAll}
                className="text-xs font-bold text-gray-500 hover:text-gray-700 px-3 py-1.5 rounded-lg border border-gray-200 bg-white hover:bg-gray-50 transition-colors"
            >
                {selectedIds.size === items.length ? 'Deselect All' : 'Select All'}
            </button>

            {selectedIds.size > 0 && (
                <button 
                    onClick={() => requestDelete(Array.from(selectedIds))}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold text-white bg-red-500 hover:bg-red-600 rounded-lg shadow-sm transition-all animate-fadeIn"
                >
                    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    Delete ({selectedIds.size})
                </button>
            )}

            <span className="bg-gray-100 text-gray-600 px-3 py-1 rounded-full text-xs font-bold">
               {items.length} Items
            </span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {items.map((item) => (
          <div 
             key={item.id} 
             className={`bg-white rounded-xl shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 ease-out border overflow-hidden flex flex-col group relative ${
                 selectedIds.has(item.id) ? 'ring-2 ring-thai-500 border-thai-500' : 'border-gray-200'
             }`}
             onClick={(e) => {
                 // Clicking card body toggles selection if we are not editing
                 if (!editingId) toggleSelection(item.id);
             }}
          >
            {/* Selection Checkbox */}
            <div className="absolute top-3 left-3 z-10" onClick={e => e.stopPropagation()}>
                <input 
                    type="checkbox" 
                    checked={selectedIds.has(item.id)}
                    onChange={() => toggleSelection(item.id)}
                    className="w-5 h-5 text-thai-600 rounded focus:ring-thai-500 border-gray-300 cursor-pointer shadow-sm"
                />
            </div>

            {/* Status Bar */}
            <div className={`px-4 py-2 pl-10 border-b border-gray-50 flex justify-between items-center text-[10px] font-bold uppercase tracking-wider ${
                item.status === 'Scheduled' ? 'bg-green-50 text-green-700' : 'bg-gray-50 text-gray-500'
            }`}>
                <span>{item.type}</span>
                {item.status === 'Scheduled' ? (
                  <span className="flex items-center gap-1">
                    <span className="w-1.5 h-1.5 bg-green-500 rounded-full"></span>
                    {item.scheduledDate}
                  </span>
                ) : (
                  <span>Unscheduled</span>
                )}
            </div>

            {/* Content Body */}
            <div className="flex-1 p-5 flex flex-col space-y-4" onClick={e => e.stopPropagation()}>
               {item.image && (
                 <div 
                   className="w-full aspect-video bg-gray-100 rounded-lg overflow-hidden cursor-zoom-in relative group/img shadow-inner"
                   onClick={() => onViewImage({ id: item.id, data: item.image!, prompt: item.prompt, timestamp: item.timestamp })}
                 >
                    <img src={item.image} alt="Asset" className="w-full h-full object-cover transition-transform duration-700 group-hover/img:scale-105" />
                    <div className="absolute inset-0 bg-black/20 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center">
                       <span className="text-white text-xs font-bold bg-black/50 px-3 py-1.5 rounded-full backdrop-blur-sm transform scale-90 group-hover/img:scale-100 transition-transform">View</span>
                    </div>
                 </div>
               )}

               {item.content && (
                 <div className="flex-1 max-h-[300px] custom-scrollbar">
                    {editingId === item.id ? (
                      <textarea
                        value={editContent}
                        onChange={(e) => setEditContent(e.target.value)}
                        className="w-full h-full min-h-[200px] p-4 border border-gray-200 bg-gray-50 focus:bg-white rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none text-sm leading-relaxed resize-none transition-all shadow-inner focus:shadow-none"
                        placeholder="Edit content here..."
                        onClick={e => e.stopPropagation()}
                      />
                    ) : (
                      <div className="max-h-[200px] overflow-y-auto pr-2 custom-scrollbar">
                        <div className="prose prose-sm prose-slate line-clamp-6">
                            <FormattedText text={item.content} />
                        </div>
                      </div>
                    )}
                 </div>
               )}

               {!item.image && !item.content && (
                   <p className="text-gray-400 italic text-sm">No content data available.</p>
               )}
            </div>

            {/* Actions */}
            <div className="p-4 bg-gray-50/80 border-t border-gray-100 flex items-center justify-between gap-3" onClick={e => e.stopPropagation()}>
                {editingId === item.id ? (
                  <div className="flex space-x-2 w-full justify-end animate-fadeIn">
                    <button 
                      onClick={cancelEdit}
                      className="px-3 py-1.5 text-xs font-bold text-gray-500 hover:text-gray-700 bg-white border border-gray-200 rounded-lg transition-colors hover:bg-gray-50"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={() => saveEdit(item.id)}
                      className="px-3 py-1.5 text-xs font-bold text-white bg-green-600 hover:bg-green-700 rounded-lg shadow-sm transition-all transform hover:scale-105 active:scale-95 flex items-center gap-1"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                      Save
                    </button>
                  </div>
                ) : (
                  <>
                    <div className="flex items-center gap-2">
                       <button 
                        type="button"
                        onClick={(e) => {
                             e.preventDefault();
                             e.stopPropagation();
                             requestDelete([item.id]);
                        }}
                        className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all duration-200"
                        title="Delete Item"
                      >
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                      </button>
                      {item.content && (
                         <button 
                           onClick={() => startEdit(item)}
                           className="flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-bold text-gray-500 hover:text-thai-600 hover:bg-white border border-transparent hover:border-gray-200 rounded-lg transition-all duration-200"
                           title="Edit Content"
                         >
                           <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                           Edit
                         </button>
                      )}
                    </div>

                    <div className="flex items-center gap-2">
                       {item.content && (
                           <button 
                             onClick={() => handleCopy(item.content || '', item.id)}
                             className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold rounded-lg transition-all duration-200 border ${
                                 copiedId === item.id 
                                 ? 'bg-green-50 text-green-700 border-green-200' 
                                 : 'bg-white text-gray-600 border-gray-200 hover:text-thai-600 hover:border-thai-300'
                             }`}
                           >
                             {copiedId === item.id ? (
                                <>
                                    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                                    Copied
                                </>
                             ) : (
                                <>
                                    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                                    Copy
                                </>
                             )}
                           </button>
                       )}
                       <button 
                         onClick={() => onSchedule(item)}
                         className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold text-white rounded-lg shadow-sm transition-all transform hover:-translate-y-0.5 active:translate-y-0 active:scale-95 ${
                             item.status === 'Scheduled' 
                             ? 'bg-green-600 hover:bg-green-700' 
                             : 'bg-gradient-to-r from-thai-600 to-thai-500 hover:from-thai-700 hover:to-thai-600'
                         }`}
                       >
                         {item.status === 'Scheduled' ? (
                             <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                         ) : (
                             <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                         )}
                         {item.status === 'Scheduled' ? 'Scheduled' : 'Schedule'}
                       </button>
                    </div>
                  </>
                )}
            </div>
          </div>
        ))}
      </div>

      {/* Reactive Confirmation Modal */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setIsDeleteModalOpen(false)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all scale-100" onClick={e => e.stopPropagation()}>
              <div className="p-6 text-center">
                 <div className="w-16 h-16 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg className="w-8 h-8 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                 </div>
                 <h3 className="text-xl font-bold text-gray-900 mb-2">Delete Content?</h3>
                 <p className="text-gray-500 text-sm mb-6">
                   Are you sure you want to delete <span className="font-bold text-gray-900">{itemsToDelete.length}</span> item(s)? This action cannot be undone. <br/> (ဖျက်မှာသေချာပါသလား)
                 </p>
                 <div className="flex space-x-3 justify-center">
                    <button 
                        onClick={() => setIsDeleteModalOpen(false)}
                        className="px-5 py-2.5 text-sm font-bold text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-xl transition-colors"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={confirmDelete}
                        className="px-5 py-2.5 text-sm font-bold text-white bg-red-600 hover:bg-red-700 rounded-xl shadow-md transition-all transform hover:-translate-y-0.5 active:scale-95"
                    >
                        Yes, Delete
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, GenerationRequest, Message, StoredImage, ImageAspectRatio, ScheduledPost, SavedContentItem } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { SavedContentRepo } from './components/SavedContentRepo';
import { OnboardingTour } from './components/OnboardingTour';
import { ContentCalendar } from './components/ContentCalendar';
import { LandingPage } from './components/LandingPage';

const STORAGE_KEY = 'SHWETHAI_GALLERY';
const SAVED_CONTENT_KEY = 'SHWETHAI_SAVED_CONTENT';
const PREFS_KEY = 'SHWETHAI_IMAGE_PREFS';
const TOUR_KEY = 'SHWETHAI_TOUR_COMPLETED';
const CALENDAR_KEY = 'SHWETHAI_CALENDAR';
const HISTORY_KEY = 'SHWETHAI_RECENT_HISTORY';

const IMAGE_FILTERS = [
  { id: 'none', label: 'Original', class: '' },
  { id: 'grayscale', label: 'B&W', class: 'grayscale' },
  { id: 'sepia', label: 'Sepia', class: 'sepia' },
  { id: 'warm', label: 'Warm', class: 'sepia-[.5] contrast-100' },
  { id: 'cool', label: 'Cool', class: 'hue-rotate-180 saturate-50' },
  { id: 'vintage', label: 'Vintage', class: 'sepia-[.3] contrast-125 brightness-90' },
  { id: 'blur', label: 'Blur', class: 'blur-[2px]' },
];

// Define state structure for a tool to allow persistence
interface ToolState {
  topic: string;
  audience: string;
  context: string;
  generatedContent: string | null;
  generatedImage: string | null;
  currentSavedItemId: string | null;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  generatedContent: null,
  generatedImage: null,
  currentSavedItemId: null
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);

  // Persistent Tool State
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});

  // History State (per tool, limit 5)
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});

  // Image Generator Preferences
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);

  // Feedback States
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [scheduleSuccess, setScheduleSuccess] = useState(false);

  // Global Repositories
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]); 
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);

  // Preview / Creative Studio State
  const [previewImage, setPreviewImage] = useState<StoredImage | null>(null);
  const [previewFilter, setPreviewFilter] = useState<string>('');

  // Calendar State
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false); // Modal trigger
  const [schedulingItem, setSchedulingItem] = useState<SavedContentItem | null>(null); // Item being scheduled from repo
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');

  // Tour State
  const [showTour, setShowTour] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Helper to access current tool's state safely
  const getCurrentToolState = () => {
    return toolStates[activeTool] || INITIAL_TOOL_STATE;
  };

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId } = getCurrentToolState();

  // Load data from local storage
  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) setStoredImages(JSON.parse(savedImages));

      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));

      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));

      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }

      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));

      // Don't show tour immediately if landing page is active, 
      // instead, we'll check this when entering the app
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  const handleStartApp = () => {
      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) {
          setTimeout(() => setShowTour(true), 1000);
      }
  };

  // Save preferences
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality }));
  }, [aspectRatio, imageQuality]);

  // Save calendar
  useEffect(() => {
    localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts));
  }, [scheduledPosts]);

  // Save Content Repo
  useEffect(() => {
    localStorage.setItem(SAVED_CONTENT_KEY, JSON.stringify(savedContent));
  }, [savedContent]);

  // Save History
  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(recentHistory));
  }, [recentHistory]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  // History Helper
  const addToRecentHistory = (item: SavedContentItem) => {
    setRecentHistory(prev => {
      const toolHistory = prev[activeTool] || [];
      // Add to front, limit to 5, avoid duplicates based on content if possible
      const newHistory = [item, ...toolHistory].slice(0, 5);
      return { ...prev, [activeTool]: newHistory };
    });
  };

  const deleteFromHistory = (tool: ToolType, id: string) => {
      if (window.confirm("Are you sure you want to delete this from recent history? (ဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({
            ...prev,
            [tool]: (prev[tool] || []).filter(item => item.id !== id)
        }));
      }
  };

  const clearToolHistory = (tool: ToolType) => {
      if (window.confirm("Are you sure you want to clear all history for this tool? (မှတ်တမ်းအားလုံးဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({
            ...prev,
            [tool]: []
        }));
      }
  };

  const loadFromHistory = (item: SavedContentItem) => {
      updateCurrentToolState({
          topic: item.prompt,
          generatedContent: item.content || null,
          generatedImage: item.image || null,
          currentSavedItemId: null // Reset saved status since we loaded a copy
      });
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  // Unified Save/Unsave Toggle Function
  const handleToggleSave = () => {
    if (!generatedContent && !generatedImage) return;

    if (currentSavedItemId) {
      // UNSAVE LOGIC
      setSavedContent(prev => prev.filter(item => item.id !== currentSavedItemId));
      updateCurrentToolState({ currentSavedItemId: null });
      return;
    }

    // SAVE LOGIC
    const newId = Date.now().toString();
    const newItem: SavedContentItem = {
      id: newId,
      type: activeTool,
      content: generatedContent || undefined,
      image: generatedImage || undefined,
      prompt: topic || 'Untitled Generation',
      timestamp: Date.now(),
      status: 'Unscheduled'
    };

    setSavedContent(prev => [newItem, ...prev]);
    updateCurrentToolState({ currentSavedItemId: newId });
  };

  const handleDeleteSavedItems = (ids: string[]) => {
    setSavedContent(prev => prev.filter(item => !ids.includes(item.id)));

    // If the currently edited/viewed item is deleted, reset the tool state for it
    if (currentSavedItemId && ids.includes(currentSavedItemId)) {
      updateCurrentToolState({ currentSavedItemId: null });
    }
  };

  const handleUpdateSavedItem = (id: string, newContent: string) => {
    setSavedContent(prev => prev.map(item => 
      item.id === id ? { ...item, content: newContent } : item
    ));
  };

  const handleDeletePost = (id: string) => {
    // Confirmation handled inside ContentCalendar
    const updated = scheduledPosts.filter(p => p.id !== id);
    setScheduledPosts(updated);
  };

  const handleOpenPreview = (img: StoredImage, initialFilter: string = '') => {
    setPreviewImage(img);
    setPreviewFilter(initialFilter);
  };

  const handleEnhanceContent = async () => {
    if (!generatedContent || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      updateCurrentToolState({ generatedContent: enhanced });
    } catch (e) {
      console.error("Failed to enhance", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  // Scheduling Logic
  const checkScheduleConflict = (date: string): boolean => {
    return scheduledPosts.some(post => post.date === date);
  };

  const openScheduleModal = (item?: SavedContentItem) => {
    if (item) {
        setSchedulingItem(item);
    } else {
        setSchedulingItem(null); 
    }
    setScheduleSuccess(false);
    setIsScheduling(true);
  };

  const handleSchedulePost = () => {
    if (!scheduleDate) return;

    // Content source: either from Repository Item OR Current Generator State
    const contentToSchedule = schedulingItem ? schedulingItem.content : generatedContent;
    const titleToSchedule = schedulingItem ? schedulingItem.prompt : topic;
    const typeToSchedule = schedulingItem ? schedulingItem.type : activeTool;

    if (!contentToSchedule && !schedulingItem?.image && !generatedImage) return;

    // Conflict Check
    if (checkScheduleConflict(scheduleDate)) {
        const confirm = window.confirm("အဲ့ဒီအချိန်မှာ Post တစ်ခုရှိပြီးသားပါ။ ထပ်တင်မှာ သေချာပါသလား? (There is already a post on this date. Continue?)");
        if (!confirm) return;
    }

    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date: scheduleDate,
      title: titleToSchedule || 'Generated Content',
      content: contentToSchedule || '[Image Post]',
      platform: schedulePlatform,
      status: 'Scheduled',
      type: typeToSchedule
    };

    setScheduledPosts(prev => [...prev, newPost]);

    // If scheduling from Repo, update status
    if (schedulingItem) {
        setSavedContent(prev => prev.map(item => 
            item.id === schedulingItem.id 
                ? { ...item, status: 'Scheduled', scheduledDate: scheduleDate } 
                : item
        ));
    } else {
        // If scheduling current content, show transient success
        setScheduleSuccess(true);
        setTimeout(() => setScheduleSuccess(false), 3000);
    }

    setIsScheduling(false);
    setScheduleDate('');
    setSchedulingItem(null);
  };

  const handleTourClose = () => {
    setShowTour(false);
    localStorage.setItem(TOUR_KEY, 'true');
  };

  const handleGenerate = async () => {
    if (!topic) return;

    setIsGenerating(true);
    setLoadingProgress(0);
    // Clear previous results while loading
    updateCurrentToolState({ generatedContent: null, generatedImage: null, currentSavedItemId: null });

    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => {
        if (prev >= 90) return prev;
        return prev + Math.floor(Math.random() * 5) + 1;
      });
    }, 800);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;

      if (activeTool === ToolType.IMAGE_GENERATION) {
        let imagePrompt = topic;
        if (audience) imagePrompt += `. Style and Mood: ${audience}`;
        if (context) imagePrompt += `. Context/Details: ${context}`;
        if (imageQuality === 'High') {
          imagePrompt += `, 8k resolution, highly detailed, photorealistic, masterpiece, professional photography`;
        }

        imageResult = await geminiService.generateImage(imagePrompt, aspectRatio);
      } else {
        const request: GenerationRequest = {
          tool: activeTool,
          topic,
          audience,
          additionalContext: context
        };
        contentResult = await geminiService.generateContent(request);
      }

      // Update State
      updateCurrentToolState({
          generatedContent: contentResult,
          generatedImage: imageResult
      });

      // Add to History automatically
      const historyItem: SavedContentItem = {
          id: Date.now().toString(),
          type: activeTool,
          content: contentResult || undefined,
          image: imageResult || undefined,
          prompt: topic,
          timestamp: Date.now(),
          status: 'Unscheduled'
      };
      addToRecentHistory(historyItem);

    } catch (error: any) {
      console.error(error);
      updateCurrentToolState({ generatedContent: "An error occurred while generating content. Please try again." });
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg: Message = {
      role: 'user',
      text: chatInput,
      timestamp: new Date()
    };

    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsGenerating(true);

    try {
      const responseText = await geminiService.sendMessage(userMsg.text);
      const botMsg: Message = {
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, botMsg]);
    } catch (error) {
       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
