interface ToolState {
  topic: string;
  audience: string;
  context: string;
  generatedContent: string | null;
  generatedImage: string | null;
  currentSavedItemId: string | null;
  // New fields for Image Gen
  negativePrompt: string;
  stylePreset: string;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  generatedContent: null,
  generatedImage: null,
  currentSavedItemId: null,
  negativePrompt: '',
  stylePreset: 'none'
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);

  // Persistent Tool State
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});

  // History State (per tool, limit 5)
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});

  // Image Generator Preferences
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);

  // Feedback States
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [scheduleSuccess, setScheduleSuccess] = useState(false);

  // Global Repositories
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]); 
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);

  // Preview / Creative Studio State
  const [previewImage, setPreviewImage] = useState<StoredImage | null>(null);
  const [previewFilter, setPreviewFilter] = useState<string>('');

  // Calendar State
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false); // Modal trigger
  const [schedulingItem, setSchedulingItem] = useState<SavedContentItem | null>(null); // Item being scheduled from repo
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');

  // Tour State
  const [showTour, setShowTour] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Helper to access current tool's state safely
  const getCurrentToolState = () => {
    return toolStates[activeTool] || INITIAL_TOOL_STATE;
  };

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId, negativePrompt, stylePreset } = getCurrentToolState();

  // Load data from local storage
  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) setStoredImages(JSON.parse(savedImages));

      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));

      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));

      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }

      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));

      // Don't show tour immediately if landing page is active, 
      // instead, we'll check this when entering the app
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  const handleStartApp = () => {
      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) {
          setTimeout(() => setShowTour(true), 1000);
      }
  };

  // Save preferences
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality }));
  }, [aspectRatio, imageQuality]);

  // Save calendar
  useEffect(() => {
    localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts));
  }, [scheduledPosts]);

  // Save Content Repo
  useEffect(() => {
    localStorage.setItem(SAVED_CONTENT_KEY, JSON.stringify(savedContent));
  }, [savedContent]);

  // Save History
  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(recentHistory));
  }, [recentHistory]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  // History Helper
  const addToRecentHistory = (item: SavedContentItem) => {
    setRecentHistory(prev => {
      const toolHistory = prev[activeTool] || [];
      // Add to front, limit to 5, avoid duplicates based on content if possible
      const newHistory = [item, ...toolHistory].slice(0, 5);
      return { ...prev, [activeTool]: newHistory };
    });
  };

  const deleteFromHistory = (tool: ToolType, id: string) => {
      if (window.confirm("Are you sure you want to delete this from recent history? (ဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({
            ...prev,
            [tool]: (prev[tool] || []).filter(item => item.id !== id)
        }));
      }
  };

  const clearToolHistory = (tool: ToolType) => {
      if (window.confirm("Are you sure you want to clear all history for this tool? (မှတ်တမ်းအားလုံးဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({
            ...prev,
            [tool]: []
        }));
      }
  };

  const loadFromHistory = (item: SavedContentItem) => {
      updateCurrentToolState({
          topic: item.prompt,
          generatedContent: item.content || null,
          generatedImage: item.image || null,
          currentSavedItemId: null // Reset saved status since we loaded a copy
      });
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  // Unified Save/Unsave Toggle Function
  const handleToggleSave = () => {
    if (!generatedContent && !generatedImage) return;

    if (currentSavedItemId) {
      // UNSAVE LOGIC
      setSavedContent(prev => prev.filter(item => item.id !== currentSavedItemId));
      updateCurrentToolState({ currentSavedItemId: null });
      return;
    }

    // SAVE LOGIC
    const newId = Date.now().toString();
    const newItem: SavedContentItem = {
      id: newId,
      type: activeTool,
      content: generatedContent || undefined,
      image: generatedImage || undefined,
      prompt: topic || 'Untitled Generation',
      timestamp: Date.now(),
      status: 'Unscheduled'
    };

    setSavedContent(prev => [newItem, ...prev]);
    updateCurrentToolState({ currentSavedItemId: newId });
  };

  const handleDeleteSavedItems = (ids: string[]) => {
    setSavedContent(prev => prev.filter(item => !ids.includes(item.id)));

    // If the currently edited/viewed item is deleted, reset the tool state for it
    if (currentSavedItemId && ids.includes(currentSavedItemId)) {
      updateCurrentToolState({ currentSavedItemId: null });
    }
  };

  const handleUpdateSavedItem = (id: string, newContent: string) => {
    setSavedContent(prev => prev.map(item => 
      item.id === id ? { ...item, content: newContent } : item
    ));
  };

  const handleDeletePost = (id: string) => {
    // Confirmation handled inside ContentCalendar
    const updated = scheduledPosts.filter(p => p.id !== id);
    setScheduledPosts(updated);
  };

  const handleOpenPreview = (img: StoredImage, initialFilter: string = '') => {
    setPreviewImage(img);
    setPreviewFilter(initialFilter);
  };

  const handleEnhanceContent = async () => {
    if (!generatedContent || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      updateCurrentToolState({ generatedContent: enhanced });
    } catch (e) {
      console.error("Failed to enhance", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  // Scheduling Logic
  const checkScheduleConflict = (date: string): boolean => {
    return scheduledPosts.some(post => post.date === date);
  };

  const openScheduleModal = (item?: SavedContentItem) => {
    if (item) {
        setSchedulingItem(item);
    } else {
        setSchedulingItem(null); 
    }
    setScheduleSuccess(false);
    setIsScheduling(true);
  };

  const handleSchedulePost = () => {
    if (!scheduleDate) return;

    // Content source: either from Repository Item OR Current Generator State
    const contentToSchedule = schedulingItem ? schedulingItem.content : generatedContent;
    const titleToSchedule = schedulingItem ? schedulingItem.prompt : topic;
    const typeToSchedule = schedulingItem ? schedulingItem.type : activeTool;

    if (!contentToSchedule && !schedulingItem?.image && !generatedImage) return;

    // Conflict Check
    if (checkScheduleConflict(scheduleDate)) {
        const confirm = window.confirm("အဲ့ဒီအချိန်မှာ Post တစ်ခုရှိပြီးသားပါ။ ထပ်တင်မှာ သေချာပါသလား? (There is already a post on this date. Continue?)");
        if (!confirm) return;
    }

    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date: scheduleDate,
      title: titleToSchedule || 'Generated Content',
      content: contentToSchedule || '[Image Post]',
      platform: schedulePlatform,
      status: 'Scheduled',
      type: typeToSchedule
    };

    setScheduledPosts(prev => [...prev, newPost]);

    // If scheduling from Repo, update status
    if (schedulingItem) {
        setSavedContent(prev => prev.map(item => 
            item.id === schedulingItem.id 
                ? { ...item, status: 'Scheduled', scheduledDate: scheduleDate } 
                : item
        ));
    } else {
        // If scheduling current content, show transient success
        setScheduleSuccess(true);
        setTimeout(() => setScheduleSuccess(false), 3000);
    }

    setIsScheduling(false);
    setScheduleDate('');
    setSchedulingItem(null);
  };

  const handleTourClose = () => {
    setShowTour(false);
    localStorage.setItem(TOUR_KEY, 'true');
  };

  const handleGenerate = async () => {
    if (!topic) return;

    setIsGenerating(true);
    setLoadingProgress(0);
    // Clear previous results while loading
    updateCurrentToolState({ generatedContent: null, generatedImage: null, currentSavedItemId: null });

    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => {
        if (prev >= 90) return prev;
        return prev + Math.floor(Math.random() * 5) + 1;
      });
    }, 800);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;

      if (activeTool === ToolType.IMAGE_GENERATION) {
        let imagePrompt = topic;
        // Construct detailed prompt in service, passing components
        if (imageQuality === 'High') {
          imagePrompt += `, 8k resolution, highly detailed, photorealistic, masterpiece, professional photography`;
        }
        // Additional context and mood handled in service via args or manual append if needed, 
        // but let's pass the raw values to service for cleaner handling

        imageResult = await geminiService.generateImage(
            imagePrompt, 
            aspectRatio, 
            negativePrompt, 
            stylePreset,
            audience, // passing mood/audience
            context // passing context
        );
      } else {
        const request: GenerationRequest = {
          tool: activeTool,
          topic,
          audience,
          additionalContext: context
        };
        contentResult = await geminiService.generateContent(request);
      }

      // Update State
      updateCurrentToolState({
          generatedContent: contentResult,
          generatedImage: imageResult
      });

      // Add to History automatically
      const historyItem: SavedContentItem = {
          id: Date.now().toString(),
          type: activeTool,
          content: contentResult || undefined,
          image: imageResult || undefined,
          prompt: topic,
          timestamp: Date.now(),
          status: 'Unscheduled'
      };
      addToRecentHistory(historyItem);

    } catch (error: any) {
      console.error(error);
      updateCurrentToolState({ generatedContent: "An error occurred while generating content. Please try again." });
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg: Message = {
      role: 'user',
      text: chatInput,
      timestamp: new Date()
    };

    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsGenerating(true);

    try {
      const responseText = await geminiService.sendMessage(userMsg.text);
      const botMsg: Message = {
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, botMsg]);
    } catch (error) {
       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY:
        return {
          title: "Strategic Planner",
          desc: "Create comprehensive marketing strategies for new campaigns or services.",
          placeholder: "e.g., Launching a new comprehensive heart check-up package",
          topicLabel: "Campaign Topic"
        };
      case ToolType.EDUCATIONAL:
        return {
          title: "Educational Content",
          desc: "Build trust with informative posts about medical conditions.",
          placeholder: "e.g., The importance of early cervical cancer screening",
          topicLabel: "Medical Topic"
        };
      case ToolType.SALES:
        return {
          title: "Sales Copy",
          desc: "Convert interest into bookings with persuasive, safe copy.",
          placeholder: "e.g., Promotion for 30% off liver screening in Bangkok",
          topicLabel: "Promotion / Service"
        };
      case ToolType.AD_COPY:
        return {
          title: "Ad Creative",
          desc: "Generate high-converting Facebook ad copy and headlines.",
          placeholder: "e.g., Second opinion services for orthopedics",
          topicLabel: "Ad Subject"
        };
      case ToolType.IMAGE_GENERATION:
        return {
          title: "AI Visual Studio",
          desc: "Create relevant visual assets for your marketing posts.",
          placeholder: "e.g., A modern, clean hospital lobby with friendly staff greeting a patient",
          topicLabel: "Image Description"
        };
      default:
        return { title: "", desc: "", placeholder: "", topicLabel: "Topic" };
    }
  };

  const headerInfo = renderToolHeader();

  const renderLoadingState = () => (
    <div className="flex flex-col items-center justify-center h-full animate-fadeIn transition-opacity duration-300">
      <div className="relative w-24 h-24 mb-6">
        <div className="absolute inset-0 border-4 border-gray-100 rounded-full"></div>
        <div className="absolute inset-0 border-4 border-thai-500 rounded-full border-t-transparent animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center font-bold text-thai-600 text-lg">
          {loadingProgress}%
        </div>
      </div>
      <h3 className="text-xl font-bold text-gray-800 mb-2">
        {activeTool === ToolType.IMAGE_GENERATION ? 'Creating Visuals...' : 'Generating Strategy...'}
      </h3>
      <p className="text-gray-500 text-sm max-w-xs text-center">
        Our AI is analyzing your requirements and crafting professional content for Shwe Thai.
      </p>
    </div>
  );

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
      {/* Input Section */}
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200/60 h-fit sticky top-6 overflow-hidden flex flex-col max-h-[calc(100vh-6rem)]">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100 flex-shrink-0 flex justify-between items-center">
          <div>
            <h2 className="text-lg font-bold text-gray-900 leading-tight">{headerInfo.title}</h2>
            <p className="text-gray-500 text-[10px] font-medium mt-1">{headerInfo.desc}</p>
          </div>
          {/* Tool Icon Placeholder if needed */}
        </div>

        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">
          {/* Main Topic Input */}
          <div>
            <label className="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-2">
              {headerInfo.topicLabel} <span className="text-thai-red">*</span>
            </label>
            <textarea
              value={topic}
              onChange={(e) => updateCurrentToolState({ topic: e.target.value })}
              placeholder={headerInfo.placeholder}
              rows={activeTool === ToolType.IMAGE_GENERATION ? 3 : 2}
              className="w-full px-4 py-3 bg-white text-gray-900 placeholder-gray-400 border-2 border-gray-100 rounded-xl focus:ring-4 focus:ring-thai-500/10 focus:border-thai-500 outline-none transition-all shadow-sm resize-none text-sm font-medium"
            />
          </div>

          {/* Configuration Group */}
          <div className="border border-gray-100 rounded-xl overflow-hidden">
             <button 
               onClick={() => setShowSettings(!showSettings)}
               className="w-full px-4 py-3 bg-gray-50 flex items-center justify-between text-xs font-bold text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-colors"
             >
               <span className="uppercase tracking-wider">Advanced Settings</span>
               <svg className={`w-4 h-4 transition-transform ${showSettings ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
               </svg>
             </button>

             {showSettings && (
               <div className="p-4 bg-white space-y-4 animate-slideDown">
                 {activeTool === ToolType.IMAGE_GENERATION && (
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                          Aspect Ratio
                        </label>
                        <select
                            value={aspectRatio}
                            onChange={(e) => setAspectRatio(e.target.value)}
                            className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                          >
                            <option value={ImageAspectRatio.SQUARE}>Square (1:1)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_4_3}>Landscape (4:3)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_16_9}>Landscape (16:9)</option>
                            <option value={ImageAspectRatio.PORTRAIT_3_4}>Portrait (3:4)</option>
                            <option value={ImageAspectRatio.PORTRAIT_9_16}>Portrait (9:16)</option>
                          </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                          Quality
                        </label>
                          <select
                            value={imageQuality}
                            onChange={(e) => setImageQuality(e.target.value)}
                            className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                          >
                            <option value="Standard">Standard</option>
                            <option value="High">High Detail</option>
                          </select>
                      </div>
                    </div>
                  )}

                  {activeTool === ToolType.IMAGE_GENERATION && (
                     <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                            Artistic Style
                          </label>
                          <select
                              value={stylePreset}
                              onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })}
                              className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                            >
                              {STYLE_PRESETS.map(style => (
                                <option key={style.id} value={style.id}>{style.label}</option>
                              ))}
                            </select>
                        </div>
                         <div>
                            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                              Mood / Lighting
                            </label>
                            <input
                              type="text"
                              value={audience}
                              onChange={(e) => updateCurrentToolState({ audience: e.target.value })}
                              placeholder="e.g., Warm, Cinematic"
                              className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none placeholder-gray-300"
                            />
                        </div>
                     </div>
                  )}

                  {activeTool !== ToolType.IMAGE_GENERATION && (
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                        Target Audience
                        </label>
                        <input
                        type="text"
                        value={audience}
                        onChange={(e) => updateCurrentToolState({ audience: e.target.value })}
                        placeholder="e.g., Women over 40"
                        className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none placeholder-gray-300"
                        />
                    </div>
                  )}

                  {activeTool === ToolType.IMAGE_GENERATION && (
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                          Negative Prompt (Exclude)
                        </label>
                        <input
                          type="text"
                          value={negativePrompt}
                          onChange={(e) => updateCurrentToolState({ negativePrompt: e.target.value })}
                          placeholder="e.g., blur, distorted, text, low quality"
                          className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none placeholder-gray-300"
                        />
                      </div>
                  )}

                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                      Context / Details
                    </label>
                    <textarea
                      value={context}
                      onChange={(e) => updateCurrentToolState({ context: e.target.value })}
                      rows={3}
                      placeholder={activeTool === ToolType.IMAGE_GENERATION ? "e.g., Specific colors, objects to include" : "e.g., Includes free pickup"}
                      className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none resize-none placeholder-gray-300"
                    />
                  </div>
               </div>
             )}
          </div>

          <button
            onClick={handleGenerate}
            disabled={!topic || isGenerating}
            className={`w-full py-3.5 px-4 rounded-xl text-white font-bold shadow-lg shadow-thai-200/50 flex items-center justify-center space-x-2 transition-all duration-300 ease-out transform hover:-translate-y-0.5 active:scale-95 relative overflow-hidden flex-shrink-0 mt-auto
              ${!topic || isGenerating 
                ? 'bg-gray-300 cursor-not-allowed shadow-none' 
                : 'bg-gradient-to-r from-thai-600 to-thai-500 hover:from-thai-700 hover:to-thai-600'
              }`}
          >
             {isGenerating && (
                <div 
                  className="absolute bottom-0 left-0 h-1 bg-white/30 transition-all duration-300 ease-linear"
                  style={{ width: `${loadingProgress}%` }}
                />
             )}
            {isGenerating ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <span className="text-sm">Generating...</span>
              </>
            ) : (
              <>
                <span className="text-sm">Generate</span>
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Output Section */}
      <div className="lg:col-span-8 space-y-4 flex flex-col h-full max-h-[calc(100vh-6rem)]">
