                            className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                          >
                            <option value={ImageAspectRatio.SQUARE}>Square (1:1)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_4_3}>Landscape (4:3)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_16_9}>Landscape (16:9)</option>
                            <option value={ImageAspectRatio.PORTRAIT_3_4}>Portrait (3:4)</option>
                            <option value={ImageAspectRatio.PORTRAIT_9_16}>Portrait (9:16)</option>
