                          <select
                              value={stylePreset}
                              onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })}
                              className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                            >
                              {STYLE_PRESETS.map(style => (
                                <option key={style.id} value={style.id}>{style.label}</option>
