                />
             )}
            {isGenerating ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <span className="text-sm">Generating...</span>
              </>
            ) : (
              <>
                <span className="text-sm">Generate</span>
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Output Section */}
      <div className="lg:col-span-8 space-y-4 flex flex-col h-full max-h-[calc(100vh-6rem)]">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200/60 flex-1 flex flex-col overflow-hidden min-h-[500px]">
          {/* Output Toolbar */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-white flex-shrink-0 z-10 relative">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
               <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
               Preview
            </h3>
            <div className="flex space-x-2">
              {(generatedContent || generatedImage) && (
                <>
                   {generatedContent && (
                    <button 
                      onClick={() => handleCopy(generatedContent || '', 'main-output')}
                      className={`p-2 rounded-lg border transition-all hover:shadow-md active:scale-95 ${
                        copiedId === 'main-output' 
                          ? 'bg-green-50 text-green-700 border-green-200' 
                          : 'bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200'
                      }`}
                      title="Copy Content"
                    >
                      {copiedId === 'main-output' ? (
                           <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                      ) : (
                           <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
                      )}
                    </button>
                   )}
                  {generatedContent && (
                      <button 
                          onClick={handleEnhanceContent}
                          disabled={isEnhancing}
                          className="px-3 py-1.5 rounded-lg text-xs font-bold text-shwe-600 bg-shwe-50 border border-shwe-200 hover:bg-shwe-100 transition-all active:scale-95 flex items-center space-x-1"
                          title="Enhance with AI"
                      >
                          {isEnhancing ? (
                              <svg className="animate-spin w-3.5 h-3.5" viewBox="0 0 24 24" fill="none"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                          ) : (
                              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                          )}
                          <span>Enhance</span>
                      </button>
                  )}
                  <button 
                    onClick={() => openScheduleModal()}
                    className={`p-2 rounded-lg border transition-all hover:shadow-md active:scale-95 ${
                         scheduleSuccess ? 'bg-green-50 text-green-600 border-green-200' : 'bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200'
                    }`}
                    title="Schedule Post"
                  >
                    {scheduleSuccess ? (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                    )}
                  </button>
                  <button 
                    onClick={handleToggleSave}
                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all shadow-sm active:scale-95 flex items-center space-x-2 border ${
                      currentSavedItemId 
                        ? 'bg-green-600 text-white border-green-600 hover:bg-red-600 hover:border-red-600' 
                        : 'bg-thai-600 text-white border-thai-600 hover:bg-thai-700 hover:border-thai-700'
                    }`}
                  >
                      {currentSavedItemId ? (
                        <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                        </svg>
                      ) : (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                      )}
                    <span>{currentSavedItemId ? 'Saved' : 'Save'}</span>
                  </button>
                </>
              )}
              {generatedImage && (
                <a 
                  href={generatedImage} 
                  download="shwethai-generated-image.png"
                  className="p-2 rounded-lg border bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200 transition-all hover:shadow-md active:scale-95"
                  title="Download Image"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                </a>
              )}
            </div>
          </div>

          <div className="flex-1 p-8 bg-white relative overflow-y-auto custom-scrollbar">
            {isGenerating ? (
              renderLoadingState()
            ) : generatedImage ? (
              <div 
                className="flex items-center justify-center h-full bg-gray-50 rounded-xl border border-dashed border-gray-200 p-4 cursor-zoom-in group relative"
                onClick={() => handleOpenPreview({ id: 'gen', data: generatedImage, prompt: topic, timestamp: Date.now() })}
              >
                <img 
                  src={generatedImage} 
                  alt="Generated Marketing Visual" 
                  className="max-w-full max-h-[600px] rounded-lg shadow-lg object-contain transition-transform group-hover:scale-[1.02]"
                />
                <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/5 pointer-events-none">
                  <span className="bg-black/70 text-white text-xs px-3 py-1.5 rounded-full backdrop-blur-sm">Click to Preview</span>
                </div>
              </div>
            ) : generatedContent ? (
              <div className="prose prose-slate max-w-none prose-p:leading-relaxed prose-headings:font-bold prose-headings:text-gray-900 prose-a:text-thai-600">
                <FormattedText text={generatedContent} />
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-300 space-y-4">
                <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center shadow-sm">
                  {activeTool === ToolType.IMAGE_GENERATION ? (
                    <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  ) : (
                    <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  )}
                </div>
                <p className="text-center max-w-xs text-sm font-medium">Ready to create. Enter your details to start.</p>
              </div>
            )}
          </div>
        </div>

        {/* Recent History Section */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200/60 p-4 h-48 flex flex-col">
            <div className="flex justify-between items-center mb-3">
                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider flex items-center gap-1">
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  Recent History
                </h4>
                {(recentHistory[activeTool] || []).length > 0 && (
                    <button 
                        onClick={() => clearToolHistory(activeTool)}
                        className="text-[10px] font-bold text-red-400 hover:text-red-600 px-2 py-1 rounded transition-colors"
                    >
                        Clear All
                    </button>
                )}
            </div>
            <div className="flex-1 overflow-x-auto overflow-y-hidden whitespace-nowrap custom-scrollbar flex space-x-3 items-center">
                {(recentHistory[activeTool] || []).length === 0 ? (
                    <div className="w-full text-center py-4">
                       <p className="text-gray-300 text-xs italic">No recent history</p>
                    </div>
                ) : (
                    (recentHistory[activeTool] || []).map((item) => (
                        <div key={item.id} className="inline-block w-60 h-full bg-white rounded-lg border border-gray-200 p-2 relative group flex flex-col hover:border-thai-200 hover:shadow-md transition-all">
                            <div className="flex justify-between items-start mb-1.5">
                                <p className="text-[10px] font-bold text-gray-800 truncate w-36" title={item.prompt}>{item.prompt}</p>
                                <span className="text-[9px] text-gray-400">{new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                            </div>
                            <div className="flex-1 overflow-hidden relative border border-gray-100 rounded-md bg-gray-50/50">
                                {item.image ? (
                                    <img src={item.image} alt="Thumbnail" className="w-full h-full object-cover rounded" />
                                ) : (
                                    <p className="text-[10px] text-gray-500 whitespace-pre-wrap line-clamp-3 p-2 leading-relaxed">{item.content}</p>
                                )}
                                {/* Overlay Actions */}
                                <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-2">
                                     <button 
                                       onClick={() => loadFromHistory(item)}
                                       className="p-1.5 bg-thai-600 text-white rounded hover:bg-thai-700 shadow-sm" 
                                       title="Load to Editor"
                                     >
                                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                     </button>
                                     <button 
                                       onClick={(e) => {
                                           e.stopPropagation();
                                           deleteFromHistory(activeTool, item.id);
                                       }}
                                       className="p-1.5 bg-red-50 text-red-500 rounded hover:bg-red-100 hover:text-red-600 shadow-sm"
                                       title="Delete"
                                     >
                                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                     </button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
      </div>

      {/* Preview Modal */}
      {previewImage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fadeIn" onClick={() => setPreviewImage(null)}>
          <button 
             className="absolute top-6 right-6 text-white/50 hover:text-white transition-colors p-2"
             onClick={() => setPreviewImage(null)}
          >
             <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>

          <div className="relative w-full max-w-5xl h-full flex flex-col items-center justify-center pointer-events-none" onClick={e => e.stopPropagation()}>
             <img 
               src={previewImage.data} 
               alt={previewImage.prompt} 
               className={`pointer-events-auto max-w-full max-h-[80vh] rounded-lg shadow-2xl object-contain transition-all duration-300 ${previewFilter}`} 
             />
             <div className="pointer-events-auto mt-6 flex space-x-3 overflow-x-auto max-w-full p-2 bg-black/20 backdrop-blur-sm rounded-full">
                {IMAGE_FILTERS.map(filter => (
                   <button
                     key={filter.id}
                     onClick={() => setPreviewFilter(filter.class)}
                     className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all whitespace-nowrap ${
                       previewFilter === filter.class 
                         ? 'bg-white text-black shadow-lg scale-105' 
                         : 'bg-white/10 text-white hover:bg-white/20'
                     }`}
                   >
                     {filter.label}
                   </button>
                ))}
             </div>
          </div>
        </div>
      )}

      {/* Schedule Modal */}
      {isScheduling && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setIsScheduling(false)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                 <h3 className="text-lg font-bold text-gray-900">Schedule Content</h3>
                 <button onClick={() => setIsScheduling(false)} className="text-gray-400 hover:text-gray-600">
                   <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>
              <div className="p-6 space-y-5">
                 <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Publish Date</label>
                    <input 
                      type="date" 
                      value={scheduleDate}
                      onChange={(e) => setScheduleDate(e.target.value)}
                      className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all"
                      min={new Date().toISOString().split('T')[0]}
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Platform</label>
                    <div className="grid grid-cols-2 gap-3">
                    {['Facebook', 'Telegram', 'Viber', 'TikTok'].map(p => (
                        <button
                            key={p}
                            onClick={() => setSchedulePlatform(p as any)}
                            className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${
                                schedulePlatform === p 
                                ? 'bg-thai-50 border-thai-200 text-thai-700 shadow-sm' 
                                : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                        >
                            {p}
                        </button>
                    ))}
                    </div>
                 </div>
              </div>
              <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end space-x-3">
                 <button onClick={() => setIsScheduling(false)} className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors">Cancel</button>
                 <button 
                   onClick={handleSchedulePost}
                   disabled={!scheduleDate}
                   className={`px-6 py-2 text-sm font-bold text-white rounded-lg shadow-md transition-all transform hover:-translate-y-0.5 active:scale-95 ${
                      !scheduleDate ? 'bg-gray-300 cursor-not-allowed shadow-none' : 'bg-thai-600 hover:bg-thai-700'
                   }`}
                 >
                   Confirm
                 </button>
              </div>
           </div>
        </div>
      )}

      <OnboardingTour isOpen={showTour} onClose={handleTourClose} />
    </>
  );
};

export default App;

