                )}
            </div>
        </div>
      </div>

      {/* Preview Modal */}
      {previewImage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fadeIn" onClick={() => setPreviewImage(null)}>
          <button 
             className="absolute top-6 right-6 text-white/50 hover:text-white transition-colors p-2"
             onClick={() => setPreviewImage(null)}
          >
             <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>

          <div className="relative w-full max-w-5xl h-full flex flex-col items-center justify-center pointer-events-none" onClick={e => e.stopPropagation()}>
             <img 
               src={previewImage.data} 
               alt={previewImage.prompt} 
               className={`pointer-events-auto max-w-full max-h-[80vh] rounded-lg shadow-2xl object-contain transition-all duration-300 ${previewFilter}`} 
             />
             <div className="pointer-events-auto mt-6 flex space-x-3 overflow-x-auto max-w-full p-2 bg-black/20 backdrop-blur-sm rounded-full">
                {IMAGE_FILTERS.map(filter => (
                   <button
                     key={filter.id}
                     onClick={() => setPreviewFilter(filter.class)}
                     className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all whitespace-nowrap ${
                       previewFilter === filter.class 
                         ? 'bg-white text-black shadow-lg scale-105' 
                         : 'bg-white/10 text-white hover:bg-white/20'
                     }`}
                   >
                     {filter.label}
                   </button>
                ))}
             </div>
          </div>
        </div>
      )}

      {/* Schedule Modal */}
      {isScheduling && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setIsScheduling(false)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                 <h3 className="text-lg font-bold text-gray-900">Schedule Content</h3>
                 <button onClick={() => setIsScheduling(false)} className="text-gray-400 hover:text-gray-600">
                   <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>
              <div className="p-6 space-y-5">
                 <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Publish Date</label>
                    <input 
                      type="date" 
                      value={scheduleDate}
                      onChange={(e) => setScheduleDate(e.target.value)}
                      className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all"
                      min={new Date().toISOString().split('T')[0]}
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Platform</label>
                    <div className="grid grid-cols-2 gap-3">
                    {['Facebook', 'Telegram', 'Viber', 'TikTok'].map(p => (
                        <button
                            key={p}
                            onClick={() => setSchedulePlatform(p as any)}
                            className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${
                                schedulePlatform === p 
                                ? 'bg-thai-50 border-thai-200 text-thai-700 shadow-sm' 
                                : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                        >
                            {p}
                        </button>
                    ))}
                    </div>
                 </div>
              </div>
              <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end space-x-3">
                 <button onClick={() => setIsScheduling(false)} className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors">Cancel</button>
                 <button 
                   onClick={handleSchedulePost}
                   disabled={!scheduleDate}
                   className={`px-6 py-2 text-sm font-bold text-white rounded-lg shadow-md transition-all transform hover:-translate-y-0.5 active:scale-95 ${
                      !scheduleDate ? 'bg-gray-300 cursor-not-allowed shadow-none' : 'bg-thai-600 hover:bg-thai-700'
                   }`}
                 >
                   Confirm
                 </button>
              </div>
           </div>
        </div>
      )}

      <OnboardingTour isOpen={showTour} onClose={handleTourClose} />
    </>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, GenerationRequest, Message, StoredImage, ImageAspectRatio, ScheduledPost, SavedContentItem } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { SavedContentRepo } from './components/SavedContentRepo';
import { OnboardingTour } from './components/OnboardingTour';
import { ContentCalendar } from './components/ContentCalendar';
import { LandingPage } from './components/LandingPage';

const STORAGE_KEY = 'SHWETHAI_GALLERY';
const SAVED_CONTENT_KEY = 'SHWETHAI_SAVED_CONTENT';
const PREFS_KEY = 'SHWETHAI_IMAGE_PREFS';
const TOUR_KEY = 'SHWETHAI_TOUR_COMPLETED';
const CALENDAR_KEY = 'SHWETHAI_CALENDAR';
const HISTORY_KEY = 'SHWETHAI_RECENT_HISTORY';

const IMAGE_FILTERS = [
  { id: 'none', label: 'Original', class: '' },
  { id: 'grayscale', label: 'B&W', class: 'grayscale' },
  { id: 'sepia', label: 'Sepia', class: 'sepia' },
  { id: 'warm', label: 'Warm', class: 'sepia-[.5] contrast-100' },
  { id: 'cool', label: 'Cool', class: 'hue-rotate-180 saturate-50' },
  { id: 'vintage', label: 'Vintage', class: 'sepia-[.3] contrast-125 brightness-90' },
  { id: 'blur', label: 'Blur', class: 'blur-[2px]' },
];

const STYLE_PRESETS = [
  { id: 'none', label: 'None (Default)' },
  { id: 'photorealistic', label: 'Photorealistic' },
  { id: 'cinematic', label: 'Cinematic' },
  { id: 'digital-art', label: 'Digital Art' },
  { id: 'anime', label: 'Anime / Manga' },
  { id: '3d-model', label: '3D Model' },
  { id: 'line-art', label: 'Line Art' },
  { id: 'watercolor', label: 'Watercolor' },
  { id: 'cyberpunk', label: 'Cyberpunk' },
  { id: 'minimalist', label: 'Minimalist' },
];

// Define state structure for a tool to allow persistence
interface ToolState {
  topic: string;
  audience: string;
  context: string;
  generatedContent: string | null;
  generatedImage: string | null;
  currentSavedItemId: string | null;
  // New fields for Image Gen
  negativePrompt: string;
  stylePreset: string;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  generatedContent: null,
  generatedImage: null,
  currentSavedItemId: null,
  negativePrompt: '',
  stylePreset: 'none'
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);

  // Persistent Tool State
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});

  // History State (per tool, limit 5)
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});

  // Image Generator Preferences
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);

  // Feedback States
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [scheduleSuccess, setScheduleSuccess] = useState(false);

  // Global Repositories
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]); 
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);

  // Preview / Creative Studio State
  const [previewImage, setPreviewImage] = useState<StoredImage | null>(null);
  const [previewFilter, setPreviewFilter] = useState<string>('');

  // Calendar State
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false); // Modal trigger
  const [schedulingItem, setSchedulingItem] = useState<SavedContentItem | null>(null); // Item being scheduled from repo
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');

  // Tour State
  const [showTour, setShowTour] = useState(false);

  // Chat State
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Helper to access current tool's state safely
  const getCurrentToolState = () => {
    return toolStates[activeTool] || INITIAL_TOOL_STATE;
  };

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId, negativePrompt, stylePreset } = getCurrentToolState();

  // Load data from local storage
  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) setStoredImages(JSON.parse(savedImages));

      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));

      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));

      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }

      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));

      // Don't show tour immediately if landing page is active, 
      // instead, we'll check this when entering the app
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  const handleStartApp = () => {
      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) {
          setTimeout(() => setShowTour(true), 1000);
      }
  };

  // Save preferences
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality }));
  }, [aspectRatio, imageQuality]);

  // Save calendar
  useEffect(() => {
    localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts));
  }, [scheduledPosts]);

  // Save Content Repo
  useEffect(() => {
    localStorage.setItem(SAVED_CONTENT_KEY, JSON.stringify(savedContent));
  }, [savedContent]);

  // Save History
  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(recentHistory));
  }, [recentHistory]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  // History Helper
  const addToRecentHistory = (item: SavedContentItem) => {
    setRecentHistory(prev => {
      const toolHistory = prev[activeTool] || [];
      // Add to front, limit to 5, avoid duplicates based on content if possible
      const newHistory = [item, ...toolHistory].slice(0, 5);
      return { ...prev, [activeTool]: newHistory };
    });
  };

  const deleteFromHistory = (tool: ToolType, id: string) => {
      if (window.confirm("Are you sure you want to delete this from recent history? (ဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({
            ...prev,
            [tool]: (prev[tool] || []).filter(item => item.id !== id)
        }));
      }
  };

  const clearToolHistory = (tool: ToolType) => {
      if (window.confirm("Are you sure you want to clear all history for this tool? (မှတ်တမ်းအားလုံးဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({
            ...prev,
            [tool]: []
        }));
      }
  };

  const loadFromHistory = (item: SavedContentItem) => {
      updateCurrentToolState({
          topic: item.prompt,
          generatedContent: item.content || null,
          generatedImage: item.image || null,
          currentSavedItemId: null // Reset saved status since we loaded a copy
      });
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  // Unified Save/Unsave Toggle Function
  const handleToggleSave = () => {
    if (!generatedContent && !generatedImage) return;

    if (currentSavedItemId) {
      // UNSAVE LOGIC
      setSavedContent(prev => prev.filter(item => item.id !== currentSavedItemId));
      updateCurrentToolState({ currentSavedItemId: null });
      return;
    }

    // SAVE LOGIC
    const newId = Date.now().toString();
    const newItem: SavedContentItem = {
      id: newId,
      type: activeTool,
      content: generatedContent || undefined,
      image: generatedImage || undefined,
      prompt: topic || 'Untitled Generation',
      timestamp: Date.now(),
      status: 'Unscheduled'
    };

    setSavedContent(prev => [newItem, ...prev]);
    updateCurrentToolState({ currentSavedItemId: newId });
  };

  const handleDeleteSavedItems = (ids: string[]) => {
    setSavedContent(prev => prev.filter(item => !ids.includes(item.id)));

    // If the currently edited/viewed item is deleted, reset the tool state for it
    if (currentSavedItemId && ids.includes(currentSavedItemId)) {
      updateCurrentToolState({ currentSavedItemId: null });
    }
  };

  const handleUpdateSavedItem = (id: string, newContent: string) => {
    setSavedContent(prev => prev.map(item => 
      item.id === id ? { ...item, content: newContent } : item
    ));
  };

  const handleDeletePost = (id: string) => {
    // Confirmation handled inside ContentCalendar
    const updated = scheduledPosts.filter(p => p.id !== id);
    setScheduledPosts(updated);
  };

  const handleOpenPreview = (img: StoredImage, initialFilter: string = '') => {
    setPreviewImage(img);
    setPreviewFilter(initialFilter);
  };

  const handleEnhanceContent = async () => {
    if (!generatedContent || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      updateCurrentToolState({ generatedContent: enhanced });
    } catch (e) {
      console.error("Failed to enhance", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  // Scheduling Logic
  const checkScheduleConflict = (date: string): boolean => {
    return scheduledPosts.some(post => post.date === date);
  };

  const openScheduleModal = (item?: SavedContentItem) => {
    if (item) {
        setSchedulingItem(item);
    } else {
        setSchedulingItem(null); 
    }
    setScheduleSuccess(false);
    setIsScheduling(true);
  };

  const handleSchedulePost = () => {
    if (!scheduleDate) return;

    // Content source: either from Repository Item OR Current Generator State
    const contentToSchedule = schedulingItem ? schedulingItem.content : generatedContent;
    const titleToSchedule = schedulingItem ? schedulingItem.prompt : topic;
    const typeToSchedule = schedulingItem ? schedulingItem.type : activeTool;

    if (!contentToSchedule && !schedulingItem?.image && !generatedImage) return;

    // Conflict Check
    if (checkScheduleConflict(scheduleDate)) {
        const confirm = window.confirm("အဲ့ဒီအချိန်မှာ Post တစ်ခုရှိပြီးသားပါ။ ထပ်တင်မှာ သေချာပါသလား? (There is already a post on this date. Continue?)");
        if (!confirm) return;
    }

    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date: scheduleDate,
      title: titleToSchedule || 'Generated Content',
      content: contentToSchedule || '[Image Post]',
      platform: schedulePlatform,
      status: 'Scheduled',
      type: typeToSchedule
    };

    setScheduledPosts(prev => [...prev, newPost]);

    // If scheduling from Repo, update status
    if (schedulingItem) {
        setSavedContent(prev => prev.map(item => 
            item.id === schedulingItem.id 
                ? { ...item, status: 'Scheduled', scheduledDate: scheduleDate } 
                : item
        ));
    } else {
        // If scheduling current content, show transient success
        setScheduleSuccess(true);
        setTimeout(() => setScheduleSuccess(false), 3000);
    }

    setIsScheduling(false);
    setScheduleDate('');
    setSchedulingItem(null);
  };

  const handleTourClose = () => {
    setShowTour(false);
    localStorage.setItem(TOUR_KEY, 'true');
  };

  const handleGenerate = async () => {
    if (!topic) return;

    setIsGenerating(true);
    setLoadingProgress(0);
    // Clear previous results while loading
    updateCurrentToolState({ generatedContent: null, generatedImage: null, currentSavedItemId: null });

    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => {
        if (prev >= 90) return prev;
        return prev + Math.floor(Math.random() * 5) + 1;
      });
    }, 800);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;

      if (activeTool === ToolType.IMAGE_GENERATION) {
        let imagePrompt = topic;
        // Construct detailed prompt in service, passing components
        if (imageQuality === 'High') {
          imagePrompt += `, 8k resolution, highly detailed, photorealistic, masterpiece, professional photography`;
        }
        // Additional context and mood handled in service via args or manual append if needed, 
        // but let's pass the raw values to service for cleaner handling

        imageResult = await geminiService.generateImage(
            imagePrompt, 
            aspectRatio, 
            negativePrompt, 
            stylePreset,
            audience, // passing mood/audience
            context // passing context
        );
      } else {
        const request: GenerationRequest = {
          tool: activeTool,
          topic,
          audience,
          additionalContext: context
        };
        contentResult = await geminiService.generateContent(request);
      }

      // Update State
      updateCurrentToolState({
          generatedContent: contentResult,
          generatedImage: imageResult
      });

      // Add to History automatically
      const historyItem: SavedContentItem = {
          id: Date.now().toString(),
          type: activeTool,
          content: contentResult || undefined,
          image: imageResult || undefined,
          prompt: topic,
          timestamp: Date.now(),
          status: 'Unscheduled'
      };
      addToRecentHistory(historyItem);

    } catch (error: any) {
      console.error(error);
      updateCurrentToolState({ generatedContent: "An error occurred while generating content. Please try again." });
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleChatSend = async () => {
    if (!chatInput.trim() || isGenerating) return;

    const userMsg: Message = {
      role: 'user',
      text: chatInput,
      timestamp: new Date()
    };

    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsGenerating(true);

    try {
      const responseText = await geminiService.sendMessage(userMsg.text);
      const botMsg: Message = {
        role: 'model',
        text: responseText,
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, botMsg]);
    } catch (error) {
       const errorMsg: Message = {
        role: 'model',
        text: "I'm having trouble connecting right now. Please try again.",
        timestamp: new Date()
      };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY:
        return {
          title: "Strategic Planner",
          desc: "Create comprehensive marketing strategies for new campaigns or services.",
          placeholder: "e.g., Launching a new comprehensive heart check-up package",
          topicLabel: "Campaign Topic"
        };
      case ToolType.EDUCATIONAL:
        return {
          title: "Educational Content",
          desc: "Build trust with informative posts about medical conditions.",
          placeholder: "e.g., The importance of early cervical cancer screening",
          topicLabel: "Medical Topic"
        };
      case ToolType.SALES:
        return {
          title: "Sales Copy",
          desc: "Convert interest into bookings with persuasive, safe copy.",
          placeholder: "e.g., Promotion for 30% off liver screening in Bangkok",
          topicLabel: "Promotion / Service"
        };
      case ToolType.AD_COPY:
        return {
          title: "Ad Creative",
          desc: "Generate high-converting Facebook ad copy and headlines.",
          placeholder: "e.g., Second opinion services for orthopedics",
          topicLabel: "Ad Subject"
        };
      case ToolType.IMAGE_GENERATION:
        return {
          title: "AI Visual Studio",
          desc: "Create relevant visual assets for your marketing posts.",
          placeholder: "e.g., A modern, clean hospital lobby with friendly staff greeting a patient",
          topicLabel: "Image Description"
        };
      default:
        return { title: "", desc: "", placeholder: "", topicLabel: "Topic" };
    }
  };

  const headerInfo = renderToolHeader();

  const renderLoadingState = () => (
    <div className="flex flex-col items-center justify-center h-full animate-fadeIn transition-opacity duration-300">
      <div className="relative w-24 h-24 mb-6">
        <div className="absolute inset-0 border-4 border-gray-100 rounded-full"></div>
        <div className="absolute inset-0 border-4 border-thai-500 rounded-full border-t-transparent animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center font-bold text-thai-600 text-lg">
          {loadingProgress}%
        </div>
      </div>
      <h3 className="text-xl font-bold text-gray-800 mb-2">
        {activeTool === ToolType.IMAGE_GENERATION ? 'Creating Visuals...' : 'Generating Strategy...'}
      </h3>
      <p className="text-gray-500 text-sm max-w-xs text-center">
        Our AI is analyzing your requirements and crafting professional content for Shwe Thai.
      </p>
    </div>
  );

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
      {/* Input Section */}
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200/60 h-fit sticky top-6 overflow-hidden flex flex-col max-h-[calc(100vh-6rem)]">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100 flex-shrink-0 flex justify-between items-center">
          <div>
            <h2 className="text-lg font-bold text-gray-900 leading-tight">{headerInfo.title}</h2>
            <p className="text-gray-500 text-[10px] font-medium mt-1">{headerInfo.desc}</p>
          </div>
          {/* Tool Icon Placeholder if needed */}
        </div>

        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">
          {/* Main Topic Input */}
          <div>
            <label className="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-2">
              {headerInfo.topicLabel} <span className="text-thai-red">*</span>
            </label>
            <textarea
              value={topic}
              onChange={(e) => updateCurrentToolState({ topic: e.target.value })}
              placeholder={headerInfo.placeholder}
              rows={activeTool === ToolType.IMAGE_GENERATION ? 3 : 2}
              className="w-full px-4 py-3 bg-white text-gray-900 placeholder-gray-400 border-2 border-gray-100 rounded-xl focus:ring-4 focus:ring-thai-500/10 focus:border-thai-500 outline-none transition-all shadow-sm resize-none text-sm font-medium"
            />
          </div>

          {/* Configuration Group */}
          <div className="border border-gray-100 rounded-xl overflow-hidden">
             <button 
               onClick={() => setShowSettings(!showSettings)}
               className="w-full px-4 py-3 bg-gray-50 flex items-center justify-between text-xs font-bold text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-colors"
             >
               <span className="uppercase tracking-wider">Advanced Settings</span>
               <svg className={`w-4 h-4 transition-transform ${showSettings ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
               </svg>
             </button>

             {showSettings && (
               <div className="p-4 bg-white space-y-4 animate-slideDown">
                 {activeTool === ToolType.IMAGE_GENERATION && (
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                          Aspect Ratio
                        </label>
                        <select
                            value={aspectRatio}
                            onChange={(e) => setAspectRatio(e.target.value)}
                            className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                          >
                            <option value={ImageAspectRatio.SQUARE}>Square (1:1)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_4_3}>Landscape (4:3)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_16_9}>Landscape (16:9)</option>
                            <option value={ImageAspectRatio.PORTRAIT_3_4}>Portrait (3:4)</option>
                            <option value={ImageAspectRatio.PORTRAIT_9_16}>Portrait (9:16)</option>
                          </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                          Quality
                        </label>
                          <select
                            value={imageQuality}
                            onChange={(e) => setImageQuality(e.target.value)}
                            className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                          >
                            <option value="Standard">Standard</option>
                            <option value="High">High Detail</option>
                          </select>
                      </div>
                    </div>
                  )}

                  {activeTool === ToolType.IMAGE_GENERATION && (
                     <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                            Artistic Style
                          </label>
                          <select
                              value={stylePreset}
                              onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })}
                              className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none"
                            >
                              {STYLE_PRESETS.map(style => (
                                <option key={style.id} value={style.id}>{style.label}</option>
                              ))}
                            </select>
                        </div>
                         <div>
                            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                              Mood / Lighting
                            </label>
                            <input
                              type="text"
                              value={audience}
                              onChange={(e) => updateCurrentToolState({ audience: e.target.value })}
                              placeholder="e.g., Warm, Cinematic"
                              className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none placeholder-gray-300"
                            />
                        </div>
                     </div>
                  )}

                  {activeTool !== ToolType.IMAGE_GENERATION && (
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                        Target Audience
                        </label>
                        <input
                        type="text"
                        value={audience}
                        onChange={(e) => updateCurrentToolState({ audience: e.target.value })}
                        placeholder="e.g., Women over 40"
                        className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none placeholder-gray-300"
                        />
                    </div>
                  )}

                  {activeTool === ToolType.IMAGE_GENERATION && (
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                          Negative Prompt (Exclude)
                        </label>
                        <input
                          type="text"
                          value={negativePrompt}
                          onChange={(e) => updateCurrentToolState({ negativePrompt: e.target.value })}
                          placeholder="e.g., blur, distorted, text, low quality"
                          className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none placeholder-gray-300"
                        />
                      </div>
                  )}

                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">
                      Context / Details
                    </label>
                    <textarea
                      value={context}
                      onChange={(e) => updateCurrentToolState({ context: e.target.value })}
                      rows={3}
                      placeholder={activeTool === ToolType.IMAGE_GENERATION ? "e.g., Specific colors, objects to include" : "e.g., Includes free pickup"}
                      className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none resize-none placeholder-gray-300"
                    />
                  </div>
               </div>
             )}
          </div>

          <button
            onClick={handleGenerate}
            disabled={!topic || isGenerating}
            className={`w-full py-3.5 px-4 rounded-xl text-white font-bold shadow-lg shadow-thai-200/50 flex items-center justify-center space-x-2 transition-all duration-300 ease-out transform hover:-translate-y-0.5 active:scale-95 relative overflow-hidden flex-shrink-0 mt-auto
              ${!topic || isGenerating 
                ? 'bg-gray-300 cursor-not-allowed shadow-none' 
                : 'bg-gradient-to-r from-thai-600 to-thai-500 hover:from-thai-700 hover:to-thai-600'
              }`}
          >
             {isGenerating && (
                <div 
                  className="absolute bottom-0 left-0 h-1 bg-white/30 transition-all duration-300 ease-linear"
                  style={{ width: `${loadingProgress}%` }}
                />
             )}
            {isGenerating ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                <span className="text-sm">Generating...</span>
              </>
            ) : (
              <>
                <span className="text-sm">Generate</span>
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              </>
            )}
          </button>
        </div>
      </div>

      {/* Output Section */}
      <div className="lg:col-span-8 space-y-4 flex flex-col h-full max-h-[calc(100vh-6rem)]">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200/60 flex-1 flex flex-col overflow-hidden min-h-[500px]">
          {/* Output Toolbar */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-white flex-shrink-0 z-10 relative">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
               <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
               Preview
            </h3>
            <div className="flex space-x-2">
              {(generatedContent || generatedImage) && (
                <>
                   {generatedContent && (
                    <button 
                      onClick={() => handleCopy(generatedContent || '', 'main-output')}
                      className={`p-2 rounded-lg border transition-all hover:shadow-md active:scale-95 ${
                        copiedId === 'main-output' 
                          ? 'bg-green-50 text-green-700 border-green-200' 
                          : 'bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200'
                      }`}
                      title="Copy Content"
                    >
                      {copiedId === 'main-output' ? (
                           <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                      ) : (
                           <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
                      )}
                    </button>
                   )}
                  {generatedContent && (
                      <button 
                          onClick={handleEnhanceContent}
                          disabled={isEnhancing}
                          className="px-3 py-1.5 rounded-lg text-xs font-bold text-shwe-600 bg-shwe-50 border border-shwe-200 hover:bg-shwe-100 transition-all active:scale-95 flex items-center space-x-1"
                          title="Enhance with AI"
                      >
                          {isEnhancing ? (
                              <svg className="animate-spin w-3.5 h-3.5" viewBox="0 0 24 24" fill="none"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                          ) : (
                              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                          )}
                          <span>Enhance</span>
                      </button>
                  )}
                  <button 
                    onClick={() => openScheduleModal()}
                    className={`p-2 rounded-lg border transition-all hover:shadow-md active:scale-95 ${
                         scheduleSuccess ? 'bg-green-50 text-green-600 border-green-200' : 'bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200'
                    }`}
                    title="Schedule Post"
                  >
                    {scheduleSuccess ? (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                    )}
                  </button>
                  <button 
                    onClick={handleToggleSave}
                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all shadow-sm active:scale-95 flex items-center space-x-2 border ${
                      currentSavedItemId 
                        ? 'bg-green-600 text-white border-green-600 hover:bg-red-600 hover:border-red-600' 
                        : 'bg-thai-600 text-white border-thai-600 hover:bg-thai-700 hover:border-thai-700'
                    }`}
                  >
                      {currentSavedItemId ? (
                        <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                        </svg>
                      ) : (
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 5a2 2 0 012-2h10a2 2 0 012 2v16l-7-3.5L5 21V5z" /></svg>
                      )}
                    <span>{currentSavedItemId ? 'Saved' : 'Save'}</span>
                  </button>
                </>
              )}
              {generatedImage && (
                <a 
                  href={generatedImage} 
                  download="shwethai-generated-image.png"
                  className="p-2 rounded-lg border bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200 transition-all hover:shadow-md active:scale-95"
                  title="Download Image"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                </a>
              )}
            </div>
          </div>

          <div className="flex-1 p-8 bg-white relative overflow-y-auto custom-scrollbar">
            {isGenerating ? (
              renderLoadingState()
            ) : generatedImage ? (
              <div 
                className="flex items-center justify-center h-full bg-gray-50 rounded-xl border border-dashed border-gray-200 p-4 cursor-zoom-in group relative"
                onClick={() => handleOpenPreview({ id: 'gen', data: generatedImage, prompt: topic, timestamp: Date.now() })}
              >
                <img 
                  src={generatedImage} 
                  alt="Generated Marketing Visual" 
                  className="max-w-full max-h-[600px] rounded-lg shadow-lg object-contain transition-transform group-hover:scale-[1.02]"
                />
                <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/5 pointer-events-none">
                  <span className="bg-black/70 text-white text-xs px-3 py-1.5 rounded-full backdrop-blur-sm">Click to Preview</span>
                </div>
              </div>
            ) : generatedContent ? (
              <div className="prose prose-slate max-w-none prose-p:leading-relaxed prose-headings:font-bold prose-headings:text-gray-900 prose-a:text-thai-600">
                <FormattedText text={generatedContent} />
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-300 space-y-4">
                <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center shadow-sm">
                  {activeTool === ToolType.IMAGE_GENERATION ? (
                    <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  ) : (
                    <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  )}
                </div>
                <p className="text-center max-w-xs text-sm font-medium">Ready to create. Enter your details to start.</p>
              </div>
            )}
          </div>
        </div>

        {/* Recent History Section */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200/60 p-4 h-48 flex flex-col">
            <div className="flex justify-between items-center mb-3">
                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider flex items-center gap-1">
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  Recent History
                </h4>
                {(recentHistory[activeTool] || []).length > 0 && (
                    <button 
                        onClick={() => clearToolHistory(activeTool)}
                        className="text-[10px] font-bold text-red-400 hover:text-red-600 px-2 py-1 rounded transition-colors"
                    >
                        Clear All
                    </button>
                )}
            </div>
            <div className="flex-1 overflow-x-auto overflow-y-hidden whitespace-nowrap custom-scrollbar flex space-x-3 items-center">
                {(recentHistory[activeTool] || []).length === 0 ? (
                    <div className="w-full text-center py-4">
                       <p className="text-gray-300 text-xs italic">No recent history</p>
                    </div>
                ) : (
                    (recentHistory[activeTool] || []).map((item) => (
                        <div key={item.id} className="inline-block w-60 h-full bg-white rounded-lg border border-gray-200 p-2 relative group flex flex-col hover:border-thai-200 hover:shadow-md transition-all">
                            <div className="flex justify-between items-start mb-1.5">
                                <p className="text-[10px] font-bold text-gray-800 truncate w-36" title={item.prompt}>{item.prompt}</p>
                                <span className="text-[9px] text-gray-400">{new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                            </div>
                            <div className="flex-1 overflow-hidden relative border border-gray-100 rounded-md bg-gray-50/50">
                                {item.image ? (
                                    <img src={item.image} alt="Thumbnail" className="w-full h-full object-cover rounded" />
                                ) : (
                                    <p className="text-[10px] text-gray-500 whitespace-pre-wrap line-clamp-3 p-2 leading-relaxed">{item.content}</p>
                                )}
                                {/* Overlay Actions */}
                                <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-2">
                                     <button 
                                       onClick={() => loadFromHistory(item)}
                                       className="p-1.5 bg-thai-600 text-white rounded hover:bg-thai-700 shadow-sm" 
                                       title="Load to Editor"
                                     >
                                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                     </button>
                                     <button 
                                       onClick={(e) => {
                                           e.stopPropagation();
                                           deleteFromHistory(activeTool, item.id);
                                       }}
                                       className="p-1.5 bg-red-50 text-red-500 rounded hover:bg-red-100 hover:text-red-600 shadow-sm"
                                       title="Delete"
                                     >
                                        <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                     </button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
      </div>
    </div>
  );

  if (showLanding) {
    return <LandingPage onStart={handleStartApp} />;
  }

  return (
    <Layout 
      activeTool={activeTool} 
      onToolChange={setActiveTool} 
      onBackHome={() => setShowLanding(true)}
    >
      {activeTool === ToolType.CALENDAR ? (
         <ContentCalendar 
           posts={scheduledPosts} 
           onDeletePost={handleDeletePost} 
         />
      ) : activeTool === ToolType.SAVED_CONTENT ? (
         <SavedContentRepo 
            items={savedContent} 
            onDelete={handleDeleteSavedItems}
            onSchedule={openScheduleModal}
            onViewImage={handleOpenPreview}
            onUpdate={handleUpdateSavedItem}
         />
      ) : (
         renderGenerator()
      )}

      {/* Preview Modal */}
      {previewImage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fadeIn" onClick={() => setPreviewImage(null)}>
          <button 
             className="absolute top-6 right-6 text-white/50 hover:text-white transition-colors p-2"
             onClick={() => setPreviewImage(null)}
          >
             <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>

          <div className="relative w-full max-w-5xl h-full flex flex-col items-center justify-center pointer-events-none" onClick={e => e.stopPropagation()}>
             <img 
               src={previewImage.data} 
               alt={previewImage.prompt} 
               className={`pointer-events-auto max-w-full max-h-[80vh] rounded-lg shadow-2xl object-contain transition-all duration-300 ${previewFilter}`} 
             />
             <div className="pointer-events-auto mt-6 flex space-x-3 overflow-x-auto max-w-full p-2 bg-black/20 backdrop-blur-sm rounded-full">
                {IMAGE_FILTERS.map(filter => (
                   <button
                     key={filter.id}
                     onClick={() => setPreviewFilter(filter.class)}
                     className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all whitespace-nowrap ${
                       previewFilter === filter.class 
                         ? 'bg-white text-black shadow-lg scale-105' 
                         : 'bg-white/10 text-white hover:bg-white/20'
                     }`}
                   >
                     {filter.label}
                   </button>
                ))}
             </div>
          </div>
        </div>
      )}

      {/* Schedule Modal */}
      {isScheduling && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setIsScheduling(false)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                 <h3 className="text-lg font-bold text-gray-900">Schedule Content</h3>
                 <button onClick={() => setIsScheduling(false)} className="text-gray-400 hover:text-gray-600">
                   <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
              </div>
              <div className="p-6 space-y-5">
                 <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Publish Date</label>
                    <input 
                      type="date" 
                      value={scheduleDate}
                      onChange={(e) => setScheduleDate(e.target.value)}
                      className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-thai-500/20 focus:border-thai-500 outline-none transition-all"
                      min={new Date().toISOString().split('T')[0]}
                    />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Platform</label>
                    <div className="grid grid-cols-2 gap-3">
                    {['Facebook', 'Telegram', 'Viber', 'TikTok'].map(p => (
                        <button
                            key={p}
                            onClick={() => setSchedulePlatform(p as any)}
                            className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${
                                schedulePlatform === p 
                                ? 'bg-thai-50 border-thai-200 text-thai-700 shadow-sm' 
                                : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                        >
                            {p}
                        </button>
                    ))}
                    </div>
                 </div>
              </div>
              <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end space-x-3">
                 <button onClick={() => setIsScheduling(false)} className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors">Cancel</button>
                 <button 
                   onClick={handleSchedulePost}
                   disabled={!scheduleDate}
                   className={`px-6 py-2 text-sm font-bold text-white rounded-lg shadow-md transition-all transform hover:-translate-y-0.5 active:scale-95 ${
                      !scheduleDate ? 'bg-gray-300 cursor-not-allowed shadow-none' : 'bg-thai-600 hover:bg-thai-700'
                   }`}
                 >
                   Confirm
                 </button>
              </div>
           </div>
        </div>
      )}

      <OnboardingTour isOpen={showTour} onClose={handleTourClose} />
    </Layout>
  );
};

export default App;

import React from 'react';

// A simple text formatter for the single-file constraint
// It converts **text** to bold and handles newlines
const FormattedText: React.FC<{ text: string }> = ({ text }) => {
  if (!text) return null;

  const paragraphs = text.split('\n');

  return (
    <div className="font-burmese text-gray-800 leading-loose tracking-wide">
      {paragraphs.map((paragraph, idx) => {
        // Simple header detection
        if (paragraph.startsWith('### ')) {
          return <h3 key={idx} className="text-lg font-bold text-thai-600 mt-6 mb-2">{paragraph.replace('### ', '')}</h3>
        }
        if (paragraph.startsWith('## ')) {
          return <h2 key={idx} className="text-xl font-bold text-gray-900 mt-8 mb-3 border-b pb-2">{paragraph.replace('## ', '')}</h2>
        }
        if (paragraph.startsWith('**') && paragraph.endsWith('**')) {
           return <h4 key={idx} className="font-bold text-gray-800 mt-4 mb-2">{paragraph.replace(/\*\*/g, '')}</h4>
        }
        if (paragraph.trim().startsWith('- ')) {
           return <li key={idx} className="ml-4 list-disc text-gray-700 my-1">{formatLine(paragraph.replace('- ', ''))}</li>
        }

        if (paragraph.trim() === '') return <br key={idx} className="block content-[''] h-2" />;

        return <p key={idx} className="mb-4">{formatLine(paragraph)}</p>;
      })}
    </div>
  );
};

const formatLine = (line: string) => {
  // Regex to match **bold**
  const parts = line.split(/(\*\*.*?\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i} className="font-bold text-gray-900">{part.slice(2, -2)}</strong>;
    }
    return part;
  });
};

