import React from 'react';

// A simple text formatter for the single-file constraint
// It converts **text** to bold and handles newlines
const FormattedText: React.FC<{ text: string }> = ({ text }) => {
  if (!text) return null;

  const paragraphs = text.split('\n');

  return (
    <div className="font-burmese text-gray-800 leading-loose tracking-wide text-lg">
      {paragraphs.map((paragraph, idx) => {
        // Simple header detection
        if (paragraph.startsWith('### ')) {
          return <h3 key={idx} className="text-xl font-bold text-thai-600 mt-6 mb-2">{paragraph.replace('### ', '')}</h3>
        }
        if (paragraph.startsWith('## ')) {
          return <h2 key={idx} className="text-2xl font-bold text-gray-900 mt-8 mb-3 border-b pb-2">{paragraph.replace('## ', '')}</h2>
        }
        if (paragraph.startsWith('**') && paragraph.endsWith('**')) {
           return <h4 key={idx} className="font-bold text-gray-900 mt-4 mb-2 text-lg">{paragraph.replace(/\*\*/g, '')}</h4>
        }
        if (paragraph.trim().startsWith('- ')) {
           return <li key={idx} className="ml-4 list-disc text-gray-700 my-1 pl-2">{formatLine(paragraph.replace('- ', ''))}</li>
        }

        if (paragraph.trim() === '') return <br key={idx} className="block content-[''] h-3" />;

        return <p key={idx} className="mb-4 text-gray-800">{formatLine(paragraph)}</p>;
      })}
    </div>
  );
};

const formatLine = (line: string) => {
  // Regex to match **bold**
  const parts = line.split(/(\*\*.*?\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i} className="font-bold text-gray-900">{part.slice(2, -2)}</strong>;
    }
    return part;
  });
};

export default FormattedText;

