- **EMOJIS:** You MUST use a LOT of attractive and medical-themed emojis (🏥, 🩺, 👩‍⚕️, 💉, 💊, ✨, 💚, 🌸, ✈️, 🇹🇭, ✅, 💙, 🏨, 🔬, 🚑, 🧘‍♀️, 🥗) in every paragraph.
- Always end with a CTA to shwethai.com or Messenger.
`;

class GeminiService {
  private getAIInstance() {
    // Always use process.env.API_KEY directly and create a new instance 
    // right before making an API call to pick up the most up-to-date key.
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel();

    let prompt = "";
    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a marketing strategy for: "${request.topic}". Audience: ${request.audience || "General"}. Context: ${request.additionalContext || "None"}.`;
        break;
      case ToolType.EDUCATIONAL:
        prompt = `Write an EDUCATIONAL Facebook post about: "${request.topic}". Context: ${request.additionalContext || "None"}.`;
        break;
      case ToolType.SALES:
        prompt = `Write a SALES Facebook post for: "${request.topic}". Context: ${request.additionalContext || "None"}.`;
        break;
      case ToolType.AD_COPY:
        prompt = `Write Facebook Ad Copy for: "${request.topic}".`;
        break;
      default:
        prompt = request.topic;
    }

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Content Gen Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: `Enhance this content: ${originalContent}` }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    } catch (error) {
       throw error;
    }
  }

  async generateImage(
    prompt: string, 
    aspectRatio: any = '1:1',
    negativePrompt?: string,
    stylePreset?: string,
    mood?: string,
    context?: string,
    isHighQuality: boolean = false
  ): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

    let finalPrompt = `Professional marketing visual: ${prompt.trim()}`;
    if (stylePreset && stylePreset !== 'none') finalPrompt += `, in ${stylePreset} style`;
    if (mood) finalPrompt += `, ${mood} lighting`;
    if (context) finalPrompt += `. Note: ${context}`;
    if (negativePrompt) finalPrompt += `. Exclude these: ${negativePrompt}`;

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ parts: [{ text: finalPrompt }] }],
        config: {
          imageConfig: { 
            aspectRatio: aspectRatio,
            // imageSize is only for gemini-3-pro-image-preview
            ...(isHighQuality ? { imageSize: "1K" } : {})
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }
      throw new Error("No image data returned from model.");
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) {
        // GUIDELINE: If 404/not found error, suggest key re-selection
        throw new Error("API KEY ERROR: Please re-select your paid API key (GCP Project with billing enabled).");
      }
      throw error;
    }
  }

  async sendMessage(message: string): Promise<string> {
    const ai = this.getAIInstance();
    const chat = ai.chats.create({
      model: this.getModel(),
      config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
    });
    const response = await chat.sendMessage({ message });
    return response.text || "";
  }
}

