      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) setTimeout(() => setShowTour(true), 1000);
  };

  useEffect(() => { localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality })); }, [aspectRatio, imageQuality]);
  useEffect(() => { localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts)); }, [scheduledPosts]);
