const SYSTEM_INSTRUCTION_TEXT = `
You are the Chief Marketing Officer (CMO) and Lead Content Strategist for "Shwe Thai" (shwethai.com).

**Brand Profile:**
- **Core Service:** Connecting Myanmar patients with world-class hospitals in Thailand (Medical Tourism).
- **USP:** Safety, Transparency, Peace of Mind (စိတ်အေးချမ်းသာမှု), and Ease of Access.
- **Target Audience:** Myanmar citizens seeking better healthcare. They value trust above price.

**Service Categories (Essential Knowledge):**
1. **Medical Checkup Packages:** Professional screening and diagnostic bundles.
2. **Insurance (အာမခံ):** Facilitating medical insurance coverage for treatments in Thailand.
3. **Treatment (ကုသမှုဆိုင်ရာ):** Specialized surgeries, chronic disease management, IVF, etc.
4. **Pre & Post Medical Travel:** Logistics, visas, transport, and recovery arrangements before and after hospital visits.

**Operational Model:**
- Shwe Thai is a marketplace connected directly to hospitals.
- Patients purchase packages on shwethai.com; forms are auto-forwarded to hospitals.
- Shwe Thai handles the appointments.

**Tone:**
- Helpful, Polite (Burmese markers: 'ခင်ဗျာ'/'ရှင်'), and Professional.
- Empathetic regarding health concerns.

**Formatting Rules:**
- Use Markdown (Bold headers, bullet points).
- **CRITICAL:** Use Myanmar Unicode.
- **EMOJIS:** Use a LOT of attractive medical-themed emojis (🏥, 🩺, 👩‍⚕️, 💉, 💊, ✨, 💚, 🌸, ✈️, 🇹🇭, ✅, 💙, 🏨, 🔬, 🚑, 🧘‍♀️, 🥗).
- Always end with a CTA to shwethai.com or Messenger.
`;

class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel();

    let prompt = "";
    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a marketing strategy for: "${request.topic}". 
        Audience: ${request.audience || "General"}. 
        Context: ${request.additionalContext || "None"}.
        Ensure you mention relevant services like Checkups, Insurance, or Pre/Post travel logistics if applicable.`;
        break;
      case ToolType.EDUCATIONAL:
        prompt = `Write an EDUCATIONAL Facebook post about: "${request.topic}". 
        Context: ${request.additionalContext || "None"}.
        Focus on patient education and how Shwe Thai makes access easier.`;
        break;
      case ToolType.SALES:
        prompt = `Write a SALES Facebook post for: "${request.topic}". 
        Target: ${request.audience || "Myanmar Patients"}.
        Context: ${request.additionalContext || "None"}.
        Mention direct booking on shwethai.com and professional hospital integration.`;
        break;
      case ToolType.AD_COPY:
        prompt = `Write Facebook Ad Copy for: "${request.topic}". Focus on safety and reliability.`;
        break;
      default:
        prompt = request.topic;
    }

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Content Gen Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: `Enhance this content and add more medical emojis: ${originalContent}` }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    } catch (error) {
       throw error;
    }
  }

  async generateImage(
    prompt: string, 
    aspectRatio: any = '1:1',
    negativePrompt?: string,
    stylePreset?: string,
    mood?: string,
    context?: string,
    isHighQuality: boolean = false
  ): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

    let finalPrompt = `Professional marketing photography for Shwe Thai Medical Tourism. 
    Subject: ${prompt.trim()}.`;

    if (stylePreset && stylePreset !== 'none') finalPrompt += ` Style: ${stylePreset}.`;
    if (mood && mood !== 'none') finalPrompt += ` Lighting & Atmosphere: ${mood}.`;
    if (context) finalPrompt += ` Context: ${context}.`;
    if (negativePrompt) finalPrompt += ` Negative prompt (exclude): ${negativePrompt}.`;

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ parts: [{ text: finalPrompt }] }],
        config: {
          imageConfig: { 
            aspectRatio: aspectRatio,
            ...(isHighQuality ? { imageSize: "1K" } : {})
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }
      throw new Error("No image data returned from model.");
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) {
        throw new Error("API KEY ERROR: Please re-select your paid API key (GCP Project with billing enabled).");
      }
      throw error;
    }
  }

  async sendMessage(message: string): Promise<string> {
    const ai = this.getAIInstance();
    const chat = ai.chats.create({
      model: this.getModel(),
      config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
    });
    const response = await chat.sendMessage({ message });
    return response.text || "";
  }
}

export const geminiService = new GeminiService();

