  { id: 'pencil-sketch', label: 'Pencil Sketch' },
  { id: 'surrealism', label: 'Surrealism' },
  { id: 'claymation', label: 'Claymation' },
  { id: 'architectural', label: 'Architectural' },
  { id: 'corporate', label: 'Corporate / Business' },
];

const MOOD_PRESETS = [
  { id: 'none', label: 'Auto (Default)' },
  { id: 'clinical-bright', label: 'Clinical & Bright' },
  { id: 'warm-reassuring', label: 'Warm & Reassuring' },
  { id: 'natural-sunlight', label: 'Natural Sunlight' },
  { id: 'modern-tech', label: 'Modern & Tech (Blueish)' },
  { id: 'professional-studio', label: 'Professional Studio' },
  { id: 'golden-hour', label: 'Golden Hour (Sunset)' },
  { id: 'soft-cinematic', label: 'Soft Cinematic' },
  { id: 'monochrome', label: 'High Contrast Monochrome' },
];

interface ToolState {
  topic: string;
  audience: string; // Reused for "Mood" in Image tool
  context: string;
  generatedContent: string | null;
  generatedImage: string | null;
  currentSavedItemId: string | null;
  negativePrompt: string;
  stylePreset: string;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  generatedContent: null,
  generatedImage: null,
  currentSavedItemId: null,
  negativePrompt: '',
  stylePreset: 'none'
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [scheduleSuccess, setScheduleSuccess] = useState(false);
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]); 
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);
  const [previewImage, setPreviewImage] = useState<StoredImage | null>(null);
  const [previewFilter, setPreviewFilter] = useState<string>('');
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false);
  const [schedulingItem, setSchedulingItem] = useState<SavedContentItem | null>(null);
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');
  const [showTour, setShowTour] = useState(false);
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const getCurrentToolState = () => toolStates[activeTool] || INITIAL_TOOL_STATE;

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId, negativePrompt, stylePreset } = getCurrentToolState();

  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) setStoredImages(JSON.parse(savedImages));
      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));
      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));
      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }
      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  const handleStartApp = (initialTool?: ToolType) => {
      if (initialTool) setActiveTool(initialTool);
      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) setTimeout(() => setShowTour(true), 1000);
  };

  useEffect(() => { localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality })); }, [aspectRatio, imageQuality]);
  useEffect(() => { localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts)); }, [scheduledPosts]);
  useEffect(() => { localStorage.setItem(SAVED_CONTENT_KEY, JSON.stringify(savedContent)); }, [savedContent]);
  useEffect(() => { localStorage.setItem(HISTORY_KEY, JSON.stringify(recentHistory)); }, [recentHistory]);
  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatMessages]);

  const addToRecentHistory = (item: SavedContentItem) => {
    setRecentHistory(prev => {
      const toolHistory = prev[activeTool] || [];
      const newHistory = [item, ...toolHistory].slice(0, 5);
      return { ...prev, [activeTool]: newHistory };
    });
  };

  const deleteFromHistory = (tool: ToolType, id: string) => {
      if (window.confirm("Are you sure? (ဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({ ...prev, [tool]: (prev[tool] || []).filter(item => item.id !== id) }));
      }
  };

  const clearToolHistory = (tool: ToolType) => {
      if (window.confirm("Clear all history? (မှတ်တမ်းအားလုံးဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({ ...prev, [tool]: [] }));
      }
  };

  const loadFromHistory = (item: SavedContentItem) => {
      updateCurrentToolState({
          topic: item.prompt,
          generatedContent: item.content || null,
          generatedImage: item.image || null,
          currentSavedItemId: null
      });
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleToggleSave = () => {
    if (!generatedContent && !generatedImage) return;
    if (currentSavedItemId) {
      setSavedContent(prev => prev.filter(item => item.id !== currentSavedItemId));
      updateCurrentToolState({ currentSavedItemId: null });
      return;
    }
    const newId = Date.now().toString();
    const newItem: SavedContentItem = {
      id: newId,
      type: activeTool,
      content: generatedContent || undefined,
      image: generatedImage || undefined,
      prompt: topic || 'Untitled Generation',
      timestamp: Date.now(),
      status: 'Unscheduled'
    };
    setSavedContent(prev => [newItem, ...prev]);
    updateCurrentToolState({ currentSavedItemId: newId });
  };

  const handleDeleteSavedItems = (ids: string[]) => {
    setSavedContent(prev => prev.filter(item => !ids.includes(item.id)));
    if (currentSavedItemId && ids.includes(currentSavedItemId)) updateCurrentToolState({ currentSavedItemId: null });
  };

  const handleUpdateSavedItem = (id: string, newContent: string) => {
    setSavedContent(prev => prev.map(item => item.id === id ? { ...item, content: newContent } : item));
  };

  const handleDeletePost = (id: string) => {
    setScheduledPosts(prev => prev.filter(p => p.id !== id));
  };

  const handleOpenPreview = (img: StoredImage, initialFilter: string = '') => {
    setPreviewImage(img);
    setPreviewFilter(initialFilter);
  };

  const handleEnhanceContent = async () => {
    if (!generatedContent || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      updateCurrentToolState({ generatedContent: enhanced });
    } catch (e) {
      console.error("Failed to enhance", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  const checkScheduleConflict = (date: string): boolean => scheduledPosts.some(post => post.date === date);

  const openScheduleModal = (item?: SavedContentItem) => {
    setSchedulingItem(item || null);
    setScheduleSuccess(false);
    setIsScheduling(true);
  };

  const handleSchedulePost = () => {
    if (!scheduleDate) return;
    const contentToSchedule = schedulingItem ? schedulingItem.content : generatedContent;
    const titleToSchedule = schedulingItem ? schedulingItem.prompt : topic;
    const typeToSchedule = schedulingItem ? schedulingItem.type : activeTool;
    if (!contentToSchedule && !schedulingItem?.image && !generatedImage) return;
    if (checkScheduleConflict(scheduleDate)) {
        if (!window.confirm("Already a post on this date. Continue? (ထပ်တင်မှာ သေချာပါသလား?)")) return;
    }
    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date: scheduleDate,
      title: titleToSchedule || 'Generated Content',
      content: contentToSchedule || '[Image Post]',
      platform: schedulePlatform,
      status: 'Scheduled',
      type: typeToSchedule
    };
    setScheduledPosts(prev => [...prev, newPost]);
    if (schedulingItem) {
        setSavedContent(prev => prev.map(item => item.id === schedulingItem.id ? { ...item, status: 'Scheduled', scheduledDate: scheduleDate } : item));
    } else {
        setScheduleSuccess(true);
        setTimeout(() => setScheduleSuccess(false), 3000);
    }
    setIsScheduling(false);
    setScheduleDate('');
    setSchedulingItem(null);
  };

  const handleGenerate = async () => {
    const trimmedTopic = topic.trim();
    if (!trimmedTopic) return;

    if (activeTool === ToolType.IMAGE_GENERATION && imageQuality === 'High') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
      }
    }

    setIsGenerating(true);
    setLoadingProgress(0);
    updateCurrentToolState({ generatedContent: null, generatedImage: null, currentSavedItemId: null });

    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => prev >= 90 ? prev : prev + Math.floor(Math.random() * 5) + 1);
    }, 800);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;
      if (activeTool === ToolType.IMAGE_GENERATION) {
        imageResult = await geminiService.generateImage(
          trimmedTopic, 
          aspectRatio, 
          negativePrompt.trim(), 
          stylePreset, 
          audience, // Standardized Mood Preset ID
          context.trim(), 
          imageQuality === 'High'
        );
      } else {
        const request: GenerationRequest = { tool: activeTool, topic: trimmedTopic, audience: audience.trim(), additionalContext: context.trim() };
        contentResult = await geminiService.generateContent(request);
      }
      updateCurrentToolState({ generatedContent: contentResult, generatedImage: imageResult });
      addToRecentHistory({ id: Date.now().toString(), type: activeTool, content: contentResult || undefined, image: imageResult || undefined, prompt: trimmedTopic, timestamp: Date.now(), status: 'Unscheduled' });
    } catch (error: any) {
      updateCurrentToolState({ generatedContent: error instanceof Error ? error.message : "An error occurred." });
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY: return { title: "Strategic Planner", desc: "Create marketing strategies.", placeholder: "e.g., Launching heart package", topicLabel: "Campaign Topic" };
      case ToolType.EDUCATIONAL: return { title: "Educational Content", desc: "Informative posts.", placeholder: "e.g., Cancer screening info", topicLabel: "Medical Topic" };
      case ToolType.SALES: return { title: "Sales Copy", desc: "Convert bookings.", placeholder: "e.g., 30% off screening", topicLabel: "Promotion" };
      case ToolType.AD_COPY: return { title: "Ad Creative", desc: "FB ad copy.", placeholder: "e.g., Orthopedic services", topicLabel: "Ad Subject" };
      case ToolType.IMAGE_GENERATION: return { title: "AI Visual Studio", desc: "Visual assets.", placeholder: "e.g., Modern hospital lobby", topicLabel: "Image Description" };
      default: return { title: "", desc: "", placeholder: "", topicLabel: "Topic" };
    }
  };

  const headerInfo = renderToolHeader();

  const renderLoadingState = () => (
    <div className="flex flex-col items-center justify-center h-full animate-fadeIn transition-opacity duration-300">
      <div className="relative w-24 h-24 mb-6">
        <div className="absolute inset-0 border-4 border-gray-100 rounded-full"></div>
        <div className="absolute inset-0 border-4 border-thai-500 rounded-full border-t-transparent animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center font-bold text-thai-600 text-lg">{loadingProgress}%</div>
      </div>
      <h3 className="text-xl font-bold text-gray-800 mb-2">{activeTool === ToolType.IMAGE_GENERATION ? 'Creating Visuals...' : 'Generating Strategy...'}</h3>
      <p className="text-gray-500 text-sm max-w-xs text-center">Our AI is analyzing requirements and crafting professional content for Shwe Thai.</p>
    </div>
  );

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200/60 h-fit sticky top-6 overflow-hidden flex flex-col max-h-[calc(100vh-6rem)]">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100 flex-shrink-0">
          <h2 className="text-lg font-bold text-gray-900 leading-tight">{headerInfo.title}</h2>
          <p className="text-gray-500 text-[10px] font-medium mt-1 uppercase tracking-wider">{headerInfo.desc}</p>
        </div>
        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">
          <div>
            <label className="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-2">{headerInfo.topicLabel} <span className="text-thai-red">*</span></label>
            <textarea
              value={topic}
              onChange={(e) => updateCurrentToolState({ topic: e.target.value })}
              placeholder={headerInfo.placeholder}
              rows={activeTool === ToolType.IMAGE_GENERATION ? 3 : 2}
              className="w-full px-4 py-3 bg-white text-gray-900 placeholder-gray-400 border-2 border-gray-100 rounded-xl focus:ring-4 focus:ring-thai-500/10 focus:border-thai-500 outline-none transition-all shadow-sm resize-none text-base font-medium"
            />
          </div>
          <div className="border border-gray-100 rounded-xl overflow-hidden">
             <button onClick={() => setShowSettings(!showSettings)} className="w-full px-4 py-3 bg-gray-50 flex items-center justify-between text-xs font-bold text-gray-500 hover:text-gray-700 hover:bg-gray-100 transition-colors uppercase tracking-wider">
               <span>Advanced Settings</span>
               <svg className={`w-4 h-4 transition-transform ${showSettings ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
             </button>
             {showSettings && (
               <div className="p-4 bg-white space-y-4 animate-slideDown">
                 {activeTool === ToolType.IMAGE_GENERATION && (
                    <div className="grid grid-cols-2 gap-3">
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Aspect Ratio</label>
                        <select value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)} className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none">
                            <option value={ImageAspectRatio.SQUARE}>Square (1:1)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_4_3}>Landscape (4:3)</option>
                            <option value={ImageAspectRatio.LANDSCAPE_16_9}>Landscape (16:9)</option>
                            <option value={ImageAspectRatio.PORTRAIT_3_4}>Portrait (3:4)</option>
                            <option value={ImageAspectRatio.PORTRAIT_9_16}>Portrait (9:16)</option>
                          </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Quality</label>
                        <select value={imageQuality} onChange={(e) => setImageQuality(e.target.value)} className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none">
                          <option value="Standard">Standard</option>
                          <option value="High">High Detail</option>
                        </select>
                        {imageQuality === 'High' && (
                           <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="block mt-1 text-[9px] text-thai-600 hover:underline">Requires Paid Billing Key</a>
                        )}
                      </div>
                    </div>
                  )}
                  {activeTool === ToolType.IMAGE_GENERATION && (
                     <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Artistic Style</label>
                          <select value={stylePreset} onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none">
                              {STYLE_PRESETS.map(style => <option key={style.id} value={style.id}>{style.label}</option>)}
                          </select>
                        </div>
                         <div>
                            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Mood / Lighting</label>
                            <select value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none">
                              {MOOD_PRESETS.map(mood => <option key={mood.id} value={mood.id}>{mood.label}</option>)}
                            </select>
                        </div>
                     </div>
                  )}
                  {activeTool !== ToolType.IMAGE_GENERATION && (
                    <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Target Audience</label>
                        <input type="text" value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} placeholder="e.g., Over 40s" className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none" />
                    </div>
                  )}
                  {activeTool === ToolType.IMAGE_GENERATION && (
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Exclude Elements</label>
                        <input type="text" value={negativePrompt} onChange={(e) => updateCurrentToolState({ negativePrompt: e.target.value })} placeholder="e.g., text, blur" className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none" />
                      </div>
                  )}
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1.5">Context / Details</label>
                    <textarea value={context} onChange={(e) => updateCurrentToolState({ context: e.target.value })} rows={3} placeholder="Additional info" className="w-full px-3 py-2 bg-gray-50 text-gray-800 text-xs border border-gray-200 rounded-lg focus:border-thai-500 outline-none resize-none" />
                  </div>
               </div>
             )}
          </div>
          <button onClick={handleGenerate} disabled={!topic.trim() || isGenerating} className={`w-full py-3.5 px-4 rounded-xl text-white font-bold shadow-lg shadow-thai-200/50 flex items-center justify-center space-x-2 transition-all transform hover:-translate-y-0.5 active:scale-95 relative overflow-hidden flex-shrink-0 mt-auto ${!topic.trim() || isGenerating ? 'bg-gray-300 cursor-not-allowed shadow-none' : 'bg-gradient-to-r from-thai-600 to-thai-500 hover:from-thai-700 hover:to-thai-600'}`}>
             {isGenerating && <div className="absolute bottom-0 left-0 h-1 bg-white/30 transition-all duration-300 ease-linear" style={{ width: `${loadingProgress}%` }} />}
             <span className="text-sm">{isGenerating ? 'Generating...' : 'Generate'}</span>
             {!isGenerating && <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>}
          </button>
        </div>
      </div>

      <div className="lg:col-span-8 space-y-4 flex flex-col h-full max-h-[calc(100vh-6rem)]">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200/60 flex-1 flex flex-col overflow-hidden min-h-[500px]">
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-white flex-shrink-0 z-10 relative">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider flex items-center gap-2">
               <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
               Preview
            </h3>
            <div className="flex space-x-2">
              {(generatedContent || generatedImage) && (
                <>
                  {generatedContent && (
                    <button onClick={() => handleCopy(generatedContent || '', 'main-output')} className={`p-2 rounded-lg border transition-all hover:shadow-md active:scale-95 ${copiedId === 'main-output' ? 'bg-green-50 text-green-700 border-green-200' : 'bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200'}`} title="Copy Content">
                      {copiedId === 'main-output' ? <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg> : <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>}
                    </button>
                  )}
                  {generatedContent && (
                    <button onClick={handleEnhanceContent} disabled={isEnhancing} className="px-3 py-1.5 rounded-lg text-xs font-bold text-shwe-600 bg-shwe-50 border border-shwe-200 hover:bg-shwe-100 transition-all flex items-center space-x-1" title="Enhance with AI">
                        {isEnhancing ? <svg className="animate-spin w-3.5 h-3.5" viewBox="0 0 24 24" fill="none"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg> : <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>}
                        <span>Enhance</span>
                    </button>
                  )}
                  <button onClick={() => openScheduleModal()} className={`p-2 rounded-lg border transition-all hover:shadow-md ${scheduleSuccess ? 'bg-green-50 text-green-600 border-green-200' : 'bg-white text-gray-500 border-gray-200 hover:text-thai-600 hover:border-thai-200'}`} title="Schedule Post">
                    {scheduleSuccess ? <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg> : <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" /></svg>}
                  </button>
                  <button onClick={handleToggleSave} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all shadow-sm flex items-center space-x-2 border ${currentSavedItemId ? 'bg-green-600 text-white border-green-600' : 'bg-thai-600 text-white border-thai-600'}`}>
                    <span>{currentSavedItemId ? 'Saved' : 'Save'}</span>
                  </button>
                </>
              )}
              {generatedImage && (
                <a href={generatedImage} download="shwethai-image.png" className="p-2 rounded-lg border bg-white text-gray-500 border-gray-200 hover:text-thai-600 transition-all hover:shadow-md" title="Download Image">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                </a>
              )}
            </div>
          </div>

          <div className="flex-1 bg-white relative overflow-hidden flex flex-col">
            {isGenerating ? (
              <div className="flex-1 p-8">{renderLoadingState()}</div>
            ) : generatedImage ? (
              <div className="flex-1 flex items-center justify-center p-4 bg-gray-50/50">
                <div 
                  className="w-full h-full cursor-zoom-in group relative flex items-center justify-center"
                  onClick={() => handleOpenPreview({ id: 'gen', data: generatedImage, prompt: topic, timestamp: Date.now() })}
                >
                  <img src={generatedImage} alt="Generated Marketing Visual" className="max-w-full max-h-full rounded-lg shadow-2xl object-contain transition-transform group-hover:scale-[1.01]" />
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/5 rounded-xl pointer-events-none">
                    <span className="bg-black/70 text-white text-xs px-4 py-2 rounded-full backdrop-blur-sm">View Full Image</span>
                  </div>
                </div>
              </div>
            ) : generatedContent ? (
              <div className="flex-1 p-8 overflow-y-auto custom-scrollbar prose prose-slate max-w-none">
                <FormattedText text={generatedContent} />
              </div>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-gray-300 space-y-4">
                <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center">
                  <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                </div>
                <p className="text-center max-w-xs text-sm font-medium">Ready to create. Enter your details to start.</p>
              </div>
            )}
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-200/60 p-4 h-48 flex flex-col">
            <div className="flex justify-between items-center mb-3">
                <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider flex items-center gap-1">
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  Recent History
                </h4>
                {(recentHistory[activeTool] || []).length > 0 && (
                    <button onClick={() => clearToolHistory(activeTool)} className="text-[10px] font-bold text-red-400 hover:text-red-600 px-2 py-1 rounded transition-colors uppercase">Clear All</button>
                )}
            </div>
            <div className="flex-1 overflow-x-auto overflow-y-hidden whitespace-nowrap custom-scrollbar flex space-x-3 items-center">
                {(recentHistory[activeTool] || []).length === 0 ? (
                    <div className="w-full text-center py-4"><p className="text-gray-300 text-xs italic">No recent history</p></div>
                ) : (
                    (recentHistory[activeTool] || []).map((item) => (
                        <div key={item.id} className="inline-block w-60 h-full bg-white rounded-lg border border-gray-200 p-2 relative group flex flex-col hover:border-thai-200 hover:shadow-md transition-all">
                            <div className="flex justify-between items-start mb-1.5">
                                <p className="text-[10px] font-bold text-gray-800 truncate w-36" title={item.prompt}>{item.prompt}</p>
                                <span className="text-[9px] text-gray-400">{new Date(item.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                            </div>
                            <div className="flex-1 overflow-hidden relative border border-gray-100 rounded-md bg-gray-50/50">
                                {item.image ? <img src={item.image} alt="Thumbnail" className="w-full h-full object-cover rounded" /> : <p className="text-[10px] text-gray-500 whitespace-pre-wrap line-clamp-3 p-2 leading-relaxed">{item.content}</p>}
                                <div className="absolute inset-0 bg-white/95 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-2">
                                     <button onClick={() => loadFromHistory(item)} className="p-1.5 bg-thai-600 text-white rounded hover:bg-thai-700 shadow-sm" title="Restore"><svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg></button>
                                     <button onClick={(e) => { e.stopPropagation(); deleteFromHistory(activeTool, item.id); }} className="p-1.5 bg-red-50 text-red-500 rounded hover:bg-red-100 shadow-sm" title="Delete"><svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
      </div>
    </div>
  );

  return showLanding ? <LandingPage onStart={handleStartApp} /> : (
    <Layout activeTool={activeTool} onToolChange={setActiveTool} onBackHome={() => setShowLanding(true)}>
      {activeTool === ToolType.CALENDAR ? <ContentCalendar posts={scheduledPosts} onDeletePost={handleDeletePost} /> : activeTool === ToolType.SAVED_CONTENT ? <SavedContentRepo items={savedContent} onDelete={handleDeleteSavedItems} onSchedule={openScheduleModal} onViewImage={handleOpenPreview} onUpdate={handleUpdateSavedItem} /> : renderGenerator()}
      {previewImage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fadeIn" onClick={() => setPreviewImage(null)}>
          <button className="absolute top-6 right-6 text-white/50 hover:text-white transition-colors p-2" onClick={() => setPreviewImage(null)}><svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <div className="relative w-full max-w-5xl h-full flex flex-col items-center justify-center" onClick={e => e.stopPropagation()}>
             <img src={previewImage.data} alt={previewImage.prompt} className={`max-w-full max-h-[80vh] rounded-lg shadow-2xl object-contain transition-all duration-300 ${previewFilter}`} />
             <div className="mt-6 flex space-x-3 overflow-x-auto max-w-full p-2 bg-black/20 backdrop-blur-sm rounded-full">
                {IMAGE_FILTERS.map(filter => <button key={filter.id} onClick={() => setPreviewFilter(filter.class)} className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all whitespace-nowrap ${previewFilter === filter.class ? 'bg-white text-black shadow-lg scale-105' : 'bg-white/10 text-white hover:bg-white/20'}`}>{filter.label}</button>)}
             </div>
          </div>
        </div>
      )}
      {isScheduling && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setIsScheduling(false)}>
           <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-gray-100 flex justify-between items-center"><h3 className="text-lg font-bold text-gray-900">Schedule Content</h3><button onClick={() => setIsScheduling(false)} className="text-gray-400 hover:text-gray-600"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
              <div className="p-6 space-y-5">
                 <div><label className="block text-xs font-bold text-gray-500 uppercase mb-2">Publish Date</label><input type="date" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:border-thai-500 outline-none" min={new Date().toISOString().split('T')[0]} /></div>
                 <div><label className="block text-xs font-bold text-gray-500 uppercase mb-2">Platform</label><div className="grid grid-cols-2 gap-3">{['Facebook', 'Telegram', 'Viber', 'TikTok'].map(p => <button key={p} onClick={() => setSchedulePlatform(p as any)} className={`px-3 py-2 rounded-lg text-sm font-medium border transition-all ${schedulePlatform === p ? 'bg-thai-50 border-thai-200 text-thai-700 shadow-sm' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`}>{p}</button>)}</div></div>
              </div>
              <div className="p-4 bg-gray-50 border-t border-gray-100 flex justify-end space-x-3"><button onClick={() => setIsScheduling(false)} className="px-4 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg">Cancel</button><button onClick={handleSchedulePost} disabled={!scheduleDate} className={`px-6 py-2 text-sm font-bold text-white rounded-lg shadow-md transition-all ${!scheduleDate ? 'bg-gray-300 cursor-not-allowed' : 'bg-thai-600 hover:bg-thai-700'}`}>Confirm</button></div>
           </div>
        </div>
      )}
      <OnboardingTour isOpen={showTour} onClose={() => { setShowTour(false); localStorage.setItem(TOUR_KEY, 'true'); }} />
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, GenerationRequest, Message, StoredImage, ImageAspectRatio, ScheduledPost, SavedContentItem } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { SavedContentRepo } from './components/SavedContentRepo';
import { OnboardingTour } from './components/OnboardingTour';
import { ContentCalendar } from './components/ContentCalendar';
import { LandingPage } from './components/LandingPage';

const STORAGE_KEY = 'SHWETHAI_GALLERY';
const SAVED_CONTENT_KEY = 'SHWETHAI_SAVED_CONTENT';
const PREFS_KEY = 'SHWETHAI_IMAGE_PREFS';
const TOUR_KEY = 'SHWETHAI_TOUR_COMPLETED';
const CALENDAR_KEY = 'SHWETHAI_CALENDAR';
const HISTORY_KEY = 'SHWETHAI_RECENT_HISTORY';

const STYLE_PRESETS = [
  { id: 'none', label: 'None (Default)' },
  { id: 'photorealistic', label: 'Photorealistic' },
  { id: 'cinematic', label: 'Cinematic Movie' },
  { id: 'digital-art', label: 'Digital Illustration' },
  { id: 'anime', label: 'Anime / Manga' },
  { id: '3d-model', label: '3D Render' },
  { id: 'line-art', label: 'Line Art' },
  { id: 'watercolor', label: 'Watercolor' },
  { id: 'oil-painting', label: 'Oil Painting' },
  { id: 'cyberpunk', label: 'Cyberpunk' },
  { id: 'minimalist', label: 'Minimalist' },
  { id: 'medical-illustration', label: 'Medical Illustration' },
  { id: 'studio-professional', label: 'Studio Professional' },
  { id: 'advertising-poster', label: 'Advertising Poster' },
  { id: 'isometric', label: 'Isometric 3D' },
  { id: 'vintage-photo', label: 'Vintage Photography' },
  { id: 'pop-art', label: 'Pop Art' },
  { id: 'pencil-sketch', label: 'Pencil Sketch' },
  { id: 'surrealism', label: 'Surrealism' },
  { id: 'claymation', label: 'Claymation' },
  { id: 'architectural', label: 'Architectural' },
  { id: 'corporate', label: 'Corporate / Business' },
];

const MOOD_PRESETS = [
  { id: 'none', label: 'Auto (Default)' },
  { id: 'clinical-bright', label: 'Clinical & Bright' },
  { id: 'warm-reassuring', label: 'Warm & Reassuring' },
  { id: 'natural-sunlight', label: 'Natural Sunlight' },
  { id: 'modern-tech', label: 'Modern & Tech (Blueish)' },
  { id: 'professional-studio', label: 'Professional Studio' },
  { id: 'golden-hour', label: 'Golden Hour (Sunset)' },
  { id: 'soft-cinematic', label: 'Soft Cinematic' },
  { id: 'monochrome', label: 'High Contrast Monochrome' },
];

// Added missing IMAGE_FILTERS constant for the preview modal
const IMAGE_FILTERS = [
  { id: 'none', label: 'Original', class: '' },
  { id: 'grayscale', label: 'B&W', class: 'grayscale' },
  { id: 'sepia', label: 'Sepia', class: 'sepia' },
  { id: 'warm', label: 'Warm', class: 'sepia-[.5] contrast-100' },
  { id: 'cool', label: 'Cool', class: 'hue-rotate-180 saturate-50' },
  { id: 'vintage', label: 'Vintage', class: 'sepia-[.3] contrast-125 brightness-90' },
  { id: 'blur', label: 'Blur', class: 'blur-[2px]' },
];

interface ToolState {
  topic: string;
  audience: string; // Reused for "Mood" in Image tool
  context: string;
  generatedContent: string | null;
  generatedImage: string | null;
  currentSavedItemId: string | null;
  negativePrompt: string;
  stylePreset: string;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  generatedContent: null,
  generatedImage: null,
  currentSavedItemId: null,
  negativePrompt: '',
  stylePreset: 'none'
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [scheduleSuccess, setScheduleSuccess] = useState(false);
  const [storedImages, setStoredImages] = useState<StoredImage[]>([]); 
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);
  const [previewImage, setPreviewImage] = useState<StoredImage | null>(null);
  const [previewFilter, setPreviewFilter] = useState<string>('');
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false);
  const [schedulingItem, setSchedulingItem] = useState<SavedContentItem | null>(null);
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');
  const [showTour, setShowTour] = useState(false);
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const getCurrentToolState = () => toolStates[activeTool] || INITIAL_TOOL_STATE;

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId, negativePrompt, stylePreset } = getCurrentToolState();

  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
      if (savedImages) setStoredImages(JSON.parse(savedImages));
      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));
      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));
      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedPrefs) {
        const prefs = JSON.parse(savedPrefs);
        if (prefs.aspectRatio) setAspectRatio(prefs.aspectRatio);
        if (prefs.imageQuality) setImageQuality(prefs.imageQuality);
      }
      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));
    } catch (e) {
      console.error("Failed to load data from storage", e);
    }
  }, []);

  const handleStartApp = (initialTool?: ToolType) => {
      if (initialTool) setActiveTool(initialTool);
      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) setTimeout(() => setShowTour(true), 1000);
  };

  useEffect(() => { localStorage.setItem(PREFS_KEY, JSON.stringify({ aspectRatio, imageQuality })); }, [aspectRatio, imageQuality]);
  useEffect(() => { localStorage.setItem(CALENDAR_KEY, JSON.stringify(scheduledPosts)); }, [scheduledPosts]);
  useEffect(() => { localStorage.setItem(SAVED_CONTENT_KEY, JSON.stringify(savedContent)); }, [savedContent]);
  useEffect(() => { localStorage.setItem(HISTORY_KEY, JSON.stringify(recentHistory)); }, [recentHistory]);
  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatMessages]);

  const addToRecentHistory = (item: SavedContentItem) => {
    setRecentHistory(prev => {
      const toolHistory = prev[activeTool] || [];
      const newHistory = [item, ...toolHistory].slice(0, 5);
      return { ...prev, [activeTool]: newHistory };
    });
  };

  const deleteFromHistory = (tool: ToolType, id: string) => {
      if (window.confirm("Are you sure? (ဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({ ...prev, [tool]: (prev[tool] || []).filter(item => item.id !== id) }));
      }
  };

  const clearToolHistory = (tool: ToolType) => {
      if (window.confirm("Clear all history? (မှတ်တမ်းအားလုံးဖျက်မှာသေချာပါသလား)")) {
        setRecentHistory(prev => ({ ...prev, [tool]: [] }));
      }
  };

  const loadFromHistory = (item: SavedContentItem) => {
      updateCurrentToolState({
          topic: item.prompt,
          generatedContent: item.content || null,
          generatedImage: item.image || null,
          currentSavedItemId: null
      });
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleToggleSave = () => {
    if (!generatedContent && !generatedImage) return;
    if (currentSavedItemId) {
      setSavedContent(prev => prev.filter(item => item.id !== currentSavedItemId));
      updateCurrentToolState({ currentSavedItemId: null });
      return;
    }
    const newId = Date.now().toString();
    const newItem: SavedContentItem = {
      id: newId,
      type: activeTool,
      content: generatedContent || undefined,
      image: generatedImage || undefined,
      prompt: topic || 'Untitled Generation',
      timestamp: Date.now(),
      status: 'Unscheduled'
    };
    setSavedContent(prev => [newItem, ...prev]);
    updateCurrentToolState({ currentSavedItemId: newId });
  };

  const handleDeleteSavedItems = (ids: string[]) => {
    setSavedContent(prev => prev.filter(item => !ids.includes(item.id)));
    if (currentSavedItemId && ids.includes(currentSavedItemId)) updateCurrentToolState({ currentSavedItemId: null });
  };

  const handleUpdateSavedItem = (id: string, newContent: string) => {
    setSavedContent(prev => prev.map(item => item.id === id ? { ...item, content: newContent } : item));
  };

  const handleDeletePost = (id: string) => {
    setScheduledPosts(prev => prev.filter(p => p.id !== id));
  };

  const handleOpenPreview = (img: StoredImage, initialFilter: string = '') => {
    setPreviewImage(img);
    setPreviewFilter(initialFilter);
  };

  const handleEnhanceContent = async () => {
    if (!generatedContent || isEnhancing) return;
    setIsEnhancing(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      updateCurrentToolState({ generatedContent: enhanced });
    } catch (e) {
      console.error("Failed to enhance", e);
    } finally {
      setIsEnhancing(false);
    }
  };

  const checkScheduleConflict = (date: string): boolean => scheduledPosts.some(post => post.date === date);

  const openScheduleModal = (item?: SavedContentItem) => {
    setSchedulingItem(item || null);
    setScheduleSuccess(false);
    setIsScheduling(true);
  };

  const handleSchedulePost = () => {
    if (!scheduleDate) return;
    const contentToSchedule = schedulingItem ? schedulingItem.content : generatedContent;
    const titleToSchedule = schedulingItem ? schedulingItem.prompt : topic;
    const typeToSchedule = schedulingItem ? schedulingItem.type : activeTool;
    if (!contentToSchedule && !schedulingItem?.image && !generatedImage) return;
    if (checkScheduleConflict(scheduleDate)) {
        if (!window.confirm("Already a post on this date. Continue? (ထပ်တင်မှာ သေချာပါသလား?)")) return;
    }
    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date: scheduleDate,
      title: titleToSchedule || 'Generated Content',
      content: contentToSchedule || '[Image Post]',
      platform: schedulePlatform,
      status: 'Scheduled',
      type: typeToSchedule
    };
    setScheduledPosts(prev => [...prev, newPost]);
    if (schedulingItem) {
        setSavedContent(prev => prev.map(item => item.id === schedulingItem.id ? { ...item, status: 'Scheduled', scheduledDate: scheduleDate } : item));
    } else {
        setScheduleSuccess(true);
        setTimeout(() => setScheduleSuccess(false), 3000);
    }
    setIsScheduling(false);
    setScheduleDate('');
    setSchedulingItem(null);
  };

  const handleGenerate = async () => {
    const trimmedTopic = topic.trim();
    if (!trimmedTopic) return;

    if (activeTool === ToolType.IMAGE_GENERATION && imageQuality === 'High') {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await window.aistudio.openSelectKey();
      }
    }

    setIsGenerating(true);
    setLoadingProgress(0);
    updateCurrentToolState({ generatedContent: null, generatedImage: null, currentSavedItemId: null });

    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => prev >= 90 ? prev : prev + Math.floor(Math.random() * 5) + 1);
    }, 800);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;
      if (activeTool === ToolType.IMAGE_GENERATION) {
        imageResult = await geminiService.generateImage(
          trimmedTopic, 
          aspectRatio, 
          negativePrompt.trim(), 
          stylePreset, 
          audience, // Standardized Mood Preset ID
          context.trim(), 
          imageQuality === 'High'
        );
      } else {
        const request: GenerationRequest = { tool: activeTool, topic: trimmedTopic, audience: audience.trim(), additionalContext: context.trim() };
        contentResult = await geminiService.generateContent(request);
      }
      updateCurrentToolState({ generatedContent: contentResult, generatedImage: imageResult });
      addToRecentHistory({ id: Date.now().toString(), type: activeTool, content: contentResult || undefined, image: imageResult || undefined, prompt: trimmedTopic, timestamp: Date.now(), status: 'Unscheduled' });
    } catch (error: any) {
      updateCurrentToolState({ generatedContent: error instanceof Error ? error.message : "An error occurred." });
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const renderToolHeader = () => {
    switch(activeTool) {
      case ToolType.STRATEGY: return { title: "Strategic Planner", desc: "Create marketing strategies.", placeholder: "e.g., Launching heart package", topicLabel: "Campaign Topic" };
      case ToolType.EDUCATIONAL: return { title: "Educational Content", desc: "Informative posts.", placeholder: "e.g., Cancer screening info", topicLabel: "Medical Topic" };
      case ToolType.SALES: return { title: "Sales Copy", desc: "Convert bookings.", placeholder: "e.g., 30% off screening", topicLabel: "Promotion" };
