                    {scheduleSuccess ? <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg> : <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" /></svg>}
                  </button>
                  <button onClick={handleToggleSave} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all shadow-sm flex items-center space-x-2 border ${currentSavedItemId ? 'bg-green-600 text-white border-green-600' : 'bg-thai-600 text-white border-thai-600'}`}>
                    <span>{currentSavedItemId ? 'Saved' : 'Save'}</span>
                  </button>
                </>
              )}
              {generatedImage && (
                <a href={generatedImage} download="shwethai-image.png" className="p-2 rounded-lg border bg-white text-gray-500 border-gray-200 hover:text-thai-600 transition-all hover:shadow-md" title="Download Image">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                </a>
              )}
            </div>
          </div>

          <div className="flex-1 bg-white relative overflow-hidden flex flex-col">
            {isGenerating ? (
              <div className="flex-1 p-8">{renderLoadingState()}</div>
            ) : generatedImage ? (
              <div className="flex-1 flex items-center justify-center p-4 bg-gray-50/50">
                <div 
                  className="w-full h-full cursor-zoom-in group relative flex items-center justify-center"
                  onClick={() => handleOpenPreview({ id: 'gen', data: generatedImage, prompt: topic, timestamp: Date.now() })}
                >
                  <img src={generatedImage} alt="Generated Marketing Visual" className="max-w-full max-h-full rounded-lg shadow-2xl object-contain transition-transform group-hover:scale-[1.01]" />
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/5 rounded-xl pointer-events-none">
                    <span className="bg-black/70 text-white text-xs px-4 py-2 rounded-full backdrop-blur-sm">View Full Image</span>
                  </div>
                </div>
              </div>
            ) : generatedContent ? (
              <div className="flex-1 p-8 overflow-y-auto custom-scrollbar prose prose-slate max-w-none">
