- **CRITICAL:** Use Myanmar Unicode for all public-facing content.
- **EMOJIS:** Use a LOT of attractive medical and travel themed emojis (🏥, 🩺, 👩‍⚕️, 💉, 💊, ✨, 💚, 🌸, ✈️, 🇹🇭, ✅, 💙, 🏨, 🔬, 🚑, 🧘‍♀️, 🥗, 📋, 🛡️).
- Always end with a CTA to shwethai.com or Messenger.
`;

class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel();

    let prompt = "";
    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a marketing strategy for: "${request.topic}". 
        Audience: ${request.audience || "General"}. 
        Context: ${request.additionalContext || "None"}.
        Ensure the strategy covers Shwe Thai's specific service pillars like Checkups, Insurance, and Pre/Post travel logistics.`;
        break;
      case ToolType.EDUCATIONAL:
        prompt = `Write an EDUCATIONAL Facebook post about: "${request.topic}". 
        Context: ${request.additionalContext || "None"}.
        Explain the medical logic clearly and how Shwe Thai simplifies access to this treatment/checkup in Thailand.`;
        break;
      case ToolType.SALES:
        prompt = `Write a SALES Facebook post for: "${request.topic}". 
        Target: ${request.audience || "Myanmar Patients"}.
        Context: ${request.additionalContext || "None"}.
        Highlight the benefit of booking via shwethai.com and our specialized Pre/Post medical travel assistance.`;
        break;
      case ToolType.AD_COPY:
        prompt = `Write Facebook Ad Copy for: "${request.topic}". Focus on "Peace of Mind" and safety. 
        Mention our Insurance coordination or Travel support if relevant.`;
        break;
      default:
        prompt = request.topic;
    }

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Content Gen Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: `Enhance this content. Ensure it highlights Shwe Thai's expertise in Checkups, Insurance, Treatments, or Travel Logistics. Add more relevant emojis: ${originalContent}` }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    } catch (error) {
       throw error;
    }
  }

  async generateImage(
    prompt: string, 
    aspectRatio: any = '1:1',
    negativePrompt?: string,
    stylePreset?: string,
    mood?: string,
    context?: string,
    isHighQuality: boolean = false
  ): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

    let finalPrompt = `Professional marketing photography for Shwe Thai Medical Tourism. 
    Subject: ${prompt.trim()}.`;

    if (stylePreset && stylePreset !== 'none') finalPrompt += ` Style: ${stylePreset}.`;
    if (mood && mood !== 'none') finalPrompt += ` Lighting & Atmosphere: ${mood}.`;
    if (context) finalPrompt += ` Additional Brand Context: ${context}.`;
    if (negativePrompt) finalPrompt += ` Exclude from image: ${negativePrompt}.`;

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ parts: [{ text: finalPrompt }] }],
        config: {
          imageConfig: { 
            aspectRatio: aspectRatio,
            ...(isHighQuality ? { imageSize: "1K" } : {})
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }
      throw new Error("No image data returned from model.");
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) {
        throw new Error("API KEY ERROR: Please re-select your paid API key (GCP Project with billing enabled).");
      }
      throw error;
    }
  }

  async sendMessage(message: string): Promise<string> {
    const ai = this.getAIInstance();
    const chat = ai.chats.create({
      model: this.getModel(),
      config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
    });
    const response = await chat.sendMessage({ message });
    return response.text || "";
  }
}

