      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId, negativePrompt, stylePreset } = getCurrentToolState();

  useEffect(() => {
    try {
      const savedImages = localStorage.getItem(STORAGE_KEY);
