  { id: 'grayscale', label: 'B&W', class: 'grayscale' },
  { id: 'sepia', label: 'Sepia', class: 'sepia' },
  { id: 'warm', label: 'Warm', class: 'sepia-[.5] contrast-100' },
  { id: 'cool', label: 'Cool', class: 'hue-rotate-180 saturate-50' },
];

interface ToolState {
  topic: string;
  audience: string;
  context: string;
  generatedContent: string | null;
  generatedImage: string | null;
  currentSavedItemId: string | null;
  negativePrompt: string;
  stylePreset: string;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  generatedContent: null,
  generatedImage: null,
  currentSavedItemId: null,
  negativePrompt: '',
  stylePreset: 'none'
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.EDUCATIONAL);
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [scheduleSuccess, setScheduleSuccess] = useState(false);
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);
  const [previewImage, setPreviewImage] = useState<StoredImage | null>(null);
  const [previewFilter, setPreviewFilter] = useState<string>('');
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [isScheduling, setIsScheduling] = useState(false);
  const [schedulingItem, setSchedulingItem] = useState<SavedContentItem | null>(null);
  const [scheduleDate, setScheduleDate] = useState('');
  const [schedulePlatform, setSchedulePlatform] = useState<'Facebook' | 'Telegram' | 'Viber' | 'TikTok' | 'Other'>('Facebook');
  const [showTour, setShowTour] = useState(false);
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const getCurrentToolState = () => toolStates[activeTool] || INITIAL_TOOL_STATE;

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, generatedContent, generatedImage, currentSavedItemId, negativePrompt, stylePreset } = getCurrentToolState();

  useEffect(() => {
    try {
      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));
      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));
      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));
      const savedChat = localStorage.getItem(CHAT_KEY);
      if (savedChat) setChatMessages(JSON.parse(savedChat));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => { localStorage.setItem(CHAT_KEY, JSON.stringify(chatMessages)); }, [chatMessages]);
  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatMessages]);

  const handleStartApp = (initialTool?: ToolType) => {
      if (initialTool) setActiveTool(initialTool);
      setShowLanding(false);
      const tourCompleted = localStorage.getItem(TOUR_KEY);
      if (!tourCompleted) setTimeout(() => setShowTour(true), 1000);
  };

  const addToRecentHistory = (item: SavedContentItem) => {
    setRecentHistory(prev => {
      const toolHistory = prev[activeTool] || [];
      const newHistory = [item, ...toolHistory].slice(0, 5);
      return { ...prev, [activeTool]: newHistory };
    });
  };

  const handleSendChatMessage = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: Message = { role: 'user', text: chatInput, timestamp: new Date() };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const response = await geminiService.sendMessage(userMsg.text, chatMessages);
      const modelMsg: Message = { role: 'model', text: response, timestamp: new Date() };
      setChatMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      const errorMsg: Message = { role: 'model', text: "Sorry, I encountered an error. Please check your connection.", timestamp: new Date() };
      setChatMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const clearChat = () => {
    if (window.confirm("Clear all conversation history?")) {
      setChatMessages([]);
      localStorage.removeItem(CHAT_KEY);
    }
  };

  const handleGenerate = async () => {
    const trimmedTopic = topic.trim();
    if (!trimmedTopic) return;
    setIsGenerating(true);
    setLoadingProgress(0);
    updateCurrentToolState({ generatedContent: null, generatedImage: null });

    const progressInterval = setInterval(() => {
      setLoadingProgress((prev) => prev >= 90 ? prev : prev + Math.floor(Math.random() * 5) + 1);
    }, 800);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;
      if (activeTool === ToolType.IMAGE_GENERATION) {
        imageResult = await geminiService.generateImage(trimmedTopic, aspectRatio, negativePrompt.trim(), stylePreset, audience, context.trim(), imageQuality === 'High');
      } else {
        const request: GenerationRequest = { tool: activeTool, topic: trimmedTopic, audience, additionalContext: context.trim() };
        contentResult = await geminiService.generateContent(request);
      }
      updateCurrentToolState({ generatedContent: contentResult, generatedImage: imageResult });
      addToRecentHistory({ id: Date.now().toString(), type: activeTool, content: contentResult || undefined, image: imageResult || undefined, prompt: trimmedTopic, timestamp: Date.now(), status: 'Unscheduled' });
    } catch (error: any) {
      updateCurrentToolState({ generatedContent: "Error generating content. Please try again." });
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const renderChatInterface = () => (
    <div className="flex flex-col h-[calc(100vh-8rem)] bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="px-6 py-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-thai-600 flex items-center justify-center text-white font-bold">CMO</div>
          <div>
            <h3 className="text-sm font-bold text-gray-900">Strategic Consultant</h3>
            <p className="text-[10px] text-green-600 font-bold uppercase tracking-wider">Expert Mode Active</p>
          </div>
        </div>
        <button onClick={clearChat} className="text-xs font-bold text-gray-400 hover:text-red-500 transition-colors uppercase">Clear Chat</button>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[#FDFDFD]">
        {chatMessages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-40">
            <svg className="w-16 h-16 text-thai-200" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            <p className="text-sm font-medium text-gray-400">မင်္ဂလာပါ။ ရွှေထိုင်း မားကတ်တင်းအတွက် ဘာများ အကြံပေးရမလဲခင်ဗျာ?</p>
          </div>
        )}
        {chatMessages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] px-5 py-4 rounded-2xl shadow-sm border ${
              msg.role === 'user' 
                ? 'bg-thai-600 text-white border-thai-700 rounded-tr-none' 
                : 'bg-white text-gray-800 border-gray-100 rounded-tl-none'
            }`}>
              <div className={msg.role === 'user' ? 'text-white' : 'prose prose-sm prose-slate'}>
                {msg.role === 'model' ? <FormattedText text={msg.text} /> : msg.text}
              </div>
              <div className={`text-[9px] mt-2 ${msg.role === 'user' ? 'text-thai-200' : 'text-gray-400'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
        {isChatLoading && (
          <div className="flex justify-start">
             <div className="bg-white border border-gray-100 px-5 py-3 rounded-2xl rounded-tl-none shadow-sm flex items-center space-x-2">
                <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
             </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-gray-100">
        <div className="relative max-w-4xl mx-auto">
          <textarea
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendChatMessage(); } }}
            placeholder="Ask anything about Shwe Thai marketing or medical logistics..."
            className="w-full px-5 py-4 pr-16 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-4 focus:ring-thai-500/10 focus:border-thai-500 outline-none transition-all resize-none text-sm font-medium"
            rows={1}
          />
          <button 
            onClick={handleSendChatMessage}
            disabled={!chatInput.trim() || isChatLoading}
            className={`absolute right-3 top-1/2 -translate-y-1/2 p-2.5 rounded-xl transition-all ${
              !chatInput.trim() || isChatLoading ? 'text-gray-300' : 'bg-thai-600 text-white shadow-md hover:bg-thai-700'
            }`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </div>
        <p className="text-center text-[9px] text-gray-400 mt-2 font-bold uppercase tracking-widest">Powered by Gemini Strategic Engine</p>
      </div>
    </div>
  );

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
      {/* Sidebar Tool Config */}
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200 h-fit sticky top-6 overflow-hidden flex flex-col">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100 flex-shrink-0">
          <h2 className="text-lg font-bold text-gray-900 leading-tight">Generator Tools</h2>
          <p className="text-gray-500 text-[10px] font-medium mt-1 uppercase tracking-wider">{activeTool}</p>
        </div>
        <div className="p-6 space-y-6 overflow-y-auto">
          <div>
            <label className="block text-xs font-bold text-gray-700 uppercase tracking-wider mb-2">Subject Topic <span className="text-thai-red">*</span></label>
            <textarea
              value={topic}
              onChange={(e) => updateCurrentToolState({ topic: e.target.value })}
              placeholder="e.g., Cancer Screening in Thailand"
              rows={3}
              className="w-full px-4 py-3 bg-white text-gray-900 border border-gray-200 rounded-xl focus:ring-4 focus:ring-thai-500/10 focus:border-thai-500 outline-none transition-all"
            />
          </div>
          <div className="border border-gray-100 rounded-xl overflow-hidden">
             <button onClick={() => setShowSettings(!showSettings)} className="w-full px-4 py-3 bg-gray-50 flex items-center justify-between text-xs font-bold text-gray-500 uppercase">
               <span>Advanced Settings</span>
               <svg className={`w-4 h-4 transition-transform ${showSettings ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
             </button>
             {showSettings && (
               <div className="p-4 bg-white space-y-4">
                  {activeTool === ToolType.IMAGE_GENERATION ? (
                     <div className="grid grid-cols-2 gap-3">
                        <div>
                          <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Style</label>
                          <select value={stylePreset} onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                              {STYLE_PRESETS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                          </select>
                        </div>
                        <div>
                          <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Mood</label>
                          <select value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                              {MOOD_PRESETS.map(m => <option key={m.id} value={m.id}>{m.label}</option>)}
                          </select>
                        </div>
                     </div>
                  ) : (
                    <div>
                      <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Audience</label>
                      <input type="text" value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} placeholder="e.g., Over 40s" className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg" />
                    </div>
                  )}
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Additional Context</label>
                    <textarea value={context} onChange={(e) => updateCurrentToolState({ context: e.target.value })} rows={3} placeholder="Add details..." className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg" />
                  </div>
               </div>
             )}
          </div>
          <button onClick={handleGenerate} disabled={!topic.trim() || isGenerating} className="w-full py-4 bg-thai-600 text-white rounded-xl font-bold shadow-lg hover:bg-thai-700 transition-all disabled:bg-gray-300">
             {isGenerating ? 'Generating...' : 'Generate Content'}
          </button>
        </div>
      </div>

      {/* Main Preview */}
      <div className="lg:col-span-8 bg-white rounded-2xl shadow-sm border border-gray-200 flex flex-col overflow-hidden min-h-[500px]">
        {isGenerating ? (
          <div className="flex-1 flex flex-col items-center justify-center p-12">
             <div className="w-24 h-24 border-4 border-thai-100 border-t-thai-600 rounded-full animate-spin mb-4"></div>
