            <div className="p-8 overflow-y-auto">
              {generatedImage ? <img src={generatedImage} alt="Generated" className="rounded-xl shadow-lg max-w-full" /> : <FormattedText text={generatedContent || ''} />}
            </div>
          </div>
        ) : (
          <div className="flex-1 flex items-center justify-center text-gray-300 italic">Enter details and click generate to start.</div>
        )}
      </div>
