  );

  return showLanding ? <LandingPage onStart={handleStartApp} /> : (
    <Layout activeTool={activeTool} onToolChange={setActiveTool} onBackHome={() => setShowLanding(true)}>
      {activeTool === ToolType.CONSULTATION ? renderChatInterface() : activeTool === ToolType.CALENDAR ? <ContentCalendar posts={scheduledPosts} onDeletePost={(id) => setScheduledPosts(p => p.filter(x => x.id !== id))} /> : activeTool === ToolType.SAVED_CONTENT ? <SavedContentRepo items={savedContent} onDelete={() => {}} onSchedule={() => {}} onViewImage={() => {}} onUpdate={() => {}} /> : renderGenerator()}
    </Layout>
  );
};

