class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel();

    let prompt = "";
    switch (request.tool) {
      case ToolType.STRATEGY:
        prompt = `Develop a comprehensive, high-level, and detailed multi-channel marketing strategy for: "${request.topic}". 
        Target Audience: ${request.audience || "General patients in Myanmar"}. 
        Context: ${request.additionalContext || "None"}.
        Include specific sections for Objective, Target Audience Analysis, Content Pillars, Channel Strategy (FB, Viber, etc.), and a 4-week Implementation Roadmap.`;
        break;
      case ToolType.EDUCATIONAL:
        prompt = `Write a deep-dive, comprehensive, and highly informative educational Facebook post about: "${request.topic}". 
        Context: ${request.additionalContext || "None"}.
        Explain the medical condition or service in detail. Focus on symptoms, the importance of early detection/treatment, and the specific advantages of Thai medical facilities. Make it long-form and authoritative.`;
        break;
      case ToolType.SALES:
        prompt = `Write a compelling, detailed, and high-converting sales Facebook post for: "${request.topic}". 
        Context: ${request.additionalContext || "None"}.
        Use the AIDA (Attention, Interest, Desire, Action) framework. Build significant value by describing the package features, the hospital's reputation, and Shwe Thai's seamless travel/logistics support. Ensure the benefits are articulated clearly for the Myanmar audience.`;
        break;
      case ToolType.AD_COPY:
        prompt = `Write three variations of highly effective Facebook Ad Copy for: "${request.topic}". 
        Include: 
        1. A long-form storytelling variation focusing on a patient's journey.
        2. A benefit-focused variation highlighting safety and insurance.
        3. A direct, short-form urgency variation.
        Provide headlines and primary text for each.`;
        break;
      default:
        prompt = request.topic;
    }

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Content Gen Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: `Expand and enhance this content to be much more detailed, professional, and comprehensive. Ensure it highlights Shwe Thai's expertise in Medical Travel Logistics and hospital coordination. REMEMBER: We do not deliver medicine. Add depth to the explanations and more relevant emojis: ${originalContent}` }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    } catch (error) {
       throw error;
    }
  }

  async generateImage(
    prompt: string, 
    aspectRatio: any = '1:1',
    negativePrompt?: string,
    stylePreset?: string,
    mood?: string,
    context?: string,
    isHighQuality: boolean = false
  ): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

    let finalPrompt = `Professional marketing photography for Shwe Thai Medical Tourism. 
    Subject: ${prompt.trim()}. Mood: ${mood || 'professional'}. Style: ${stylePreset || 'photorealistic'}. Context: ${context || ''}`;

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ parts: [{ text: finalPrompt }] }],
        config: {
          imageConfig: { 
            aspectRatio: aspectRatio,
            ...(isHighQuality ? { imageSize: "1K" } : {})
          }
        }
      });

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }
      throw new Error("No image data returned.");
    } catch (error: any) {
      throw error;
    }
  }

  async sendMessage(message: string, history: Message[] = []): Promise<string> {
    const ai = this.getAIInstance();
    const contents = history.map(m => ({
      role: m.role === 'model' ? 'model' : 'user' as any,
      parts: [{ text: m.text }]
    }));

    contents.push({ role: 'user', parts: [{ text: message }] });

    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: contents,
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT + "\n\nProvide detailed, advisory responses with strategic depth. Strictly enforce the rule that Shwe Thai does not provide medicine home delivery." },
      });
      return response.text || "";
    } catch (error) {
      console.error("Chat Error:", error);
      throw error;
    }
  }
}

