const SYSTEM_INSTRUCTION_TEXT = `
You are the Chief Marketing Officer (CMO) and Strategic Consultant for "Shwe Thai" (shwethai.com).

**Brand Profile:**
- **Core Service:** Connecting Myanmar patients with world-class hospitals in Thailand (Medical Tourism).
- **USP:** Safety, Transparency, Peace of Mind (စိတ်အေးချမ်းသာမှု), and Ease of Access.
- **Target Audience:** Myanmar citizens seeking better healthcare. They value trust above price.

**CRITICAL RESTRICTION:**
- **NO MEDICINE DELIVERY:** Shwe Thai does NOT provide medicine home delivery services. 
- **ဆေးဝါးများကို အိမ်အရောက် ပို့ဆောင်ပေးခြင်း လုံးဝ(လုံးဝ) မလုပ်ပါ။** 

**TikTok Scriptwriting Rules:**
- Focus on high-engagement visual storytelling.
- Format: [Scene Description] | [Audio/Music] | [Spoken Text].
- Include a 3-second "Hook" to grab attention.
- Use professional yet approachable Burmese.

**Content Quality:**
- **Depth over Brevity:** Always prioritize providing detailed, comprehensive information.
- **Explain the "Why":** Explain medical benefits and Shwe Thai's value.
- **Structure:** Use headers, bullet points, and bold text.
- **CTA:** Always end with a clear call-to-action to shwethai.com or Messenger.
`;

class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel();
    const platform = request.platform || "Facebook";

    let prompt = "";
    switch (request.tool) {
      case ToolType.TIKTOK_SCRIPT:
        prompt = `Write a professional TikTok/Reels Video Script for Shwe Thai about: "${request.topic}".
        Context: ${request.additionalContext || "None"}.
        The script MUST include:
        1. Visual Scene descriptions in brackets [Scene: ...].
        2. Suggested background music cues.
        3. Spoken Burmese text that sounds natural and professional.
        4. Clear timestamps or scene durations.
        5. Engaging medical advice/highlights of Shwe Thai services.`;
        break;
      case ToolType.STRATEGY:
        prompt = `Develop a detailed multi-channel marketing strategy for: "${request.topic}". 
        Include Objectives, KPIs, Channel-specific plans for FB/TikTok/Viber, and a 4-week implementation roadmap.`;
        break;
      case ToolType.CONTENT_BUILDER:
        if (request.subType === ContentSubType.EDUCATIONAL) {
          prompt = `Write a deep-dive educational post for ${platform} about: "${request.topic}". Explain the medical value and Shwe Thai coordination.`;
        } else if (request.subType === ContentSubType.SALES) {
          prompt = `Write a compelling sales post for ${platform} about: "${request.topic}". Use AIDA framework and highlight ease of medical travel with Shwe Thai.`;
        } else {
          prompt = `Write 3 variations of Ad Copy for ${platform} about: "${request.topic}". High impact and clear CTA.`;
        }
        break;
      default:
        prompt = request.topic;
    }

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Content Gen Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: `Expand and enhance this content for Shwe Thai. REMEMBER: No medicine delivery. ${originalContent}` }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    } catch (error) {
       throw error;
    }
  }

  async generateImage(prompt: string, aspectRatio: any = '1:1', negativePrompt?: string, stylePreset?: string, mood?: string, context?: string, isHighQuality: boolean = false): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
    let finalPrompt = `Professional marketing photography for Shwe Thai Medical Tourism. Subject: ${prompt.trim()}. Mood: ${mood || 'professional'}. Style: ${stylePreset || 'photorealistic'}. Context: ${context || ''}`;
    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ parts: [{ text: finalPrompt }] }],
        config: { imageConfig: { aspectRatio: aspectRatio, ...(isHighQuality ? { imageSize: "1K" } : {}) } }
      });
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data returned.");
    } catch (error: any) { throw error; }
  }

  async sendMessage(message: string, history: Message[] = []): Promise<string> {
    const ai = this.getAIInstance();
    const contents = history.map(m => ({ role: m.role === 'model' ? 'model' : 'user' as any, parts: [{ text: m.text }] }));
    contents.push({ role: 'user', parts: [{ text: message }] });
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: contents,
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT + "\n\nProvide detailed advice on TikTok trends, Viber engagement, and Telegram community growth strategy." },
      });
      return response.text || "";
    } catch (error) { throw error; }
  }
}

export const geminiService = new GeminiService();

