                  {cIdx === 1 ? <span className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Visual</span> : null}
                  {cIdx === 2 ? <span className="text-[10px] uppercase font-bold text-gray-400 block mb-1">Audio</span> : null}
                  {formatLine(col.trim())}
                </div>
              ))}
            </div>
          );
        }

        // Scene/Script formatting generic
        if (trimmed.startsWith('[') && trimmed.includes(']')) {
          return (
            <div key={idx} className="bg-gray-50 border-l-4 border-shwe-gold p-3 my-4 rounded-r-lg italic text-gray-800 text-base shadow-sm">
              {formatLine(trimmed)}
            </div>
          );
        }

        if (trimmed === '') return <div key={idx} className="h-4" />;

        // Visual Section block
        if (inVisualSection) {
          return (
            <div key={idx} className="bg-thai-50/30 border-l-4 border-thai-200 p-4 my-2 rounded-r-lg italic text-thai-900 text-base">
              {formatLine(paragraph)}
            </div>
          );
        }

        return <p key={idx} className="mb-4 text-gray-800">{formatLine(paragraph)}</p>;
      })}
    </div>
  );
};

const formatLine = (line: string) => {
  // Split by bold markers
  const parts = line.split(/(\*\*.*?\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i} className="font-bold text-gray-950">{part.slice(2, -2)}</strong>;
    }
    return part;
  });
};

