`;

class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private getModel() {
    return 'gemini-3-pro-preview';
  }

  private getLengthInstruction(length: ContentLength = ContentLength.AUTO, tool: ToolType): string {
    if (length === ContentLength.AUTO) return "";

    if (tool === ToolType.TIKTOK_SCRIPT) {
      switch (length) {
        case ContentLength.SHORT: return "SCRIPT LENGTH: Short (Approx 30 seconds). Keep it punchy and fast-paced.";
        case ContentLength.MEDIUM: return "SCRIPT LENGTH: Medium (Approx 60 seconds). Standard detailed explanation.";
        case ContentLength.LONG: return "SCRIPT LENGTH: Long (Approx 90 seconds). In-depth storytelling and explanation.";
        default: return "";
      }
    }

    // Default for Text Content
    switch (length) {
      case ContentLength.SHORT: return "CONTENT LENGTH: Concise/Short (Under 150 words). Focus on high impact and brevity.";
      case ContentLength.MEDIUM: return "CONTENT LENGTH: Standard/Medium (Approx 300 words). Balanced detail and readability.";
      case ContentLength.LONG: return "CONTENT LENGTH: Long-form/Detailed (Over 500 words). Comprehensive deep-dive.";
      default: return "";
    }
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel();
    const platform = request.platform || "Facebook";
    const lengthInstruction = this.getLengthInstruction(request.length, request.tool);

    let prompt = "";
    switch (request.tool) {
      case ToolType.TIKTOK_SCRIPT:
        prompt = `Write a PROFESSIONAL Human-Presenter TikTok/Reels Script for Shwe Thai.
        Topic: "${request.topic}".
        Additional Context: ${request.additionalContext || "None"}.
        ${lengthInstruction}

        Requirements:
        1. Tone: Expert, trustworthy, and empathetic.
        2. Spoken Content: Pure Burmese paragraphs (No English mixing).
        3. Visual Storyboard: Use polite "...ပါမယ်" endings (e.g., "...ပြသပါမယ်").
        4. CTA: Must end with a call to visit shwethai.com.
        5. Formatting: DO NOT use double asterisks (**) for any text. Use plain text for headers.

        Structure your response exactly like this:

        ၁။ ဗီဒီယို ဇာတ်ညွှန်း (Spoken Script for Presenter)
        (Write the full dialogue here in clear, logical Burmese paragraphs. Use plain text labels for segments.)
        စတင်ဆွဲဆောင်မှု (Hook): 
        (Content...)

        အဓိက အကြောင်းအရာ (Core Content): 
        (Content...)

        ရွှေထိုင်း၏ ဝန်ဆောင်မှု (The Solution): 
        (Highlight that Shwe Thai is a Health Partner arranging appointments AND hotels/accommodation together - ဟိုတယ်ပါ တစ်ပါတည်းစီစဉ်ပေးခြင်း...)

        နောက်ဆုံး တိုက်တွန်းချက် (CTA): 
        (Must include: "အသေးစိတ်သိရှိလိုပါက shwethai.com တွင် ဝင်ရောက်ကြည့်ရှုနိုင်ပါတယ်")

        ၂။ ရုပ်ပုံနှင့် တည်းဖြတ်မှု အကြံပြုချက်များ (Visual Storyboard)
        (List instructions here using polite endings like "...ပါမယ်".)
        - Scene 1: ...
        - Scene 2: ...
        - Text Overlays: ...

        ၃။ ထုတ်လုပ်ရေး မှတ်စု (Production Notes)
        - Music: ...
        - Hashtags: #ShweThai #MedicalTourism #ThailandHealthcare #HealthTips

        REMINDER: NO HTML. NO DOUBLE ASTERISKS (**). Pure professional Burmese script.`;
        break;
      case ToolType.STRATEGY:
        prompt = `Develop a detailed multi-channel marketing strategy for: "${request.topic}". 
        Include Objectives, KPIs, Channel-specific plans for FB/TikTok/Viber, and a 4-week implementation roadmap.
        ${lengthInstruction}
        REMINDER: Do not use HTML or double asterisks (**).`;
        break;
      case ToolType.CONTENT_BUILDER:
        if (request.subType === ContentSubType.EDUCATIONAL) {
          prompt = `Write a deep-dive educational post for ${platform} about: "${request.topic}". Explain the medical value and Shwe Thai coordination.
          ${lengthInstruction}
          REMINDER: Do not use HTML or double asterisks (**).`;
        } else if (request.subType === ContentSubType.SALES) {
          prompt = `Write a compelling sales post for ${platform} about: "${request.topic}". Use AIDA framework and highlight ease of medical travel with Shwe Thai (including hotel arrangements).
          ${lengthInstruction}
          REMINDER: Do not use HTML or double asterisks (**).`;
        } else {
          prompt = `Write 3 variations of Ad Copy for ${platform} about: "${request.topic}". High impact and clear CTA.
          ${lengthInstruction}
          REMINDER: Do not use HTML or double asterisks (**).`;
        }
        break;
      default:
        prompt = request.topic;
    }

    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    } catch (error) {
      console.error("Content Gen Error:", error);
      throw error;
    }
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: `Expand and enhance this content for Shwe Thai. Focus on high-clarity script structure, professional human dialogue, and shwethai.com CTA. Use polite "...ပါမယ်" endings for visual cues. NO HTML. NO DOUBLE ASTERISKS (**). REMEMBER: No medicine delivery. We are Health Partners (Official Company), arranging Hotels & Care. ${originalContent}` }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    } catch (error) {
       throw error;
    }
  }

  async generateImage(prompt: string, aspectRatio: any = '1:1', negativePrompt?: string, stylePreset?: string, mood?: string, context?: string, isHighQuality: boolean = false): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-preview' : 'gemini-2.5-flash-image';
    let finalPrompt = `Professional marketing photography for Shwe Thai Medical Tourism. Subject: ${prompt.trim()}. Mood: ${mood || 'professional'}. Style: ${stylePreset || 'photorealistic'}. Context: ${context || ''}`;
    try {
      const response = await ai.models.generateContent({
        model,
        contents: [{ parts: [{ text: finalPrompt }] }],
        config: { imageConfig: { aspectRatio: aspectRatio, ...(isHighQuality ? { imageSize: "1K" } : {}) } }
      });
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data returned.");
    } catch (error: any) { throw error; }
  }

  async sendMessage(message: string, history: Message[] = []): Promise<string> {
    const ai = this.getAIInstance();
    const contents = history.map(m => ({ role: m.role === 'model' ? 'model' : 'user' as any, parts: [{ text: m.text }] }));
    contents.push({ role: 'user', parts: [{ text: message }] });
    try {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: contents,
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT + "\n\nProvide detailed advice on TikTok trends, Viber engagement, and Telegram community growth strategy. Do not use HTML or double asterisks (**)." },
      });
      return response.text || "";
    } catch (error) { throw error; }
  }
}

