                          value={length} 
                          onChange={(e) => updateCurrentToolState({ length: e.target.value as ContentLength })}
                          className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-thai-500"
                        >
                          {Object.values(ContentLength).map(l => <option key={l} value={l}>{l}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Audience Segment</label>
                        <input type="text" value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} placeholder="e.g. Retired patients" className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-thai-500" />
                      </div>
                    </div>
                  )}
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Specific Constraints</label>
                    <textarea value={context} onChange={(e) => updateCurrentToolState({ context: e.target.value })} rows={2} placeholder="Visa info, prices, etc." className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg resize-none outline-none focus:ring-1 focus:ring-thai-500" />
                  </div>
               </div>
             )}
          </div>

          <button onClick={handleGenerate} disabled={!topic.trim() || isGenerating} className="w-full py-4 bg-thai-600 text-white rounded-xl font-bold shadow-lg hover:bg-thai-700 transition-all disabled:bg-gray-300 transform active:scale-95">
             {isGenerating ? 'AI is Crafting...' : 'Build Content'}
          </button>
        </div>
      </div>

      <div className="lg:col-span-8 bg-white rounded-2xl shadow-sm border border-gray-200 flex flex-col min-h-[500px] overflow-hidden">
        {isGenerating ? (
          <div className="flex-1 flex flex-col items-center justify-center p-12">
             <div className="w-16 h-16 border-4 border-thai-100 border-t-thai-600 rounded-full animate-spin mb-4"></div>
             <p className="text-gray-500 font-medium animate-pulse">Consulting Shwe Thai brand strategy...</p>
          </div>
        ) : generatedContent ? (
          <div className="flex-1 flex flex-col">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
               <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{platform} PREVIEW</span>
                  {subType && <span className="px-2 py-0.5 bg-thai-100 text-thai-700 text-[10px] font-bold rounded uppercase">{subType}</span>}
                  {length && length !== ContentLength.AUTO && <span className="px-2 py-0.5 bg-gray-100 text-gray-600 text-[10px] font-bold rounded uppercase">{length}</span>}
               </div>
               <button onClick={() => { navigator.clipboard.writeText(generatedContent!); setCopiedId('main'); setTimeout(() => setCopiedId(null), 2000); }} className="px-3 py-1.5 text-xs font-bold text-thai-600 border border-thai-200 rounded-lg hover:bg-white">{copiedId === 'main' ? 'Copied!' : 'Copy Draft'}</button>
            </div>
            <div className="p-8 overflow-y-auto">
              <FormattedText text={generatedContent} />
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-12 text-center">
            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mb-4">
              <svg className="w-10 h-10 text-gray-200" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h10a2 2 0 012 2v1m2 13a2 2 0 01-2-2V7m2 13a2 2 0 002-2V9a2 2 0 00-2-2h-2m-4-3H9M7 16h6M7 8h6v4H7V8z" /></svg>
            </div>
            <p className="font-bold text-gray-400 uppercase tracking-wider text-sm mb-1">Preview Studio Empty</p>
            <p className="text-xs text-gray-400">Configure your parameters and click "Build Content" to start.</p>
          </div>
        )}
      </div>
    </div>
  );

  const renderChat = () => (
    <div className="flex flex-col h-[calc(100vh-8rem)] bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="px-6 py-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-thai-600 flex items-center justify-center text-white font-bold">CMO</div>
          <div><h3 className="text-sm font-bold text-gray-900">CMO Strategy Consultant</h3><p className="text-[10px] text-green-600 font-bold uppercase">Active Advisor</p></div>
        </div>
        <button onClick={() => setChatMessages([])} className="text-xs font-bold text-gray-400 hover:text-red-500 uppercase">Reset Session</button>
      </div>
      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-[#FDFDFD] custom-scrollbar">
        {chatMessages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-full text-center opacity-30">
            <svg className="w-16 h-16 text-thai-200 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" strokeWidth={1}/></svg>
            <p className="text-sm font-bold uppercase tracking-widest text-gray-500">How can I help you scale Shwe Thai today?</p>
          </div>
        )}
        {chatMessages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] px-5 py-4 rounded-2xl shadow-sm border ${msg.role === 'user' ? 'bg-thai-600 text-white border-thai-700 rounded-tr-none' : 'bg-white text-gray-800 border-gray-100 rounded-tl-none'}`}>
              <div className={msg.role === 'user' ? 'text-white text-sm' : 'prose prose-sm prose-slate'}><FormattedText text={msg.text} /></div>
            </div>
          </div>
        ))}
        {isChatLoading && <div className="flex justify-start"><div className="bg-white border border-gray-100 px-5 py-3 rounded-2xl animate-pulse">AI is thinking...</div></div>}
        <div ref={chatEndRef} />
      </div>
      <div className="p-4 bg-white border-t border-gray-100">
        <div className="relative max-w-4xl mx-auto flex gap-3">
          <input value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendChatMessage()} placeholder="Ask for TikTok trends, hospital news, or strategy advice..." className="flex-1 px-5 py-4 bg-gray-50 border border-gray-200 rounded-2xl focus:border-thai-500 outline-none text-sm"/>
          <button onClick={handleSendChatMessage} disabled={!chatInput.trim() || isChatLoading} className="p-4 bg-thai-600 text-white rounded-2xl shadow-md disabled:bg-gray-300"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/></svg></button>
        </div>
      </div>
    </div>
  );

  return showLanding ? <LandingPage onStart={(tool) => { if(tool) setActiveTool(tool); setShowLanding(false); }} /> : (
    <Layout activeTool={activeTool} onToolChange={setActiveTool} onBackHome={() => setShowLanding(true)}>
      {activeTool === ToolType.CONSULTATION ? renderChat() : activeTool === ToolType.CALENDAR ? <ContentCalendar posts={scheduledPosts} onDeletePost={(id) => setScheduledPosts(p => p.filter(x => x.id !== id))} /> : activeTool === ToolType.SAVED_CONTENT ? <SavedContentRepo items={savedContent} onDelete={() => {}} onSchedule={() => {}} onViewImage={() => {}} onUpdate={() => {}} /> : renderGenerator()}
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ToolType, ContentSubType, GenerationRequest, Message, StoredImage, ImageAspectRatio, ScheduledPost, SavedContentItem, Platform, ContentLength } from './types';
import { geminiService } from './services/geminiService';
import FormattedText from './components/MarkdownRenderer';
import { SavedContentRepo } from './components/SavedContentRepo';
import { ContentCalendar } from './components/ContentCalendar';
import { LandingPage } from './components/LandingPage';

const SAVED_CONTENT_KEY = 'SHWETHAI_SAVED_CONTENT';
const CALENDAR_KEY = 'SHWETHAI_CALENDAR';
const HISTORY_KEY = 'SHWETHAI_RECENT_HISTORY';
const CHAT_KEY = 'SHWETHAI_CHAT_HISTORY';

const STYLE_PRESETS = [
  { id: 'none', label: 'None (Default)' },
  { id: 'photorealistic', label: 'Photorealistic' },
  { id: 'cinematic', label: 'Cinematic Movie' },
  { id: 'digital-art', label: 'Digital Illustration' },
  { id: 'medical-illustration', label: 'Medical Illustration' },
  { id: 'studio-professional', label: 'Studio Professional' },
];

const MOOD_PRESETS = [
  { id: 'none', label: 'Auto (Default)' },
  { id: 'clinical-bright', label: 'Clinical & Bright' },
  { id: 'warm-reassuring', label: 'Warm & Reassuring' },
  { id: 'modern-tech', label: 'Modern & Tech' },
];

interface ToolState {
  topic: string;
  audience: string;
  context: string;
  platform: Platform;
  subType: ContentSubType;
  generatedContent: string | null;
  generatedImage: string | null;
  negativePrompt: string;
  stylePreset: string;
  length: ContentLength;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  platform: 'Facebook',
  subType: ContentSubType.EDUCATIONAL,
  generatedContent: null,
  generatedImage: null,
  negativePrompt: '',
  stylePreset: 'none',
  length: ContentLength.AUTO
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.CONTENT_BUILDER);
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});
  const [recentHistory, setRecentHistory] = useState<Record<string, SavedContentItem[]>>({});
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const getCurrentToolState = () => toolStates[activeTool] || INITIAL_TOOL_STATE;

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, platform, subType, generatedContent, generatedImage, negativePrompt, stylePreset, length } = getCurrentToolState();

  useEffect(() => {
    try {
      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));
      const savedHistory = localStorage.getItem(HISTORY_KEY);
      if (savedHistory) setRecentHistory(JSON.parse(savedHistory));
      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));
      const savedChat = localStorage.getItem(CHAT_KEY);
      if (savedChat) setChatMessages(JSON.parse(savedChat));
    } catch (e) { console.error("Load failed", e); }
  }, []);

  useEffect(() => { localStorage.setItem(CHAT_KEY, JSON.stringify(chatMessages)); }, [chatMessages]);
  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatMessages]);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setIsGenerating(true);
    setLoadingProgress(0);
    updateCurrentToolState({ generatedContent: null, generatedImage: null });
    const progressInterval = setInterval(() => setLoadingProgress(p => p >= 90 ? p : p + 5), 500);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;
      if (activeTool === ToolType.IMAGE_GENERATION) {
        imageResult = await geminiService.generateImage(topic, aspectRatio, negativePrompt, stylePreset, audience, context, imageQuality === 'High');
      } else {
        const request: GenerationRequest = { tool: activeTool, subType, topic, audience, platform, additionalContext: context, length };
        contentResult = await geminiService.generateContent(request);
      }
      updateCurrentToolState({ generatedContent: contentResult, generatedImage: imageResult });

      // Auto-save to history logic could go here
    } catch (error: any) {
      updateCurrentToolState({ generatedContent: activeTool !== ToolType.IMAGE_GENERATION ? "Generation failed. Try again." : null });
      if (activeTool === ToolType.IMAGE_GENERATION) {
          alert("Image generation failed. Please try again.");
      }
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleEnhance = async () => {
    if (!generatedContent || isGenerating) return;
    setIsGenerating(true);
    try {
      const enhanced = await geminiService.enhanceContent(generatedContent);
      updateCurrentToolState({ generatedContent: enhanced });
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSaveToGallery = () => {
      if (generatedImage) {
          const newItem: SavedContentItem = {
              id: Date.now().toString(),
              type: ToolType.IMAGE_GENERATION,
              image: generatedImage,
              prompt: topic,
              timestamp: Date.now(),
              status: 'Unscheduled'
          };
          const updated = [newItem, ...savedContent];
          setSavedContent(updated);
          localStorage.setItem(SAVED_CONTENT_KEY, JSON.stringify(updated));
          alert("Image saved to Gallery!");
      }
  };

  const handleSendChatMessage = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: Message = { role: 'user', text: chatInput, timestamp: new Date() };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.sendMessage(userMsg.text, chatMessages);
      setChatMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
    } catch (error) {
      setChatMessages(prev => [...prev, { role: 'model', text: "Chat error occurred.", timestamp: new Date() }]);
    } finally { setIsChatLoading(false); }
  };

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200 h-fit sticky top-6 overflow-hidden">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100">
          <h2 className="text-lg font-bold text-gray-900">{activeTool}</h2>
          <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest mt-1">Multi-Channel Creative Engine</p>
        </div>
        <div className="p-6 space-y-6">
          {/* Sub-type Selection for Content Builder */}
          {activeTool === ToolType.CONTENT_BUILDER && (
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">Project Goal</label>
              <div className="flex bg-gray-100 p-1 rounded-xl">
                {Object.values(ContentSubType).map(t => (
                  <button 
                    key={t}
                    onClick={() => updateCurrentToolState({ subType: t })}
                    className={`flex-1 py-2 text-[11px] font-bold rounded-lg transition-all ${subType === t ? 'bg-white text-thai-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                  >
                    {t}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Platform Selection */}
          {(activeTool === ToolType.CONTENT_BUILDER || activeTool === ToolType.STRATEGY) && (
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">Target Platform</label>
              <div className="grid grid-cols-2 gap-2">
                {['Facebook', 'TikTok', 'Viber', 'Telegram'].map(p => (
                  <button 
                    key={p} 
                    onClick={() => updateCurrentToolState({ platform: p as Platform })}
                    className={`px-3 py-2 rounded-lg text-xs font-bold border transition-all ${platform === p ? 'bg-thai-600 text-white border-thai-600 shadow-md' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div>
            <label className="block text-xs font-bold text-gray-700 uppercase mb-2">Topic or Subject</label>
            <textarea
              value={topic}
              onChange={(e) => updateCurrentToolState({ topic: e.target.value })}
              placeholder={activeTool === ToolType.TIKTOK_SCRIPT ? "e.g. 5 steps to dental implants" : "e.g. Health screening packages"}
              rows={3}
              className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl focus:border-thai-500 outline-none text-sm transition-all"
            />
          </div>

          <div className="border border-gray-100 rounded-xl overflow-hidden">
             <button onClick={() => setShowSettings(!showSettings)} className="w-full px-4 py-3 bg-gray-50 flex items-center justify-between text-xs font-bold text-gray-500 uppercase">
               <span>Advanced Logistics</span>
               <svg className={`w-4 h-4 transition-transform ${showSettings ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M19 9l-7 7-7-7" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" /></svg>
             </button>
             {showSettings && (
               <div className="p-4 bg-white space-y-4">
                  {activeTool === ToolType.IMAGE_GENERATION ? (
                     <div className="space-y-4">
                        <div className="grid grid-cols-2 gap-3">
                           <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Format</label>
                              <select value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                 {Object.entries(ImageAspectRatio).map(([k, v]) => <option key={k} value={v}>{k.replace(/_/g, ' ')} ({v})</option>)}
                              </select>
                           </div>
                           <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Quality</label>
                              <select value={imageQuality} onChange={(e) => setImageQuality(e.target.value)} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                 <option value="Standard">Standard (Fast)</option>
                                 <option value="High">High (HD)</option>
                              </select>
                           </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Style</label>
                              <select value={stylePreset} onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                  {STYLE_PRESETS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                              </select>
                            </div>
                            <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Mood</label>
                              <select value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                  {MOOD_PRESETS.map(m => <option key={m.id} value={m.id}>{m.label}</option>)}
                              </select>
                            </div>
                        </div>
                     </div>
                  ) : (
                    <div>
                      <div className="mb-4">
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Content Length</label>
                        <select 
                          value={length} 
                          onChange={(e) => updateCurrentToolState({ length: e.target.value as ContentLength })}
                          className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-thai-500"
                        >
                          {Object.values(ContentLength).map(l => <option key={l} value={l}>{l}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Audience Segment</label>
                        <input type="text" value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} placeholder="e.g. Retired patients" className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-thai-500" />
                      </div>
                    </div>
                  )}
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Specific Constraints</label>
                    <textarea value={context} onChange={(e) => updateCurrentToolState({ context: e.target.value })} rows={2} placeholder="Visa info, prices, etc." className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg resize-none outline-none focus:ring-1 focus:ring-thai-500" />
                  </div>
               </div>
             )}
          </div>

          <button onClick={handleGenerate} disabled={!topic.trim() || isGenerating} className="w-full py-4 bg-thai-600 text-white rounded-xl font-bold shadow-lg hover:bg-thai-700 transition-all disabled:bg-gray-300 transform active:scale-95">
             {isGenerating ? 'AI is Crafting...' : 'Build Content'}
          </button>
        </div>
      </div>

      <div className="lg:col-span-8 bg-white rounded-2xl shadow-sm border border-gray-200 flex flex-col min-h-[500px] overflow-hidden">
        {isGenerating ? (
          <div className="flex-1 flex flex-col items-center justify-center p-12">
             <div className="w-16 h-16 border-4 border-thai-100 border-t-thai-600 rounded-full animate-spin mb-4"></div>
             <p className="text-gray-500 font-medium animate-pulse">
                {activeTool === ToolType.IMAGE_GENERATION ? 'Visualizing concept...' : 'Consulting Shwe Thai brand strategy...'}
             </p>
          </div>
        ) : generatedContent ? (
          <div className="flex-1 flex flex-col">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
               <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{platform} PREVIEW</span>
                  {subType && <span className="px-2 py-0.5 bg-thai-100 text-thai-700 text-[10px] font-bold rounded uppercase">{subType}</span>}
                  {length && length !== ContentLength.AUTO && <span className="px-2 py-0.5 bg-gray-100 text-gray-600 text-[10px] font-bold rounded uppercase">{length}</span>}
               </div>
               <div className="flex gap-2">
                 <button onClick={handleEnhance} className="px-3 py-1.5 text-xs font-bold text-purple-600 border border-purple-200 rounded-lg hover:bg-white flex items-center gap-1">
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                    Enhance
                 </button>
                 <button onClick={() => { navigator.clipboard.writeText(generatedContent!); setCopiedId('main'); setTimeout(() => setCopiedId(null), 2000); }} className="px-3 py-1.5 text-xs font-bold text-thai-600 border border-thai-200 rounded-lg hover:bg-white">{copiedId === 'main' ? 'Copied!' : 'Copy Draft'}</button>
               </div>
            </div>
            <div className="p-8 overflow-y-auto">
              <FormattedText text={generatedContent} />
            </div>
          </div>
        ) : generatedImage ? (
