                 <button onClick={() => { navigator.clipboard.writeText(generatedContent!); setCopiedId('main'); setTimeout(() => setCopiedId(null), 2000); }} className="px-3 py-1.5 text-xs font-bold text-thai-600 border border-thai-200 rounded-lg hover:bg-white">{copiedId === 'main' ? 'Copied!' : 'Copy'}</button>
