                   <button onClick={() => handleSaveToGallery()} className="px-3 py-1.5 text-xs font-bold text-thai-600 border border-thai-200 rounded-lg hover:bg-white">Save to Gallery</button>
                </div>
                <div className="flex-1 p-8 flex items-center justify-center bg-gray-100/50">
                    <img src={generatedImage} alt="Generated" className="max-h-full max-w-full rounded-xl shadow-lg object-contain" />
                </div>
            </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-12 text-center">
            <p className="font-bold text-gray-400 uppercase tracking-wider text-sm">Preview Studio Empty</p>
          </div>
        )}
      </div>
    </div>
  );

  return showLanding ? <LandingPage onStart={(tool, sub) => { if(tool) setActiveTool(tool); if(sub) updateCurrentToolState({ subType: sub }); setShowLanding(false); }} /> : (
    <Layout activeTool={activeTool} onToolChange={setActiveTool} onBackHome={() => setShowLanding(true)}>
      {activeTool === ToolType.CONSULTATION ? renderChat() : activeTool === ToolType.CALENDAR ? <ContentCalendar posts={scheduledPosts} onDeletePost={(id) => { const updated = scheduledPosts.filter(p => p.id !== id); setScheduledPosts(updated); saveToStorage(CALENDAR_KEY, updated); }} /> : activeTool === ToolType.SAVED_CONTENT ? <SavedContentRepo items={savedContent} onDelete={handleDeleteSaved} onSchedule={handleScheduleSaved} onViewImage={() => {}} onUpdate={handleUpdateSaved} /> : renderGenerator()}
    </Layout>
  );
};

