**Service Scope (One-Stop Service):**
- We arrange EVERYTHING: Hospital Appointments, Medical Translation, Visa Support, and **Hotel/Accommodation Booking** (ဟိုတယ်နှင့် တည်းခိုနေထိုင်ရေး အစီအစဉ်များ). 
- **Accommodation:** Explicitly mention that we arrange hotels near the hospital so patients don't have to worry. (ဆေးရုံနှင့် နီးစပ်ရာ ဟိုတယ်များကိုပါ တစ်ပါတည်းစီစဉ်ပေးသောကြောင့် လူနာများအနေဖြင့် တည်းခိုနေထိုင်ရေးအတွက် ပူပန်စရာမလိုပါ။)

**CRITICAL RESTRICTIONS:**
- **NO HTML TAGS:** Strictly DO NOT use HTML tags like <br>, <div>, or <span>. Use only plain text or Markdown.
- **NO DOUBLE ASTERISKS:** Do NOT use double asterisks (**) for formatting. Use plain text headers or numbered lists. စာသားများကို bold လုပ်ရန် (**) များ လုံးဝ အသုံးမပြုပါနှင့်။
`;

class GeminiService {
  // Use a fresh instance with process.env.API_KEY directly as per guidelines
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  // Optimize model selection as per guidelines
  private getModel(tool?: ToolType) {
    if (tool === ToolType.STRATEGY || tool === ToolType.CONSULTATION) {
      return 'gemini-3-pro-preview';
    }
    return 'gemini-3-flash-preview';
  }

  private getLengthInstruction(length: ContentLength = ContentLength.AUTO, tool: ToolType): string {
    if (length === ContentLength.AUTO) return "";
    switch (length) {
      case ContentLength.SHORT: return "CONTENT LENGTH: Concise (Under 150 words).";
      case ContentLength.MEDIUM: return "CONTENT LENGTH: Standard (Approx 300 words).";
      case ContentLength.LONG: return "CONTENT LENGTH: Comprehensive (Over 500 words).";
      default: return "";
    }
  }

  private async retryOperation<T>(operation: () => Promise<T>, maxRetries: number = 5, initialDelay: number = 2000): Promise<T> {
    let lastError: any;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        return await operation();
      } catch (error: any) {
        lastError = error;
        const message = error.message || '';
        const isRateLimit = message.includes('429') || message.includes('Quota') || message.includes('RESOURCE_EXHAUSTED');
        if (isRateLimit && attempt < maxRetries - 1) {
          const delay = initialDelay * Math.pow(2, attempt);
          console.warn(`[Gemini] Rate limit hit. Retrying in ${delay}ms...`);
          await new Promise(resolve => setTimeout(resolve, delay));
          continue;
        }
        throw error;
      }
    }
    throw lastError;
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel(request.tool);
    const platform = request.platform || "Facebook";
    const lengthInstruction = this.getLengthInstruction(request.length, request.tool);

    let prompt = "";
    switch (request.tool) {
      case ToolType.TIKTOK_SCRIPT:
        prompt = `Write a PROFESSIONAL TikTok Script for Shwe Thai. Topic: "${request.topic}". 
        Requirement: Pure Burmese dialogue. Visual storyboard with "...ပါမယ်" endings. CTA: shwethai.com. NO **.`;
        break;
      case ToolType.STRATEGY:
        prompt = `Develop a multi-channel marketing strategy for: "${request.topic}". Include Roadmap and KPIs. NO **.`;
        break;
      case ToolType.CONTENT_BUILDER:
        if (request.subType === ContentSubType.SALES) {
          prompt = `Write a high-converting, deeply empathetic sales post for ${platform} about: "${request.topic}". 

          **Tone Strategy:** 
          - Start with a "Heart Hook": Validate the reader's fear or uncertainty about healthcare.
          - Bridge to "Total Care": Explain how Shwe Thai handles the logistics (Hospital + Hotel + Visa) like family.
          - Transition to "Peace of Mind": Paint a picture of safety and recovery in Thailand.

          ${lengthInstruction}
          NO HTML. NO **. Use natural, warm Burmese flow. Focus on trust over price.`;
        } else if (request.subType === ContentSubType.EDUCATIONAL) {
          prompt = `Write an educational post for ${platform} about: "${request.topic}". Explain medical concepts clearly in Burmese. NO **.`;
        } else {
          prompt = `Write Ad Copy for ${platform} about: "${request.topic}". Punchy and high impact. NO **.`;
        }
        break;
      default:
        prompt = request.topic;
    }

    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      // response.text is a property as per guidelines
      return response.text || "No response generated.";
    });
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    const prompt = `Rewrite this for Shwe Thai with a focus on Natural, Warm Burmese dialogue. 
    Ensure it sounds empathetic and professional. NO **. Original: ${originalContent}`;
    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    });
  }

  async generateImage(prompt: string, aspectRatio: any = '1:1', negativePrompt?: string, stylePreset?: string, mood?: string, context?: string, isHighQuality: boolean = false): Promise<string> {
    const ai = this.getAIInstance();
    // Use correct image models as per guidelines
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
    const moodDesc = mood && mood !== 'none' ? mood.replace(/-/g, ' ') : 'warm, reassuring, professional';
    const styleDesc = stylePreset && stylePreset !== 'none' ? stylePreset.replace(/-/g, ' ') : 'photorealistic';
    const finalPrompt = `Professional Shwe Thai Medical Tourism photography: ${prompt.trim()}. Style: ${styleDesc}. Lighting: ${moodDesc}. Context: ${context || 'Safe hospital environment'}.`;

    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model,
        contents: { parts: [{ text: finalPrompt }] },
        config: { imageConfig: { aspectRatio: aspectRatio, ...(isHighQuality ? { imageSize: "1K" } : {}) } }
      });
      // Iterate through parts to find the image part as per guidelines
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }
      throw new Error("No image data.");
    });
  }

  async sendMessage(message: string, history: Message[] = []): Promise<string> {
    const ai = this.getAIInstance();
    const contents = history.map(m => ({ role: m.role === 'model' ? 'model' : 'user' as any, parts: [{ text: m.text }] }));
    contents.push({ role: 'user', parts: [{ text: message }] });
    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model: this.getModel(ToolType.CONSULTATION),
        contents: contents,
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "";
    });
  }
}

