const SYSTEM_INSTRUCTION_TEXT = `
You are the Chief Marketing Officer (CMO) and Strategic Consultant for "Shwe Thai" (shwethai.com).

**Brand Identity & Core Values:**
- **Who We Are:** We are **Health Partners** (ကျန်းမာရေးမိတ်ဖက်). We are **NOT** a travel agency.
- **Legal Status:** Officially Registered Company in Thailand.
- **USP:** Safety, Transparency, Peace of Mind (စိတ်အေးချမ်းသာမှု).

**TikTok Narration & Voice-over Expertise:**
- You specialize in writing scripts optimized for **narration (Voice-over)**.
- Use **Phonetic Flow**: Write Burmese dialogue that is easy to speak naturally.
- **Narrative Cues**: Use brackets [ ] to indicate tone, pauses, or emotional emphasis (e.g., [နွေးထွေးသောလေသံဖြင့် - With a warm tone], [ခဏရပ်ပါ - Pause]).
- **Pacing**: Ensure the script fits within the requested time limit by controlling sentence length.

**Writing Style & Tone:**
- **Tone:** Warm, Professional, Empathetic, and Trustworthy.
- **Language:** Natural, Flowing Burmese. Avoid robotic translations.

**CRITICAL RESTRICTIONS:**
- **NO HTML TAGS.**
- **NO DOUBLE ASTERISKS (**).** Use plain text headers or numbered lists.
`;

class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private getModel(tool?: ToolType) {
    // GUIDELINE: Use Flash for high-volume tasks like Content Creation and TikTok Scripts to avoid Pro quota limits
    if (tool === ToolType.STRATEGY || tool === ToolType.CONSULTATION) {
      return 'gemini-3-pro-preview';
    }
    return 'gemini-3-flash-preview';
  }

  private getLengthInstruction(length: ContentLength = ContentLength.AUTO, tool: ToolType): string {
    if (length === ContentLength.AUTO) return "";
    switch (length) {
      case ContentLength.SHORT: return tool === ToolType.TIKTOK_SCRIPT ? "LENGTH: 15-30 seconds." : "LENGTH: Under 150 words.";
      case ContentLength.MEDIUM: return tool === ToolType.TIKTOK_SCRIPT ? "LENGTH: 60 seconds." : "LENGTH: Approx 300 words.";
      case ContentLength.LONG: return tool === ToolType.TIKTOK_SCRIPT ? "LENGTH: 90+ seconds." : "LENGTH: Over 500 words.";
      default: return "";
    }
  }

  private async retryOperation<T>(operation: () => Promise<T>, maxRetries: number = 6, initialDelay: number = 3000): Promise<T> {
    let lastError: any;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        return await operation();
      } catch (error: any) {
        lastError = error;
        const message = error.message || '';
        // Capture common quota/rate limit error codes and strings
        const isRateLimit = message.includes('429') || 
                            message.includes('Quota') || 
                            message.includes('RESOURCE_EXHAUSTED') ||
                            message.includes('Resource has been exhausted');

        if (isRateLimit && attempt < maxRetries - 1) {
          const delay = initialDelay * Math.pow(2, attempt); // Exponential backoff
          console.warn(`[Gemini Quota Management] Attempt ${attempt + 1} failed. Retrying in ${delay}ms...`);
          await new Promise(resolve => setTimeout(resolve, delay));
          continue;
        }
        throw error;
      }
    }
    throw lastError;
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel(request.tool);
    const lengthInstruction = this.getLengthInstruction(request.length, request.tool);

    let prompt = "";
    switch (request.tool) {
      case ToolType.TIKTOK_SCRIPT:
        prompt = `Write a PROFESSIONAL TikTok Narration Script for: "${request.topic}".

        **Narration Requirements:**
        1. Pure Burmese dialogue optimized for a professional narrator.
        2. Include [Narration Cues] in Burmese for tone and pauses.
        3. Structure: 
           - Hook (0-5s)
           - Value/Problem (5-20s)
           - Shwe Thai Solution (20-50s)
           - CTA (50-60s)
        4. ${lengthInstruction}
        5. Visual cues: Use "...ပါမယ်" endings.
        6. NO ** formatting.`;
        break;
      case ToolType.STRATEGY:
        prompt = `Develop a multi-channel marketing strategy for: "${request.topic}". Roadmap + KPIs included. NO **.`;
        break;
      case ToolType.CONTENT_BUILDER:
        if (request.subType === ContentSubType.SALES) {
          prompt = `Write a deeply empathetic sales post for ${request.platform || 'Facebook'} about: "${request.topic}". Use AIDA. NO **.`;
        } else {
          prompt = `Write content for ${request.platform || 'Facebook'} about: "${request.topic}". NO **.`;
        }
        break;
      default:
        prompt = request.topic;
    }

    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response generated.";
    });
  }

  // ... (rest of methods remain same but utilize the improved getModel and retryOperation)
  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    const prompt = `Rewrite this content to improve narration flow and natural Burmese dialogue. NO **. Original: ${originalContent}`;
    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    });
  }

  async generateImage(prompt: string, aspectRatio: any = '1:1', negativePrompt?: string, stylePreset?: string, mood?: string, context?: string, isHighQuality: boolean = false): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
    const finalPrompt = `Professional Shwe Thai imagery: ${prompt.trim()}. Style: ${stylePreset}. Mood: ${mood}.`;

    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model,
        contents: { parts: [{ text: finalPrompt }] },
        config: { imageConfig: { aspectRatio: aspectRatio, ...(isHighQuality ? { imageSize: "1K" } : {}) } }
      });
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data.");
    });
  }

  async sendMessage(message: string, history: Message[] = []): Promise<string> {
    const ai = this.getAIInstance();
    const contents = history.map(m => ({ role: m.role === 'model' ? 'model' : 'user' as any, parts: [{ text: m.text }] }));
    contents.push({ role: 'user', parts: [{ text: message }] });
    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model: this.getModel(ToolType.CONSULTATION),
        contents: contents,
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "";
    });
  }
}

