const CALENDAR_KEY = 'SHWETHAI_CALENDAR';
const CHAT_KEY = 'SHWETHAI_CHAT_HISTORY';

const STYLE_PRESETS = [
  { id: 'none', label: 'Auto (Default)' },
  { id: 'photorealistic', label: 'Photorealistic' },
  { id: 'commercial-advertising', label: 'Commercial Ad' },
  { id: 'minimalist-modern', label: 'Minimalist' },
  { id: 'studio-portrait', label: 'Studio Portrait' },
];

const MOOD_PRESETS = [
  { id: 'none', label: 'Auto (Default)' },
  { id: 'calm', label: 'Calm & Peaceful' },
  { id: 'professional', label: 'Professional & Elite' },
  { id: 'hopeful', label: 'Hopeful & Warm' },
  { id: 'luxurious', label: 'Luxurious & Premium' },
  { id: 'clinical-bright', label: 'Clinical & Bright' },
];

interface ToolState {
  topic: string;
  audience: string;
  context: string;
  platform: Platform;
  subType: ContentSubType;
  scriptStyle: ScriptStyle;
  generatedContent: string | null;
  generatedImage: string | null;
  negativePrompt: string;
  stylePreset: string;
  length: ContentLength;
  mood: string;
}

const INITIAL_TOOL_STATE: ToolState = {
  topic: '',
  audience: '',
  context: '',
  platform: 'Facebook',
  subType: ContentSubType.EDUCATIONAL,
  scriptStyle: ScriptStyle.NARRATOR,
  generatedContent: null,
  generatedImage: null,
  negativePrompt: '',
  stylePreset: 'none',
  length: ContentLength.AUTO,
  mood: 'none'
};

const App = () => {
  const [showLanding, setShowLanding] = useState(true);
  const [activeTool, setActiveTool] = useState<ToolType>(ToolType.CONTENT_BUILDER);
  const [toolStates, setToolStates] = useState<Record<string, ToolState>>({});
  const [aspectRatio, setAspectRatio] = useState<string>(ImageAspectRatio.SQUARE);
  const [imageQuality, setImageQuality] = useState<string>('Standard');
  const [showSettings, setShowSettings] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [errorFeedback, setErrorFeedback] = useState<string | null>(null);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [savedContent, setSavedContent] = useState<SavedContentItem[]>([]);
  const [scheduledPosts, setScheduledPosts] = useState<ScheduledPost[]>([]);
  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const getCurrentToolState = () => toolStates[activeTool] || INITIAL_TOOL_STATE;

  const updateCurrentToolState = (updates: Partial<ToolState>) => {
    setToolStates(prev => ({
      ...prev,
      [activeTool]: { ...(prev[activeTool] || INITIAL_TOOL_STATE), ...updates }
    }));
  };

  const { topic, audience, context, platform, subType, scriptStyle, generatedContent, generatedImage, length, mood, stylePreset, negativePrompt } = getCurrentToolState();

  useEffect(() => {
    try {
      const savedContentData = localStorage.getItem(SAVED_CONTENT_KEY);
      if (savedContentData) setSavedContent(JSON.parse(savedContentData));
      const savedPosts = localStorage.getItem(CALENDAR_KEY);
      if (savedPosts) setScheduledPosts(JSON.parse(savedPosts));
      const savedChat = localStorage.getItem(CHAT_KEY);
      if (savedChat) setChatMessages(JSON.parse(savedChat));
    } catch (e) { console.error("Load failed", e); }
  }, []);

  const saveToStorage = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

  useEffect(() => { saveToStorage(CHAT_KEY, chatMessages); }, [chatMessages]);
  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatMessages]);

  const handleGenerate = async () => {
    if (!topic.trim()) return;
    setErrorFeedback(null);

    setIsGenerating(true);
    setLoadingProgress(0);
    updateCurrentToolState({ generatedContent: null, generatedImage: null });
    const progressInterval = setInterval(() => setLoadingProgress(p => p >= 90 ? p : p + 5), 500);

    try {
      let contentResult: string | null = null;
      let imageResult: string | null = null;

      if (activeTool === ToolType.IMAGE_GENERATION) {
        imageResult = await geminiService.generateImage(topic, aspectRatio, negativePrompt, stylePreset, mood, context, imageQuality === 'High');
      } else {
        const request: GenerationRequest = { 
          tool: activeTool, 
          subType, 
          scriptStyle, 
          topic, 
          audience, 
          platform, 
          additionalContext: context, 
          length 
        };
        contentResult = await geminiService.generateContent(request);
      }
      updateCurrentToolState({ generatedContent: contentResult, generatedImage: imageResult });
    } catch (error: any) {
      const msg = error.message || '';
      if (msg.includes('429') || msg.includes('Quota')) {
        setErrorFeedback("Daily limit reached. We are attempting high-quota fallback. Please wait a moment or try again shortly.");
      } else {
        setErrorFeedback("Generation failed. Please check connection.");
      }
    } finally {
      clearInterval(progressInterval);
      setLoadingProgress(100);
      setIsGenerating(false);
    }
  };

  const handleSaveToGallery = (imgData?: string, textData?: string) => {
    const content = textData || generatedContent;
    const image = imgData || generatedImage;
    if (!content && !image) return;

    const newItem: SavedContentItem = {
      id: Date.now().toString(),
      type: activeTool,
      subType,
      content: content || undefined,
      image: image || undefined,
      prompt: topic,
      timestamp: Date.now(),
      status: 'Unscheduled'
    };
    const updated = [newItem, ...savedContent];
    setSavedContent(updated);
    saveToStorage(SAVED_CONTENT_KEY, updated);
    alert("Saved to Repository!");
  };

  const handleUpdateSaved = (id: string, newContent: string) => {
    const updated = savedContent.map(item => item.id === id ? { ...item, content: newContent } : item);
    setSavedContent(updated);
    saveToStorage(SAVED_CONTENT_KEY, updated);
  };

  const handleDeleteSaved = (ids: string[]) => {
    const updated = savedContent.filter(item => !ids.includes(item.id));
    setSavedContent(updated);
    saveToStorage(SAVED_CONTENT_KEY, updated);
  };

  const handleScheduleSaved = (item: SavedContentItem) => {
    const date = prompt("Enter scheduled date (YYYY-MM-DD):", new Date().toISOString().split('T')[0]);
    if (!date) return;

    const newPost: ScheduledPost = {
      id: Date.now().toString(),
      date,
      title: item.prompt,
      content: item.content || "Visual Asset",
      platform: 'Facebook',
      status: 'Scheduled',
      type: item.type
    };

    const updatedPosts = [newPost, ...scheduledPosts];
    setScheduledPosts(updatedPosts);
    saveToStorage(CALENDAR_KEY, updatedPosts);

    const updatedContent = savedContent.map(s => s.id === item.id ? { ...s, status: 'Scheduled', scheduledDate: date } as SavedContentItem : s);
    setSavedContent(updatedContent);
    saveToStorage(SAVED_CONTENT_KEY, updatedContent);
    alert(`Scheduled for ${date}`);
  };

  const handleSendChatMessage = async () => {
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: Message = { role: 'user', text: chatInput, timestamp: new Date() };
    setChatMessages(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.sendMessage(userMsg.text, chatMessages);
      setChatMessages(prev => [...prev, { role: 'model', text: response, timestamp: new Date() }]);
    } catch (error: any) {
      setChatMessages(prev => [...prev, { role: 'model', text: "Service error. Try again later.", timestamp: new Date() }]);
    } finally { setIsChatLoading(false); }
  };

  const renderChat = () => (
    <div className="flex flex-col h-[calc(100vh-160px)] bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="px-6 py-4 border-b border-gray-100 bg-gray-50/50 flex items-center justify-between">
        <div>
          <h2 className="text-lg font-bold text-gray-900">CMO Strategic Consultant</h2>
          <p className="text-xs text-gray-500">Ask about brand strategy or market trends.</p>
        </div>
        <button 
          onClick={() => { if (window.confirm("Clear chat?")) setChatMessages([]); }}
          className="text-xs font-bold text-red-500 hover:bg-red-50 px-3 py-1.5 rounded-lg border border-red-100"
        >
          Clear
        </button>
      </div>
      <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
        {chatMessages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-2xl p-4 ${msg.role === 'user' ? 'bg-thai-600 text-white shadow-md' : 'bg-gray-100 text-gray-800'}`}>
              {msg.role === 'model' ? <FormattedText text={msg.text} /> : <p className="text-sm">{msg.text}</p>}
            </div>
          </div>
        ))}
        {isChatLoading && <p className="text-xs text-gray-400 italic">Thinking...</p>}
        <div ref={chatEndRef} />
      </div>
      <div className="p-4 border-t flex gap-3">
        <textarea
          value={chatInput}
          onChange={(e) => setChatInput(e.target.value)}
          placeholder="Type your question..."
          className="flex-1 bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-thai-500/20 outline-none resize-none"
          rows={1}
        />
        <button onClick={handleSendChatMessage} className="bg-thai-600 text-white p-3 rounded-xl hover:bg-thai-700 shadow-md">
           <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" strokeWidth={2}/></svg>
        </button>
      </div>
    </div>
  );

  const renderGenerator = () => (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
      <div className="lg:col-span-4 bg-white rounded-2xl shadow-sm border border-gray-200 h-fit sticky top-6 overflow-hidden">
        <div className="px-6 py-5 bg-gray-50/50 border-b border-gray-100">
          <h2 className="text-lg font-bold text-gray-900">{activeTool}</h2>
        </div>
        <div className="p-6 space-y-6">
          {activeTool === ToolType.TIKTOK_SCRIPT && (
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">Voice Style</label>
              <div className="flex bg-gray-100 p-1 rounded-xl">
                {Object.values(ScriptStyle).map(s => (
                  <button key={s} onClick={() => updateCurrentToolState({ scriptStyle: s })} className={`flex-1 py-2 text-[10px] font-bold rounded-lg transition-all ${scriptStyle === s ? 'bg-white text-thai-600 shadow-sm' : 'text-gray-500'}`}>{s}</button>
                ))}
              </div>
            </div>
          )}

          {activeTool === ToolType.CONTENT_BUILDER && (
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-2">Content Goal</label>
              <div className="flex bg-gray-100 p-1 rounded-xl">
                {Object.values(ContentSubType).map(t => (
                  <button key={t} onClick={() => updateCurrentToolState({ subType: t })} className={`flex-1 py-2 text-[10px] font-bold rounded-lg transition-all ${subType === t ? 'bg-white text-thai-600 shadow-sm' : 'text-gray-500'}`}>{t}</button>
                ))}
              </div>
            </div>
          )}

          <div>
            <label className="block text-xs font-bold text-gray-700 uppercase mb-2">Topic</label>
            <textarea value={topic} onChange={(e) => updateCurrentToolState({ topic: e.target.value })} placeholder="e.g. Health check-up packages in Bangkok" rows={3} className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl outline-none text-sm"/>
          </div>

          <div className="border border-gray-100 rounded-xl overflow-hidden">
             <button onClick={() => setShowSettings(!showSettings)} className="w-full px-4 py-3 bg-gray-50 flex items-center justify-between text-xs font-bold text-gray-500 uppercase">
               <span>Advanced Settings</span>
               <svg className={`w-4 h-4 transition-transform ${showSettings ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M19 9l-7 7-7-7" strokeWidth={2}/></svg>
             </button>
             {showSettings && (
               <div className="p-4 bg-white space-y-4">
                  {activeTool === ToolType.IMAGE_GENERATION ? (
                     <div className="space-y-4">
                        <div className="grid grid-cols-2 gap-3">
                           <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Format</label>
                              <select value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                 {Object.entries(ImageAspectRatio).map(([k, v]) => <option key={k} value={v}>{k.replace(/_/g, ' ')}</option>)}
                              </select>
                           </div>
                           <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Quality</label>
                              <select value={imageQuality} onChange={(e) => setImageQuality(e.target.value)} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                 <option value="Standard">Standard (Fast)</option>
                                 <option value="High">HD (Paid Tier)</option>
                              </select>
                           </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                           <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Style</label>
                              <select value={stylePreset} onChange={(e) => updateCurrentToolState({ stylePreset: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                 {STYLE_PRESETS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                              </select>
                           </div>
                           <div>
                              <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Mood</label>
                              <select value={mood} onChange={(e) => updateCurrentToolState({ mood: e.target.value })} className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg">
                                 {MOOD_PRESETS.map(m => <option key={m.id} value={m.id}>{m.label}</option>)}
                              </select>
                           </div>
                        </div>
                     </div>
                  ) : (
                    <div>
                      <div className="mb-4">
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Target Audience</label>
                        <input type="text" value={audience} onChange={(e) => updateCurrentToolState({ audience: e.target.value })} placeholder="e.g. Families, Seniors" className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg" />
                      </div>
                    </div>
                  )}
                  <div>
                    <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5">Extra Details</label>
                    <textarea value={context} onChange={(e) => updateCurrentToolState({ context: e.target.value })} rows={2} placeholder="Important facts to include..." className="w-full px-3 py-2 bg-gray-50 text-xs border border-gray-200 rounded-lg resize-none" />
                  </div>
               </div>
             )}
          </div>

          {errorFeedback && <div className="p-3 bg-red-50 text-red-700 text-[11px] font-medium rounded-lg border border-red-100">{errorFeedback}</div>}

          <button onClick={handleGenerate} disabled={!topic.trim() || isGenerating} className="w-full py-4 bg-thai-600 text-white rounded-xl font-bold hover:bg-thai-700 transition-all disabled:bg-gray-300 shadow-lg shadow-thai-500/20">
             {isGenerating ? 'AI is Processing...' : 'Generate Assets'}
          </button>
        </div>
      </div>

      <div className="lg:col-span-8 bg-white rounded-2xl shadow-sm border border-gray-200 flex flex-col min-h-[500px] overflow-hidden">
        {isGenerating ? (
          <div className="flex-1 flex flex-col items-center justify-center p-12">
             <div className="w-16 h-16 border-4 border-thai-100 border-t-thai-600 rounded-full animate-spin mb-4"></div>
             <p className="text-gray-500 font-medium">Drafting Shwe Thai narrative...</p>
          </div>
        ) : generatedContent ? (
          <div className="flex-1 flex flex-col">
            <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
               <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{activeTool} Draft</span>
               <div className="flex gap-2">
                 <button onClick={async () => {
                    setIsGenerating(true);
                    const enhanced = await geminiService.enhanceContent(generatedContent);
                    updateCurrentToolState({ generatedContent: enhanced });
                    setIsGenerating(false);
                 }} className="px-3 py-1.5 text-xs font-bold text-purple-600 border border-purple-200 rounded-lg hover:bg-white">Re-Narrate</button>
                 <button onClick={() => { navigator.clipboard.writeText(generatedContent!); setCopiedId('main'); setTimeout(() => setCopiedId(null), 2000); }} className="px-3 py-1.5 text-xs font-bold text-thai-600 border border-thai-200 rounded-lg hover:bg-white">{copiedId === 'main' ? 'Copied!' : 'Copy Text'}</button>
               </div>
            </div>
            <div className="p-8 overflow-y-auto"><FormattedText text={generatedContent} /></div>
          </div>
        ) : generatedImage ? (
            <div className="flex-1 flex flex-col">
                <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
                   <span className="text-xs font-bold text-gray-400 uppercase">IMAGE PREVIEW</span>
                   <button onClick={() => handleSaveToGallery()} className="px-3 py-1.5 text-xs font-bold text-thai-600 border border-thai-200 rounded-lg hover:bg-white">Save to Gallery</button>
                </div>
                <div className="flex-1 p-8 flex items-center justify-center bg-gray-100/50">
                    <img src={generatedImage} alt="Generated" className="max-h-full max-w-full rounded-xl shadow-lg object-contain" />
                </div>
            </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-300 p-12 text-center opacity-60">
            <svg className="w-20 h-20 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth={1} /></svg>
            <p className="font-bold uppercase tracking-widest text-sm">Preview Studio Empty</p>
          </div>
        )}
      </div>
    </div>
  );

  return showLanding ? <LandingPage onStart={(tool, sub) => { if(tool) setActiveTool(tool); if(sub) updateCurrentToolState({ subType: sub }); setShowLanding(false); }} /> : (
    <Layout activeTool={activeTool} onToolChange={setActiveTool} onBackHome={() => setShowLanding(true)}>
      {activeTool === ToolType.CONSULTATION ? renderChat() : activeTool === ToolType.CALENDAR ? <ContentCalendar posts={scheduledPosts} onDeletePost={(id) => { const updated = scheduledPosts.filter(p => p.id !== id); setScheduledPosts(updated); saveToStorage(CALENDAR_KEY, updated); }} /> : activeTool === ToolType.SAVED_CONTENT ? <SavedContentRepo items={savedContent} onDelete={handleDeleteSaved} onSchedule={handleScheduleSaved} onViewImage={() => {}} onUpdate={handleUpdateSaved} /> : renderGenerator()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Chat } from "@google/genai";
import { ToolType, ContentSubType, GenerationRequest, Message, ContentLength, ScriptStyle } from "../types";

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const SYSTEM_INSTRUCTION_TEXT = `
You are the Chief Marketing Officer (CMO) and Strategic Consultant for "Shwe Thai" (shwethai.com).

**Brand Identity:**
- We are **Health Partners** (ကျန်းမာရေးမိတ်ဖက်). Not just a travel agency.
- Position Shwe Thai as premium, safe, and empathetic.

**Scriptwriting Persona - TikTok Specialist:**
You write scripts in two distinct styles based on user selection:

1. **Narrator Tone (Voice-over):**
   - Focus: Atmospheric storytelling and clinical clarity.
   - Dialogue: Rhythmic and poetic Burmese.
   - Cues: Use [Brackets] for vocal delivery cues (e.g., [နွေးထွေးသောလေသံဖြင့် - Warm tone], [ခဏရပ်ပါ - Pause]).
   - Visuals: Describe cinematic B-roll (Hospital corridors, modern Thai cityscapes, patient smiles).

2. **Presenter Tone (Talking Head):**
   - Focus: Direct engagement, trust, and personality.
   - Dialogue: Conversational "Spoken" Burmese (using "...ပါနော်", "...မလား" endings).
   - Cues: Use [Brackets] for body language and expressions (e.g., [လက်ဟန်ခြေဟန်ဖြင့် ရှင်းပြပါ - Explain with gestures], [ယုံကြည်မှုရှိရှိ ပြုံးပြပါ - Smile confidently]).
   - Visuals: Focus on camera angles and framing (e.g., Medium shot, Close-up).

**CRITICAL RESTRICTIONS:**
- **NO HTML TAGS.**
- **NO DOUBLE ASTERISKS (**).**
- Language: 100% Professional and Warm Burmese.
`;

class GeminiService {
  private getAIInstance() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private getModel(tool?: ToolType) {
    // GUIDELINE: Use Flash for script and content tools to mitigate 429 quota errors.
    // Use Pro only for high-complexity Strategy and Chat.
    if (tool === ToolType.STRATEGY || tool === ToolType.CONSULTATION) {
      return 'gemini-3-pro-preview';
    }
    return 'gemini-3-flash-preview';
  }

  private getLengthInstruction(length: ContentLength = ContentLength.AUTO, tool: ToolType): string {
    if (length === ContentLength.AUTO) return "";
    switch (length) {
      case ContentLength.SHORT: return tool === ToolType.TIKTOK_SCRIPT ? "LENGTH: 15-20 seconds." : "LENGTH: Under 150 words.";
      case ContentLength.MEDIUM: return tool === ToolType.TIKTOK_SCRIPT ? "LENGTH: 45-60 seconds." : "LENGTH: Approx 300 words.";
      case ContentLength.LONG: return tool === ToolType.TIKTOK_SCRIPT ? "LENGTH: 90+ seconds." : "LENGTH: Over 500 words.";
      default: return "";
    }
  }

  private async retryOperation<T>(operation: () => Promise<T>, maxRetries: number = 6, initialDelay: number = 3000): Promise<T> {
    let lastError: any;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        return await operation();
      } catch (error: any) {
        lastError = error;
        const message = error.message || '';
        const isRateLimit = message.includes('429') || message.includes('Quota') || message.includes('RESOURCE_EXHAUSTED');
        if (isRateLimit && attempt < maxRetries - 1) {
          const delay = initialDelay * Math.pow(2, attempt);
          console.warn(`[Gemini Quota] Attempt ${attempt + 1} failed. Retrying in ${delay}ms...`);
          await new Promise(resolve => setTimeout(resolve, delay));
          continue;
        }
        throw error;
      }
    }
    throw lastError;
  }

  async generateContent(request: GenerationRequest): Promise<string> {
    const ai = this.getAIInstance();
    const model = this.getModel(request.tool);
    const lengthInstruction = this.getLengthInstruction(request.length, request.tool);
    const style = request.scriptStyle || ScriptStyle.NARRATOR;

    let prompt = "";
    switch (request.tool) {
      case ToolType.TIKTOK_SCRIPT:
        prompt = `Write a PROFESSIONAL TikTok Script in ${style} style for Shwe Thai.
        Topic: "${request.topic}".
        Target Audience: ${request.audience || 'General patients'}.

        Style Requirements for ${style}:
        ${style === ScriptStyle.NARRATOR ? 
          '- Use [VO Cues] for tone and pauses.\n- Focus on cinematic descriptions of Thailand medical care.\n- Dialogue should be smooth and professional.' :
          '- Use [Performance Cues] for hand gestures and eye contact.\n- Focus on the presenter building a personal connection.\n- Dialogue should be conversational and friendly.'
        }

        ${lengthInstruction}
        CTA: Must direct users to shwethai.com.
        NO **. NO HTML.`;
        break;
      case ToolType.STRATEGY:
        prompt = `Develop a detailed marketing strategy for: "${request.topic}". NO **.`;
        break;
      case ToolType.CONTENT_BUILDER:
        prompt = `Write a ${request.subType} post for ${request.platform} about: "${request.topic}". ${lengthInstruction}. NO **.`;
        break;
      default:
        prompt = request.topic;
    }

    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "No response.";
    });
  }

  async enhanceContent(originalContent: string): Promise<string> {
    const ai = this.getAIInstance();
    const prompt = `Rewrite and polish this content for Shwe Thai. Focus on natural spoken-word flow for Burmese. NO **. Original: ${originalContent}`;
    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model: this.getModel(),
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || originalContent;
    });
  }

  async generateImage(prompt: string, aspectRatio: any = '1:1', negativePrompt?: string, stylePreset?: string, mood?: string, context?: string, isHighQuality: boolean = false): Promise<string> {
    const ai = this.getAIInstance();
    const model = isHighQuality ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';

    // Construct sophisticated visual instructions based on mood
    let moodInstructions = "professional lighting";
    if (mood === 'calm') moodInstructions = "peaceful atmosphere, soft pastel colors, morning light, relaxed environment";
    if (mood === 'professional') moodInstructions = "corporate excellence, sharp focus, clean modern architecture, formal professional attire, high-end commercial look";
    if (mood === 'hopeful') moodInstructions = "optimistic sunlight, warm golden hour tones, smiling expressions, bright and airy composition";
    if (mood === 'luxurious') moodInstructions = "premium high-end aesthetics, 5-star hotel environment, gold and neutral color palette, cinematic depth of field, elegant textures";
    if (mood === 'clinical-bright') moodInstructions = "bright clinical precision, hospital-clean aesthetics, white and blue medical tones, modern medical equipment";

    const finalPrompt = `Premium Shwe Thai Medical Service commercial advertising photography. Subject: ${prompt.trim()}. Style: ${stylePreset || 'photorealistic'}. Lighting and Atmosphere: ${moodInstructions}. Scene Context: ${context || 'Bangkok, Thailand'}. High-end commercial production quality. NO text, NO logos, NO typography. Realistic human features.`;

    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model,
        contents: { parts: [{ text: finalPrompt }] },
        config: { imageConfig: { aspectRatio: aspectRatio, ...(isHighQuality ? { imageSize: "1K" } : {}) } }
      });
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data.");
    });
  }

  async sendMessage(message: string, history: Message[] = []): Promise<string> {
    const ai = this.getAIInstance();
    const contents = history.map(m => ({ role: m.role === 'model' ? 'model' : 'user' as any, parts: [{ text: m.text }] }));
    contents.push({ role: 'user', parts: [{ text: message }] });
    return this.retryOperation(async () => {
      const response = await ai.models.generateContent({
        model: this.getModel(ToolType.CONSULTATION),
        contents: contents,
        config: { systemInstruction: SYSTEM_INSTRUCTION_TEXT },
      });
      return response.text || "";
    });
  }
}

export const geminiService = new GeminiService();
